    private GameMode GetHostedListingGameMode()
    {
        if (_meta != null)
            return _meta.CurrentWorldGameMode;

        return _gameMode;
    }

    public bool TryGetPresenceState(out string worldName, out string gameMode, out bool isMultiplayer)
    {
        worldName = (_meta?.Name ?? _world?.Meta?.Name ?? "WORLD").Trim();
        if (string.IsNullOrWhiteSpace(worldName))
            worldName = "WORLD";

        gameMode = GetHostedListingGameMode().ToString();
        isMultiplayer = _lanSession != null && _lanSession.IsConnected;
        return _hasLoadedWorld && !_worldSyncInProgress && !_isClosing;
    }

