    public GameWorldScreen(MenuStack menus, AssetLoader assets, PixelFont font, Texture2D pixel, Logger log, PlayerProfile profile, global::Microsoft.Xna.Framework.GraphicsDeviceManager graphics, string worldPath, string metaPath, ILanSession? lanSession = null, VoxelWorld? preloadedWorld = null, bool startPaused = false, bool showAttunementWipPopup = false)
    {
        _menus = menus;
        _assets = assets;
        _font = font;
        _pixel = pixel;
        _log = log;
        _profile = profile;
        _onlineGate = OnlineGateClient.GetOrCreate();
        _socialState = OnlineSocialStateService.GetOrCreate(_log);
        _graphics = graphics;
        _worldPath = worldPath;
        _metaPath = metaPath;
        _showAttunementWipPopupOnLoad = showAttunementWipPopup;
        _attunementWipPopupVisible = false;
        _lanSession = lanSession;
        _persistenceSendAccumulator = _lanSession != null && !_lanSession.IsHost
            ? PersistenceSendIntervalSeconds
            : 0f;
        _world = preloadedWorld; // Use preloaded world if available
        _settings = GameSettings.LoadOrCreate(_log);
        _settingsStamp = GetSettingsStamp();
        _targetActiveRadiusChunks = Math.Clamp(_settings.RenderDistanceChunks, 4, MaxRuntimeActiveRadius);
        _activeRadiusChunks = GetInitialActiveRadius(_targetActiveRadiusChunks);
        UpdateReticleSettings();
        ApplyRuntimeInputBindingsFromSettings();
        _indicatorsEnabled = _settings.IndicatorsEnabled;
        _soulMarkerGuidanceEnabled = _settings.SoulDeathMarkerGuidanceEnabled;
        _nametagMode = NormalizeNametagMode(_settings.NametagMode);
        _nametagFadeSeconds = Math.Clamp(_settings.NametagFadeSeconds, 0.5f, 12f);
        _blockBreakParticles.ApplyPreset(_settings.ParticlePreset, _settings.QualityPreset);
        _soulMarkerParticles.ApplyPreset(_settings.ParticlePreset, _settings.QualityPreset);
        EnsureCommandRegistry();

        // Initialize stub services to fix compilation (will be replaced with new world generation)
        if (_world != null)
        {
            _streamingService = new StubStreamingService(_world, _log);
            _pregenerationService = new StubPregenerationService(_world, _log);
        }

        _pauseResume = new Button("RESUME", () =>
        {
            _pauseMenuOpen = false;
            _pauseHostOptionsOpen = false;
            if (_survivalRespawnPending)
                UpdateDeathScreenLayout();
        });
        _deathRespawn = new Button("RESPAWN", RespawnVeilwalkerPlayer) { BoldText = true };
        _deathQuit = new Button("QUIT", SaveAndExit) { BoldText = true };
        _pauseHost = new Button("HOST WORLD", OpenHostMenuFromPause);
        _pauseOpenLan = new Button("OPEN TO LAN", OpenToLanFromPause);
        _pauseHostOnline = new Button("HOST ONLINE", OpenOnlineHostFromPause);
        _pauseHostBack = new Button("BACK", CloseHostMenuFromPause);
        _pauseInviteFriends = new Button("INVITE FRIENDS", OpenInviteFriendsFromPause);
        _pauseSettings = new Button("SETTINGS", OpenSettings);
        _pauseSaveExit = new Button("SAVE & EXIT", SaveAndExit);
        _pauseProfileIcon = new Button("", OpenProfileFromPause) { BoldText = true };
        _pauseScreenshotsIcon = new Button("", OpenScreenshotsFromPause) { BoldText = true };
        _pauseInviteRefresh = new Button("REFRESH", RefreshInviteFriendsFromPause) { BoldText = true };
        _pauseInviteSend = new Button("SEND INVITE", SendInviteToSelectedPauseFriend) { BoldText = true };
        _pauseInviteClose = new Button("CLOSE", CloseInviteFriendsPopupFromPause) { BoldText = true };
        _inventoryClose = new Button("CLOSE", CloseInventory);
        _inventoryClear = new Button("CLEAR INVENTORY", ClearArtificerInventoryFromUi);
        _soulLootClose = new Button("CLOSE", CloseInventory);
        _soulLootClear = new Button("CLEAR SOUL", ClearSoulLootFromUi);
        _soulLootTakeAll = new Button("TAKE ALL", TakeAllSoulLootFromUi);
        _inventoryClose.Label = "X";
        _inventoryClose.BackgroundColor = new Color(150, 28, 28);
        _inventoryClose.BoldText = true;
        _soulLootClose.Label = "X";
        _soulLootClose.BackgroundColor = new Color(150, 28, 28);
        _soulLootClose.BoldText = true;
        _structureFinderBiomeTabBtn = new Button("BIOMES", () =>
        {
            _structureFinderStructureTab = false;
            ClearStructureFinderResult();
        });
        _structureFinderStructureTabBtn = new Button("STRUCTURES", () =>
        {
            _structureFinderStructureTab = true;
            ClearStructureFinderResult();
        });
        _structureFinderRadiusBtn = new Button("RADIUS", CycleStructureFinderRadius);
        _structureFinderFindBtn = new Button("FIND", ExecuteStructureFinderSearchFromGui);
        _structureFinderTeleportBtn = new Button("TELEPORT", TeleportStructureFinderResultFromGui);
        _structureFinderPrintBtn = new Button("PRINT COORDS", PrintStructureFinderResultToChat);
        _structureFinderCloseBtn = new Button("CLOSE", () => _structureFinderOpen = false);
        SyncStructureFinderRadiusLabel();
        _pauseMenuOpen = startPaused;

        try
        {
            _pausePanel = _assets.LoadTexture("textures/menu/GUIS/Pause_GUI.png");
            _pauseProfileIcon.Texture = _assets.LoadTexture("textures/menu/buttons/Profile.png");
            _pauseScreenshotsIcon.Texture = _assets.LoadTexture("textures/menu/buttons/screenshots.png");
            _healthHudTexture = TryLoadOptionalTexture("textures/menu/GUIS/health.png");
            _hungerHudTexture = TryLoadOptionalTexture("textures/menu/GUIS/hunger.png");
            _sigilHudTexture = TryLoadOptionalTexture("textures/menu/GUIS/sigil_balance_mockup.png");
        }
        catch (Exception ex)
        {
            _log.Warn($"Pause menu asset load: {ex.Message}");
        }

        LoadGamemodeWheelIcons();
        _structureFinderPanelTexture = TryLoadOptionalTexture(
            "textures/menu/GUIS/GUIBOX.png",
            "textures/menu/GUIS/WorldGeneration_GUI.png");

        // Note: World load is deferred to the first Update() to allow "Loading..." screen to draw.
    }

