    {
        _viewport = viewport;
        UpdateDeathScreenLayout();
        UpdatePauseMenuLayout();
        UpdateHotbarLayout();
        UpdateInventoryLayout();
        LayoutStructureFinderGui();
        UpdateAttunementWipPopupLayout();
    }

