    private Keys GetKeybind(string action, Keys fallback)
    {
        if (_settings.Keybinds != null && _settings.Keybinds.TryGetValue(action, out var key))
            return key;
        return fallback;
    }

    private string? GetMouseBind(string action)
    {
        if (_settings.MouseBinds != null && _settings.MouseBinds.TryGetValue(action, out var bind))
        {
            var normalized = NormalizeMouseBindToken(bind);
            if (!string.IsNullOrWhiteSpace(normalized))
                return normalized;
        }

        return null;
    }

    private static string? NormalizeMouseBindToken(string? token)
    {
        var value = (token ?? string.Empty).Trim().ToLowerInvariant();
        return value switch
        {
            "mouseleft" or "left" => "mouseleft",
            "mouseright" or "right" => "mouseright",
            "mousemiddle" or "middle" => "mousemiddle",
            "mousex1" or "mouse4" or "x1" => "mousex1",
            "mousex2" or "mouse5" or "x2" => "mousex2",
            _ => null
        };
    }

    private bool IsNewActionPress(InputState input, string action, Keys fallback)
    {
        if (input.IsNewKeyPress(GetKeybind(action, fallback)))
            return true;

        return GetMouseBind(action) switch
        {
            "mouseleft" => input.IsNewLeftClick(),
            "mouseright" => input.IsNewRightClick(),
            "mousemiddle" => input.IsNewMiddleClick(),
            "mousex1" => input.IsNewXButton1Click(),
            "mousex2" => input.IsNewXButton2Click(),
            _ => false
        };
    }

    private bool IsActionDown(InputState input, string action, Keys fallback)
    {
        if (input.IsKeyDown(GetKeybind(action, fallback)))
            return true;

        return GetMouseBind(action) switch
        {
            "mouseleft" => input.IsLeftDown(),
            "mouseright" => input.IsRightDown(),
            "mousemiddle" => input.IsMiddleDown(),
            "mousex1" => input.IsXButton1Down(),
            "mousex2" => input.IsXButton2Down(),
            _ => false
        };
    }

    private string FormatBindingLabel(string action, Keys fallback)
    {
        return GetMouseBind(action) switch
        {
            "mouseleft" => "MOUSE1",
            "mouseright" => "MOUSE2",
            "mousemiddle" => "MOUSE3",
            "mousex1" => "MOUSE4",
            "mousex2" => "MOUSE5",
            _ => FormatKeyLabel(GetKeybind(action, fallback))
        };
    }

    private static string NormalizeNametagMode(string? mode)
    {
        var text = (mode ?? string.Empty).Trim();
        if (text.Equals("off", StringComparison.OrdinalIgnoreCase))
            return "Off";
        if (text.Equals("fade", StringComparison.OrdinalIgnoreCase))
            return "Fade";
        return "Static";
    }

    private void EnqueuePostSyncDirtyHint(ChunkCoord coord)
    {
        if (_postSyncDirtyHintQueued.Add(coord))
            _postSyncDirtyHintQueue.Enqueue(coord);
    }

    private void ProcessPostSyncDirtyHints()
    {
        if (_postSyncDirtyHintQueue.Count == 0)
            return;

        var budget = _postSyncRecoveryTimer > 0f ? 8 : 3;
        while (budget > 0 && _postSyncDirtyHintQueue.Count > 0)
        {
            var coord = _postSyncDirtyHintQueue.Dequeue();
            _postSyncDirtyHintQueued.Remove(coord);

            if (_world?.TryGetChunk(coord, out var chunk) == true && chunk != null)
                chunk.IsDirty = true;

            QueuePriorityMeshBuild(coord);
            budget--;
        }
    }

    private void QueueDirtyChunks()
    {
        if (_world == null || _atlas == null)
            return;

        ProcessPostSyncDirtyHints();

        if (_postSyncRecoveryTimer > 0f)
        {
            _postSyncDirtyScanGate = (_postSyncDirtyScanGate + 1) % PostSyncDirtyScanIntervalFrames;
            if (_postSyncDirtyScanGate != 0)
                return;
        }

        var maxDirtyChunksPerFrame = _postSyncRecoveryTimer > 0f ? 4 : 8;
        var dirtyChunksProcessed = 0;
        _world.CopyChunksTo(_chunkSnapshotBuffer);

        // Two passes: near player first, then far chunks. Reuses buffers and avoids per-frame list allocations.
        for (var pass = 0; pass < 2 && dirtyChunksProcessed < maxDirtyChunksPerFrame; pass++)
        {
            for (var i = 0; i < _chunkSnapshotBuffer.Count; i++)
            {
                var chunk = _chunkSnapshotBuffer[i];
                if (!chunk.IsDirty)
                    continue;
                if (_activeChunks.Count > 0 && !_activeChunks.Contains(chunk.Coord))
                    continue;

                var nearFocus = IsChunkNearAnyFocus(chunk.Coord, _streamingFocusChunks, horizontalRadius: 2, verticalRadius: 1);
                if ((pass == 0 && !nearFocus) || (pass == 1 && nearFocus))
                    continue;

                QueueMeshBuild(chunk.Coord);
                dirtyChunksProcessed++;
                if (dirtyChunksProcessed >= maxDirtyChunksPerFrame)
                    break;
            }
        }
    }

    private void QueueMeshBuild(ChunkCoord coord)
    {
        if (!IsChunkNearAnyFocus(coord, _streamingFocusChunks) && (_meshQueued.Count + _meshBuildInFlight.Count) >= MaxOutstandingMeshJobs)
            return;

        if (_meshQueued.Add(coord))
            _meshQueue.Enqueue(coord);
    }

    private void QueuePriorityMeshBuild(ChunkCoord coord)
    {
        if (_activeChunks.Count > 0 && !_activeChunks.Contains(coord))
            return;
        if (_priorityMeshQueued.Add(coord))
            _priorityMeshQueue.Enqueue(coord);
    }

    private bool IsChunkNearAnyFocus(ChunkCoord coord, IReadOnlyList<ChunkCoord> focusChunks, int horizontalRadius = 2, int verticalRadius = 1)
    {
        if (focusChunks == null || focusChunks.Count == 0)
        {
            var dxFallback = Math.Abs(coord.X - _centerChunk.X);
            var dzFallback = Math.Abs(coord.Z - _centerChunk.Z);
            var dyFallback = Math.Abs(coord.Y - _centerChunk.Y);
            return Math.Max(dxFallback, dzFallback) <= horizontalRadius && dyFallback <= verticalRadius;
        }

        for (var i = 0; i < focusChunks.Count; i++)
        {
            var focus = focusChunks[i];
            var dx = Math.Abs(coord.X - focus.X);
            var dz = Math.Abs(coord.Z - focus.Z);
            var dy = Math.Abs(coord.Y - focus.Y);
            if (Math.Max(dx, dz) <= horizontalRadius && dy <= verticalRadius)
                return true;
        }

        return false;
    }

    private void QueuePriorityRemeshForBlockEdit(int wx, int wy, int wz)
    {
        _blockEditBoostRemaining = Math.Max(_blockEditBoostRemaining, BlockEditBoostFrames);
        var coord = VoxelWorld.WorldToChunk(wx, wy, wz, out var lx, out var ly, out var lz);
        InvalidateBlockEditMesh(coord);

        if (lx == 0)
        {
            var neighbor = new ChunkCoord(coord.X - 1, coord.Y, coord.Z);
            InvalidateBlockEditMesh(neighbor);
        }
        if (lx == VoxelChunkData.ChunkSizeX - 1)
        {
            var neighbor = new ChunkCoord(coord.X + 1, coord.Y, coord.Z);
            InvalidateBlockEditMesh(neighbor);
        }
        if (ly == 0)
        {
            var neighbor = new ChunkCoord(coord.X, coord.Y - 1, coord.Z);
            InvalidateBlockEditMesh(neighbor);
        }
        if (ly == VoxelChunkData.ChunkSizeY - 1)
        {
            var neighbor = new ChunkCoord(coord.X, coord.Y + 1, coord.Z);
            InvalidateBlockEditMesh(neighbor);
        }
        if (lz == 0)
        {
            var neighbor = new ChunkCoord(coord.X, coord.Y, coord.Z - 1);
            InvalidateBlockEditMesh(neighbor);
        }
        if (lz == VoxelChunkData.ChunkSizeZ - 1)
        {
            var neighbor = new ChunkCoord(coord.X, coord.Y, coord.Z + 1);
            InvalidateBlockEditMesh(neighbor);
        }
    }

    private void InvalidateBlockEditMesh(ChunkCoord coord)
    {
        if (_activeChunks.Count > 0 && !_activeChunks.Contains(coord))
            return;

        if (_world == null || !_world.TryGetChunk(coord, out var chunk) || chunk == null)
        {
            QueuePriorityMeshBuild(coord);
            return;
        }

        chunk.IsDirty = true;
        if (TryRebuildBlockEditMeshNow(coord, chunk))
            return;

        QueuePriorityMeshBuild(coord);
    }

    private bool TryRebuildBlockEditMeshNow(ChunkCoord coord, VoxelChunkData chunk)
    {
        if (_world == null || _atlas == null)
            return false;

        try
        {
            var mesh = VoxelMesherGreedy.BuildChunkMeshPriority(_world, chunk, _atlas, _log);
            if (!ValidateMesh(mesh))
                return false;

            _chunkMeshes[coord] = mesh;
            if (!_chunkOrder.Contains(coord))
                _chunkOrder.Add(coord);
            chunk.IsDirty = false;
            return true;
        }
        catch (Exception ex)
        {
            _log.Warn($"Failed immediate block-edit remesh for {coord}: {ex.Message}");
            return false;
        }
    }

    private bool TryDequeuePriorityMeshBuildCandidate(VoxelWorld world, out ChunkCoord coord, out VoxelChunkData chunk)
    {
        while (_priorityMeshQueue.Count > 0)
        {
            coord = _priorityMeshQueue.Dequeue();
            _priorityMeshQueued.Remove(coord);
            if (_activeChunks.Count > 0 && !_activeChunks.Contains(coord))
                continue;
            if (!world.TryGetChunk(coord, out var chunkData) || chunkData == null)
                continue;

            chunk = chunkData;
            return true;
        }

        coord = default;
        chunk = null!;
        return false;
    }

    private bool TryDequeueMeshBuildCandidate(VoxelWorld world, out ChunkCoord coord, out VoxelChunkData chunk)
    {
        while (_meshQueue.Count > 0)
        {
            coord = _meshQueue.Dequeue();
            _meshQueued.Remove(coord);
            if (_activeChunks.Count > 0 && !_activeChunks.Contains(coord))
                continue;
            if (!world.TryGetChunk(coord, out var chunkData) || chunkData == null)
                continue;

            chunk = chunkData;
            return true;
        }

        coord = default;
        chunk = null!;
        return false;
    }

    private void ProcessStreamingResults(bool aggressiveApply = false)
    {
        if (_streamingService == null || _world == null)
            return;

        // Check if streaming service is stuck and force recovery
        if (_streamingService.IsStuck(TimeSpan.FromSeconds(10)))
        {
            _log.Warn("Chunk streaming service appears stuck, forcing recovery...");
            
            if (!_spawnPrewarmComplete)
                _log.Warn("Streaming service is stuck during prewarm; continuing local prewarm path.");
        }

        // D) Reset per-frame counters
        _completedLoadsAppliedThisFrame = 0;
        _completedMeshesAppliedThisFrame = 0;
        
        // 4) AGGRESSIVE APPLY - Higher budget during preparing (up to 16 meshes/frame)
        int maxMeshesPerFrame = aggressiveApply ? 16 : 4;

        // Process load results - add loaded chunks to world
        _streamingService.ProcessLoadResults(result => {
            if (result.Success && result.Chunk != null)
            {
                // Add chunk to world dictionary (main thread only)
                _world.AddChunkDirect(result.Coord, result.Chunk);
                
                // 3) NEIGHBOR SCHEDULING - When a chunk loads, schedule mesh for it AND its N/S/E/W neighbors
                if (_activeChunks.Contains(result.Coord))
                {
                    _streamingService.EnqueueMeshJob(result.Coord, result.Chunk, 0);
                    
                    // Schedule neighbor meshes (N/S/E/W only)
                    var neighbors = new[]
                    {
                        new ChunkCoord(result.Coord.X + 1, result.Coord.Y, result.Coord.Z),
                        new ChunkCoord(result.Coord.X - 1, result.Coord.Y, result.Coord.Z),
                        new ChunkCoord(result.Coord.X, result.Coord.Y, result.Coord.Z + 1),
                        new ChunkCoord(result.Coord.X, result.Coord.Y, result.Coord.Z - 1)
                    };
                    
                    foreach (var neighborCoord in neighbors)
                    {
                        if (_world.TryGetChunk(neighborCoord, out var neighborChunk) && neighborChunk != null &&
                            _activeChunks.Contains(neighborCoord) &&
                            !_chunkMeshes.ContainsKey(neighborCoord))
                        {
                            _streamingService.EnqueueMeshJob(neighborCoord, neighborChunk, 1);
                        }
                    }
                }
                
                _completedLoadsAppliedThisFrame++;
            }
            else if (!result.Success)
            {
                _log.Error($"Failed to load chunk {result.Coord}: {result.Error}");
            }
        }, maxResults: MaxApplyCompletedChunkLoadsPerFrame);

        // Process mesh results - add built meshes to rendering
        _streamingService.ProcessMeshResults(result => {
            if (result.Success && result.Mesh != null)
            {
                _chunkMeshes[result.Coord] = result.Mesh;
                if (!_chunkOrder.Contains(result.Coord))
                    _chunkOrder.Add(result.Coord);
                
                _completedMeshesAppliedThisFrame++;
            }
            else if (result.Success && result.IsPlaceholder)
            {
                // Accept placeholder meshes to prevent infinite retry
                if (result.Mesh != null)
                {
                    _chunkMeshes[result.Coord] = result.Mesh;
                    if (!_chunkOrder.Contains(result.Coord))
                        _chunkOrder.Add(result.Coord);
                    
                    _completedMeshesAppliedThisFrame++;
                    _log.Debug($"Applied placeholder mesh for chunk {result.Coord}");
                }
            }
            else if (!result.Success)
            {
                _log.Error($"Failed to build mesh for chunk {result.Coord}: {result.Error}");
            }
        }, maxResults: maxMeshesPerFrame);

        // Process save results - log any save errors
        _streamingService.ProcessSaveResults(result => {
            if (!result.Success)
            {
                _log.Error($"Failed to save chunk {result.Coord}: {result.Error}");
            }
        }, maxResults: 2);

        // G) Log streaming stats periodically (every 5 seconds)
        var now = DateTime.UtcNow;
        if ((now - _lastStreamingStats).TotalSeconds >= 5)
        {
            if (_debugHudVisible)
            {
                var (loadQueue, meshQueue, saveQueue) = _streamingService.GetQueueSizes();
                _log.Info($"Streaming: Player={_playerChunkCoord}, Loaded={_world.ChunkCount}, " +
                         $"Queues(L/M/S)={loadQueue}/{meshQueue}/{saveQueue}, " +
                         $"Applied(L/M)={_completedLoadsAppliedThisFrame}/{_completedMeshesAppliedThisFrame}");
            }
            _lastStreamingStats = now;
        }
    }

    private readonly struct MeshBuildResult
    {
        public ChunkCoord Coord { get; }
        public ChunkMesh? Mesh { get; }
        public string? Error { get; }
        public int Version { get; }

        public MeshBuildResult(ChunkCoord coord, ChunkMesh? mesh, string? error, int version)
        {
            Coord = coord;
            Mesh = mesh;
            Error = error;
            Version = version;
        }
    }

    private readonly struct SaveAndExitResult
    {
        public bool Success { get; }
        public int SavedChunks { get; }
        public int SavedMeshes { get; }
        public double Seconds { get; }
        public string? Error { get; }

        public SaveAndExitResult(bool success, int savedChunks, int savedMeshes, double seconds, string? error)
        {
            Success = success;
            SavedChunks = savedChunks;
            SavedMeshes = savedMeshes;
            Seconds = seconds;
            Error = error;
        }
    }

    private void ProcessMeshBuildQueue(int budgetOverride = 0)
    {
        if (_isClosing || _world == null || _atlas == null)
            return;

        var boostBuilds = _blockEditBoostRemaining > 0;
        if (boostBuilds)
            _blockEditBoostRemaining--;

        var applyBudget = budgetOverride > 0 ? Math.Max(2, budgetOverride * 2) : 3;
        if (boostBuilds)
            applyBudget = Math.Max(applyBudget, 16);
        ApplyCompletedMeshBuilds(applyBudget);

        var scheduleBudget = budgetOverride > 0
            ? budgetOverride
            : Math.Max(MaxMeshBuildsPerFrame, RuntimeMeshScheduleBudget);
        if (boostBuilds)
            scheduleBudget = Math.Max(scheduleBudget, Math.Min(MeshWorkerCount + 1, 6));

        if (_postSyncRecoveryTimer > 0f)
            scheduleBudget = Math.Max(2, Math.Min(scheduleBudget, 3));

        var useFastMeshing = boostBuilds || _postSyncRecoveryTimer > 0f || ShouldUseFastMeshing();
        var priorityCap = boostBuilds ? MaxPriorityMeshBuildsPerFrame + 2 : MaxPriorityMeshBuildsPerFrame;
        var priorityBudget = Math.Min(scheduleBudget, priorityCap);
        var inlinePriorityBudget = boostBuilds ? MaxInlinePriorityMeshBuildsPerFrame : 0;

        // Always schedule edit-driven remeshes first so block breaks appear immediately.
        while (priorityBudget > 0 && scheduleBudget > 0)
        {
            if (!TryDequeuePriorityMeshBuildCandidate(_world, out var coord, out var chunk))
                break;

            if (!_meshBuildInFlight.TryAdd(coord, 0))
                continue;

            var tookSemaphore = _meshBuildSemaphore.Wait(0);
            if (!tookSemaphore)
            {
                if (inlinePriorityBudget > 0)
                {
                    try
                    {
                        var inlineMesh = VoxelMesherGreedy.BuildChunkMeshPriority(_world, chunk, _atlas, _log);
                        if (!ValidateMesh(inlineMesh))
                        {
                            _completedPriorityMeshBuildQueue.Enqueue(new MeshBuildResult(coord, null, "invalid", chunk.Version));
                        }
                        else
                        {
                            _completedPriorityMeshBuildQueue.Enqueue(new MeshBuildResult(coord, inlineMesh, null, chunk.Version));
                        }
                    }
                    catch (Exception ex)
                    {
                        _completedPriorityMeshBuildQueue.Enqueue(new MeshBuildResult(coord, null, ex.Message, chunk.Version));
                    }
                    finally
                    {
                        _meshBuildInFlight.TryRemove(coord, out _);
                    }

                    inlinePriorityBudget--;
                    scheduleBudget--;
                    priorityBudget--;
                    continue;
                }

                _meshBuildInFlight.TryRemove(coord, out _);
                QueuePriorityMeshBuild(coord);
                break;
            }

            var world = _world;
            var atlas = _atlas;
            var log = _log;
            var coordForBuild = coord;
            var chunkForBuild = chunk;
            var versionForBuild = chunk.Version;
            var cancellationToken = _backgroundWorkCts.Token;
            void BuildPriorityMesh()
            {
                try
                {
                    if (cancellationToken.IsCancellationRequested || _isClosing)
                        return;
                    var mesh = VoxelMesherGreedy.BuildChunkMeshPriority(world, chunkForBuild, atlas, log);
                    if (!ValidateMesh(mesh))
                    {
                        _completedPriorityMeshBuildQueue.Enqueue(new MeshBuildResult(coordForBuild, null, "invalid", versionForBuild));
                        return;
                    }

                    if (!_isClosing)
                        _completedPriorityMeshBuildQueue.Enqueue(new MeshBuildResult(coordForBuild, mesh, null, versionForBuild));
                }
                catch (Exception ex)
                {
                    _completedPriorityMeshBuildQueue.Enqueue(new MeshBuildResult(coordForBuild, null, ex.Message, versionForBuild));
                }
                finally
                {
                    _meshBuildInFlight.TryRemove(coordForBuild, out _);
                    if (tookSemaphore)
                        _meshBuildSemaphore.Release();
                }
            }

            _ = Task.Run(BuildPriorityMesh, cancellationToken);

            scheduleBudget--;
            priorityBudget--;
        }

        while (scheduleBudget > 0)
        {
            if (!TryDequeueMeshBuildCandidate(_world, out var coord, out var chunk))
                break;

            if (_priorityMeshQueued.Contains(coord))
                continue;

            if (!_meshBuildInFlight.TryAdd(coord, 0))
                continue;

            if (!_meshBuildSemaphore.Wait(0))
            {
                _meshBuildInFlight.TryRemove(coord, out _);
                QueueMeshBuild(coord);
                break;
            }

            var world = _world;
            var atlas = _atlas;
            var log = _log;
            var fast = useFastMeshing;
            var coordForBuild = coord;
            var chunkForBuild = chunk;
            var versionForBuild = chunk.Version;
            var cancellationToken = _backgroundWorkCts.Token;
            _ = Task.Run(() =>
            {
                try
                {
                    if (cancellationToken.IsCancellationRequested || _isClosing)
                        return;
                    var mesh = fast
                        ? VoxelMesherGreedy.BuildChunkMeshFast(world, chunkForBuild, atlas, log)
                        : VoxelMesherGreedy.BuildChunkMesh(world, chunkForBuild, atlas, log);
                    if (!ValidateMesh(mesh))
                    {
                        _completedMeshBuildQueue.Enqueue(new MeshBuildResult(coordForBuild, null, "invalid", versionForBuild));
                        return;
                    }

                    if (!_isClosing)
                        _completedMeshBuildQueue.Enqueue(new MeshBuildResult(coordForBuild, mesh, null, versionForBuild));
                }
                catch (Exception ex)
                {
                    _completedMeshBuildQueue.Enqueue(new MeshBuildResult(coordForBuild, null, ex.Message, versionForBuild));
                }
                finally
                {
                    _meshBuildInFlight.TryRemove(coordForBuild, out _);
                    _meshBuildSemaphore.Release();
                }
            }, cancellationToken);

            scheduleBudget--;
        }

        // Apply inline priority builds immediately so rapid block breaks are visually instant.
        if (boostBuilds)
            ApplyCompletedMeshBuilds(MaxInlinePriorityMeshBuildsPerFrame + 1);
    }

    private void ApplyCompletedMeshBuilds(int maxApply)
    {
        if (_world == null || _isClosing)
            return;

        for (var i = 0; i < maxApply; i++)
        {
            if (!_completedPriorityMeshBuildQueue.TryDequeue(out var result)
                && !_completedMeshBuildQueue.TryDequeue(out result))
                break;

            if (!_world.TryGetChunk(result.Coord, out var chunk) || chunk == null)
                continue;

            // Skip stale background results produced before a newer block edit.
            if (chunk.Version != result.Version)
            {
                chunk.IsDirty = true;
                QueuePriorityMeshBuild(result.Coord);
                continue;
            }

            if (result.Mesh != null)
            {
                _chunkMeshes[result.Coord] = result.Mesh;
                if (!_chunkOrder.Contains(result.Coord))
                    _chunkOrder.Add(result.Coord);
            }
            else if (!string.IsNullOrWhiteSpace(result.Error) && result.Error != "invalid" && !_isClosing)
            {
                _log.Warn($"Background mesh build failed for {result.Coord}: {result.Error}");
            }
            else if (!_loggedInvalidChunkMesh)
            {
                _log.Error($"Invalid chunk mesh for {result.Coord}. Skipping draw to avoid artifacts.");
                _loggedInvalidChunkMesh = true;
            }

            chunk.IsDirty = false;
        }
    }

    private bool ShouldUseFastMeshing()
    {
        // During prewarm we prioritize quick visual availability over final mesh quality.
        if (!_spawnPrewarmComplete)
            return true;

        // In gameplay, only use fast meshing under sustained pressure and queue backlog.
        if (_meshQueue.Count > 24 && _fps > 0f && _fps < 50f)
            return true;

        return false;
    }

    private static bool ValidateMesh(ChunkMesh mesh)
    {
        if (mesh.OpaqueVertices.Length % 3 != 0
            || mesh.CutoutVertices.Length % 3 != 0
            || mesh.TransparentVertices.Length % 3 != 0
            || mesh.WaterVertices.Length % 3 != 0)
            return false;

        return VerticesFinite(mesh.OpaqueVertices)
            && VerticesFinite(mesh.CutoutVertices)
            && VerticesFinite(mesh.TransparentVertices)
            && VerticesFinite(mesh.WaterVertices);
    }

    private static bool VerticesFinite(VertexPositionTexture[] verts)
    {
        for (int i = 0; i < verts.Length; i++)
        {
            var p = verts[i].Position;
            if (float.IsNaN(p.X) || float.IsNaN(p.Y) || float.IsNaN(p.Z))
                return false;
            if (float.IsInfinity(p.X) || float.IsInfinity(p.Y) || float.IsInfinity(p.Z))
                return false;
        }
        return true;
    }

    private void TrimFarChunks(int keepRadius)
    {
        if (_world == null || _streamingService == null)
            return;

        var keep = new HashSet<ChunkCoord>();
        var keepSq = keepRadius * keepRadius;
        BuildStreamingFocusChunks(_streamingFocusChunks);
        if (_streamingFocusChunks.Count == 0)
            _streamingFocusChunks.Add(_centerChunk);

        for (var focusIndex = 0; focusIndex < _streamingFocusChunks.Count; focusIndex++)
        {
            var focus = _streamingFocusChunks[focusIndex];
            var maxCy = GetStreamingMaxChunkY(focus.Y);
            for (var dz = -keepRadius; dz <= keepRadius; dz++)
            {
                for (var dx = -keepRadius; dx <= keepRadius; dx++)
                {
                    if (dx * dx + dz * dz > keepSq)
                        continue;
                    for (var cy = 0; cy <= maxCy; cy++)
                        keep.Add(new ChunkCoord(focus.X + dx, cy, focus.Z + dz));
                }
            }
        }

        // Unload chunks with save-on-unload support
        _world.UnloadChunks(keep, (coord, blocks) => {
            _streamingService.EnqueueSaveJob(coord, blocks);
        });

        // Also remove meshes for unloaded chunks - thread-safe with ConcurrentDictionary
        var toRemoveMeshes = new List<ChunkCoord>();
        var meshKeys = _chunkMeshes.Keys.ToArray(); // Create snapshot for safe enumeration
        foreach (var meshCoord in meshKeys)
        {
            if (!keep.Contains(meshCoord))
                toRemoveMeshes.Add(meshCoord);
        }

        foreach (var coord in toRemoveMeshes)
        {
            if (_chunkMeshes.TryRemove(coord, out _))
            {
                _chunkOrder.Remove(coord);
            }
        }
    }

    private void CenterCamera()
    {
        var state = BuildDefaultPlayerState();
        ApplyPlayerState(state);
        _thirdPersonYaw = _player.Yaw;
        _thirdPersonPitch = Math.Clamp(_player.Pitch, ThirdPersonPitchMin, ThirdPersonPitchMax);
        _thirdPersonPlayerYawTarget = _player.Yaw;
        _thirdPersonFreeLookHeld = false;
        _cameraPosition = _player.Position + _player.HeadOffset;
        _thirdPersonCameraDistance = 0f;
    }

    private bool IsThirdPersonCameraActive()
    {
        return _thirdPersonEnabled && _gameMode != GameMode.Veilseer;
    }

    private void ToggleThirdPersonMode()
    {
        _thirdPersonEnabled = !_thirdPersonEnabled;
        if (_thirdPersonEnabled)
        {
            _thirdPersonYaw = _player.Yaw;
            _thirdPersonPitch = Math.Clamp(_player.Pitch, ThirdPersonPitchMin, ThirdPersonPitchMax);
            _thirdPersonPlayerYawTarget = _player.Yaw;
            _thirdPersonFreeLookHeld = false;
            SetCommandStatus("Third-person view enabled.", 2.5f, echoToChat: false);
        }
        else
        {
            _thirdPersonFreeLookHeld = false;
            SetCommandStatus("First-person view enabled.", 2.5f, echoToChat: false);
        }
    }

    private void UpdatePlayer(GameTime gameTime, float dt, InputState input)
    {
        if (_world == null)
            return;
        _player.AllowCrouch = _gameMode != GameMode.Veilseer;
        _player.ToggleCrouchEnabled = _settings.ToggleCrouchEnabled;
        _player.SprintLatchEnabled = _settings.SprintLatchEnabled;
        if (_gameMode == GameMode.Veilseer && !_player.IsFlying)
            _player.SetFlying(true);
        if (_gameMode == GameMode.Veilseer
            && _veilseerSpectateTargetPlayerId >= 0
            && _remotePlayers.ContainsKey(_veilseerSpectateTargetPlayerId))
        {
            UpdateSpectateCameraSmoothing(dt);
            return;
        }

        ResetSpectateCameraSmoothing();

        var thirdPersonActive = IsThirdPersonCameraActive();
        if (thirdPersonActive)
        {
            var look = input.LookDelta;
            var freeLookHeld = IsActionDown(input, "GamemodeModifier", Keys.LeftAlt);
            var wasFreeLookHeld = _thirdPersonFreeLookHeld;
            _thirdPersonFreeLookHeld = freeLookHeld;
            _player.SuppressLookInput = true;

            _thirdPersonPitch = Math.Clamp(_thirdPersonPitch - look.Y, ThirdPersonPitchMin, ThirdPersonPitchMax);
            if (freeLookHeld)
            {
                _thirdPersonYaw = MathHelper.WrapAngle(_thirdPersonYaw + look.X);
                if (!wasFreeLookHeld)
                    _thirdPersonPlayerYawTarget = _player.Yaw;
            }
            else
            {
                if (wasFreeLookHeld)
                {
                    // On free-look release, snap orbit back to current facing without rotating player.
                    _thirdPersonPlayerYawTarget = _player.Yaw;
                    _thirdPersonYaw = _player.Yaw;
                    _thirdPersonPitch = Math.Clamp(_player.Pitch / 0.70f, ThirdPersonPitchMin, ThirdPersonPitchMax);
                    look.X = 0f;
                    look.Y = 0f;
                }

                _thirdPersonPlayerYawTarget = MathHelper.WrapAngle(_thirdPersonPlayerYawTarget + look.X);
                _player.Yaw = _thirdPersonPlayerYawTarget;
                // Follow mode keeps camera locked to facing direction like first-person.
                _thirdPersonYaw = _player.Yaw;
            }

            // Keep model head/upper body aligned to camera vertical aim in third person with smoothing.
            if (!freeLookHeld)
            {
                var desiredPlayerPitch = Math.Clamp(_thirdPersonPitch * 0.70f, -1.0f, 1.0f);
                var pitchLerp = Math.Clamp(ThirdPersonPitchLerpPerSecond * dt, 0f, 1f);
                _player.Pitch = MathHelper.Lerp(_player.Pitch, desiredPlayerPitch, pitchLerp);
            }
        }
        else
        {
            _player.SuppressLookInput = false;
            _thirdPersonFreeLookHeld = false;
        }

        _player.Update(dt, gameTime.TotalGameTime.TotalSeconds, input, _world.GetBlock);
        _player.SuppressLookInput = false;

        if (!thirdPersonActive)
        {
            _thirdPersonYaw = _player.Yaw;
            _thirdPersonPitch = Math.Clamp(_player.Pitch, ThirdPersonPitchMin, ThirdPersonPitchMax);
            _thirdPersonPlayerYawTarget = _player.Yaw;
        }

        ClampPlayerToWorldBounds();
    }

    private void UpdateVeilwalkerSurvival(float dt)
    {
        if (_gameMode != GameMode.Veilwalker)
        {
            _survivalRespawnPending = false;
            _survivalWasGrounded = _player.IsGrounded;
            _survivalPeakAirY = _player.Position.Y;
            return;
        }

        if (_survivalRespawnPending)
            return;

        var moving = _player.MoveIntent.LengthSquared() > 0.01f && !_player.IsFlying;
        var previousHealth = _survivalVitals.Health;
        var tickResult = _survivalVitals.Tick(dt, moving, _player.IsSprinting && moving, _difficultyLevel);
        if (tickResult.AnyChange)
            MarkPlayerStateDirty();
        if (_survivalVitals.Health < previousHealth)
            TriggerDamageFeedback(previousHealth - _survivalVitals.Health);

        TrackVeilwalkerFallDamage();

        if (_survivalVitals.IsDead)
            BeginVeilwalkerRespawn();
    }

    private void TrackVeilwalkerFallDamage()
    {
        if (_player.IsFlying)
        {
            _survivalWasGrounded = false;
            _survivalPeakAirY = _player.Position.Y;
            return;
        }

        if (!_player.IsGrounded)
        {
            if (_survivalWasGrounded)
            {
                _survivalWasGrounded = false;
                _survivalPeakAirY = _player.Position.Y;
            }
            else if (_player.Position.Y > _survivalPeakAirY)
            {
                _survivalPeakAirY = _player.Position.Y;
            }

            return;
        }

        if (!_survivalWasGrounded)
        {
            var fallDistance = _survivalPeakAirY - _player.Position.Y;
            var damage = _survivalVitals.CalculateFallDamage(fallDistance / Scale.BlockSize);
            if (damage > 0 && _survivalVitals.ApplyDamage(damage))
            {
                TriggerDamageFeedback(damage);
                MarkPlayerStateDirty();
                SetCommandStatus($"Took {damage} fall damage.", 2.2f, echoToChat: false);
            }

            if (_survivalVitals.IsDead)
                BeginVeilwalkerRespawn();
        }

        _survivalWasGrounded = true;
        _survivalPeakAirY = _player.Position.Y;
    }

    private void TriggerDamageFeedback(int damage)
    {
        if (damage <= 0)
            return;

        var normalized = Math.Clamp(damage / 8f, 0.18f, 0.65f);
        _damageFlashTimer = DamageFlashDurationSeconds;
        _damageFlashStrength = Math.Max(_damageFlashStrength, normalized);
        _damageHandKickTimer = DamageHandKickDurationSeconds;
        _damageHandKickStrength = Math.Max(_damageHandKickStrength, normalized);
        _damageCameraKickTimer = DamageCameraKickDurationSeconds;
        _damageCameraKickStrength = Math.Max(_damageCameraKickStrength, normalized);
    }

    private void BeginVeilwalkerRespawn()
    {
        if (_survivalRespawnPending)
            return;

        HandleDeathRecoveryAtDeath();
        _survivalRespawnPending = true;
        _player.Velocity = Vector3.Zero;
        MarkPlayerStateDirty();
        SetCommandStatus("You died.", 2.5f, echoToChat: false);
        UpdateDeathScreenLayout();
    }

    private void HandleDeathRecoveryAtDeath()
    {
        if (_gameMode == GameMode.Artificer || _saveInventoryEnabled || !HasAnyDroppablePlayerInventoryItems())
            return;

        switch (GetInventoryRuleValue())
        {
            case "drop":
                SpawnDeathItemDrops();
                break;
            case "body":
            case "soul":
            default:
                SpawnSoulMarkerAtDeath();
                break;
        }

        if (_gameMode != GameMode.Artificer)
            _inventory.ClearAll(clearGrid: true);

        MarkPlayerStateDirty();
        SavePlayerState();
        PushLocalPersistenceSnapshotNow();
    }

    private void RespawnVeilwalkerPlayer()
    {
        _survivalRespawnPending = false;
        _player.Velocity = Vector3.Zero;
        _player.SetFlying(false);

        Vector3 respawnPosition;
        if (_hasHome)
        {
            respawnPosition = _homePosition;
        }
        else
        {
            var spawnPoint = GetWorldSpawnPoint();
            var safeHeight = FindSafeSpawnHeight(spawnPoint.X, spawnPoint.Y);
            respawnPosition = new Vector3(spawnPoint.X, Math.Max(safeHeight + 2f, 6f), spawnPoint.Y);
        }

        _player.Position = respawnPosition;
        _survivalVitals.RestoreToFull();
        _survivalWasGrounded = false;
        _survivalPeakAirY = respawnPosition.Y;
        EnsurePlayerNotInsideSolid(forceLog: false);
        MarkPlayerStateDirty();
        SavePlayerState();
        SetCommandStatus("Respawned.", 2f, echoToChat: false);
    }

    private void SpawnSoulMarkerAtDeath()
    {
        var nowUtc = DateTime.UtcNow;
        var expireUtc = GetSoulMarkerExpireUtc(nowUtc, _difficultyLevel);
        var markerPosition = _player.Position;
        var soulInventory = CaptureSoulInventoryFromPlayer();
        if (!HasAnySoulInventoryItems(soulInventory))
            return;

        _soulMarker = new SoulMarkerState
        {
            Active = true,
            Position = markerPosition,
            BasePosition = markerPosition,
            OwnerUsername = _profile.GetDisplayUsername(),
            OwnerPlayerId = _profile.PlayerId,
            Yaw = _player.Yaw,
            SpawnedUtc = nowUtc,
            ExpireUtc = expireUtc,
            ReleaseTimer = SoulMarkerReleaseSeconds,
            Inventory = soulInventory
        };
        _soulMarkerParticles.SpawnRelease(markerPosition + new Vector3(0f, 0.45f, 0f));

        if (AreCheatsEnabled())
        {
            AddChatLine(
                "Soul marker created. Use RECOVER to warp back to the death site.",
                isSystem: true,
                actionLabel: "RECOVER",
                customActionToken: SoulMarkerWarpActionToken,
                customActionStatus: "Warping to soul marker...",
                hoverText: "Teleport to your active soul marker.");
        }

        PushLocalPersistenceSnapshotNow();
    }

    private void SpawnDeathItemDrops()
    {
        if (_world == null)
            return;

        var origin = _player.Position + new Vector3(0f, Scale.PlayerHeadHeight * 0.25f, 0f);
        var random = new Random(Environment.TickCount);
        var localPlayerId = _lanSession?.LocalPlayerId ?? -1;

        void DropSlot(HotbarSlot slot)
        {
            if (slot.Id == BlockId.Air || slot.Count <= 0)
                return;

            var angle = (float)(random.NextDouble() * Math.PI * 2.0);
            var radius = 0.25f + (float)random.NextDouble() * 0.45f;
            var velocity = new Vector3(
                MathF.Cos(angle) * (1.2f + (float)random.NextDouble()),
                2.1f + (float)random.NextDouble() * 0.9f,
                MathF.Sin(angle) * (1.2f + (float)random.NextDouble())) * Scale.BlockSize;
            var spawn = new LanItemSpawn
            {
                ItemId = NextItemId(),
                BlockId = (byte)slot.Id,
                Count = slot.Count,
                X = origin.X + MathF.Cos(angle) * radius,
                Y = origin.Y + 0.2f + (float)random.NextDouble() * 0.25f,
                Z = origin.Z + MathF.Sin(angle) * radius,
                VelX = velocity.X,
                VelY = velocity.Y,
                VelZ = velocity.Z,
                PickupDelay = ItemDropPickupDelaySeconds,
                PickupLockPlayerId = localPlayerId
            };
            SpawnWorldItem(spawn);
            SendItemSpawn(spawn);
        }

        for (var i = 0; i < _inventory.Hotbar.Length; i++)
            DropSlot(_inventory.Hotbar[i]);
        for (var i = 0; i < _inventory.Grid.Length; i++)
            DropSlot(_inventory.Grid[i]);
    }

    private bool HasAnyDroppablePlayerInventoryItems()
    {
        for (var i = 0; i < _inventory.Hotbar.Length; i++)
        {
            var slot = _inventory.Hotbar[i];
            if (slot.Id != BlockId.Air && slot.Count > 0)
                return true;
        }

        for (var i = 0; i < _inventory.Grid.Length; i++)
        {
            var slot = _inventory.Grid[i];
            if (slot.Id != BlockId.Air && slot.Count > 0)
                return true;
        }

        return false;
    }

    private static bool HasAnySoulInventoryItems(HotbarSlot[]? slots)
    {
        if (slots == null)
            return false;

        for (var i = 0; i < slots.Length; i++)
        {
            if (slots[i].Id != BlockId.Air && slots[i].Count > 0)
                return true;
        }

        return false;
    }

    private void UpdateSoulMarker(float dt)
    {
        if (_soulMarker.Active && !_soulMarker.IsInfinite && _soulMarker.ExpireUtc <= DateTime.UtcNow)
        {
            ClearSoulMarker(saveImmediately: true);
        }

        if (_soulMarker.Active)
        {
            if (_soulMarker.ReleaseTimer > 0f)
                _soulMarker.ReleaseTimer = Math.Max(0f, _soulMarker.ReleaseTimer - dt);

            var floatPhase = _worldTimeSeconds * 1.15f;
            var bob = _soulMarker.ReleaseTimer > 0f
                ? MathHelper.Lerp(0f, SoulMarkerRiseHeightBlocks * Scale.BlockSize, 1f - (_soulMarker.ReleaseTimer / SoulMarkerReleaseSeconds))
                : (SoulMarkerIdleHeightBlocks + MathF.Sin(floatPhase) * SoulMarkerIdleBobBlocks) * Scale.BlockSize;
            _soulMarker.Position = _soulMarker.BasePosition + new Vector3(0f, bob, 0f);

            if (!_survivalRespawnPending && !_survivalVitals.IsDead)
            {
                var distance = Vector3.Distance(_player.Position, _soulMarker.BasePosition);
                if (!_soulLootOpen
                    && distance <= SoulMarkerRecoverRadiusBlocks * Scale.BlockSize
                    && !HasSoulInventoryItems())
                {
                    ClearSoulMarker(saveImmediately: true);
                    SetCommandStatus("Soul marker recovered.", 2.5f, echoToChat: false);
                }
            }
        }

        _soulMarkerParticles.Update(dt, _soulMarker.Active, _soulMarker.Position);
    }

    private void ClearSoulMarker(bool saveImmediately)
    {
        if (!_soulMarker.Active)
            return;

        _soulMarker = default;
        _soulLootOpen = false;
        _soulLootSourcePlayerId = -1;
        _soulRecoverHoldActive = false;
        _soulRecoverHoldElapsed = 0f;
        MarkPlayerStateDirty();
        if (saveImmediately)
            SavePlayerState();
        if (saveImmediately)
            PushLocalPersistenceSnapshotNow();
    }

    private HotbarSlot[] CaptureSoulInventoryFromPlayer()
    {
        var soulInventory = CloneSoulInventorySlots(null);
        for (var i = 0; i < Inventory.HotbarSize; i++)
        {
            soulInventory[i] = _inventory.Hotbar[i];
            _inventory.Hotbar[i] = default;
        }

        for (var i = 0; i < Inventory.GridSize; i++)
        {
            soulInventory[Inventory.HotbarSize + i] = _inventory.Grid[i];
            _inventory.Grid[i] = default;
        }

        _inventoryHeld = default;
        _inventoryHasHeld = false;
        _heldFrom = InventorySlotGroup.None;
        _heldIndex = -1;
        return soulInventory;
    }

    private bool HasSoulInventoryItems()
    {
        if (!_soulMarker.Active || _soulMarker.Inventory == null)
            return false;

        for (var i = 0; i < _soulMarker.Inventory.Length; i++)
        {
            if (_soulMarker.Inventory[i].Id != BlockId.Air && _soulMarker.Inventory[i].Count > 0)
                return true;
        }

        return false;
    }

    private bool IsLocalPlayersSoul()
    {
        var ownerPlayerId = (_soulMarker.OwnerPlayerId ?? string.Empty).Trim();
        if (!string.IsNullOrWhiteSpace(ownerPlayerId) && string.Equals(ownerPlayerId, (_profile.PlayerId ?? string.Empty).Trim(), StringComparison.OrdinalIgnoreCase))
            return true;

        var ownerUsername = (_soulMarker.OwnerUsername ?? string.Empty).Trim();
        return !string.IsNullOrWhiteSpace(ownerUsername)
            && string.Equals(ownerUsername, _profile.GetDisplayUsername(), StringComparison.OrdinalIgnoreCase);
    }

    private bool IsSoulOwnerTrustedByLocalPlayer()
    {
        return true;
    }

    private bool CanInteractWithSoul()
    {
        if (!_soulMarker.Active || !HasSoulInventoryItems())
            return false;

        if (IsLocalPlayersSoul())
            return true;

        return _sharedSoulAccessEnabled && IsSoulOwnerTrustedByLocalPlayer();
    }

    private string GetSoulDisplayTitle()
    {
        var owner = (_soulMarker.OwnerUsername ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(owner))
            owner = "Unknown";

        return $"{owner}'s Soul";
    }

    private bool IsViewingLocalSoul()
    {
        return _lanSession == null || _soulLootSourcePlayerId <= 0 || _soulLootSourcePlayerId == _lanSession.LocalPlayerId;
    }

    private HotbarSlot[] GetViewedSoulInventory()
    {
        if (IsViewingLocalSoul())
            return _soulMarker.Inventory ?? Array.Empty<HotbarSlot>();

        if (_remoteSoulStates.TryGetValue(_soulLootSourcePlayerId, out var remoteState) && remoteState.SoulInventory != null)
            return remoteState.SoulInventory;

        return Array.Empty<HotbarSlot>();
    }

    private bool HasViewedSoulInventoryItems()
    {
        return HasAnySoulInventoryItems(GetViewedSoulInventory());
    }

    private string GetViewedSoulDisplayTitle()
    {
        if (IsViewingLocalSoul())
            return GetSoulDisplayTitle();

        if (_remoteSoulStates.TryGetValue(_soulLootSourcePlayerId, out var remoteState))
        {
            var owner = string.IsNullOrWhiteSpace(remoteState.SoulOwnerUsername) ? ResolvePlayerName(_soulLootSourcePlayerId) : remoteState.SoulOwnerUsername.Trim();
            if (string.IsNullOrWhiteSpace(owner))
                owner = "Unknown";
            return $"{owner}'s Soul";
        }

        return "Unknown Soul";
    }

    private bool CanModifyViewedSoul()
    {
        return IsViewingLocalSoul();
    }

    private bool CanTakeFromViewedSoul()
    {
        if (IsViewingLocalSoul())
            return CanModifyViewedSoul() && CanInteractWithSoul();

        return _sharedSoulAccessEnabled && HasViewedSoulInventoryItems();
    }

    private void RefreshRemoteSoulState(int playerId, PlayerWorldState state)
    {
        if (playerId <= 0)
            return;

        var expireUtc = state.SoulMarkerExpireUtcTicks > 0
            ? new DateTime(state.SoulMarkerExpireUtcTicks, DateTimeKind.Utc)
            : DateTime.MaxValue;
        var hasLiveSoul = state.HasSoulMarker
            && expireUtc > DateTime.UtcNow
            && HasAnySoulInventoryItems(state.SoulInventory);
        if (!hasLiveSoul)
        {
            _remoteSoulStates.Remove(playerId);
            return;
        }

        _remoteSoulStates[playerId] = state;
    }

    private static Vector3 GetSoulMarkerBasePosition(PlayerWorldState state)
    {
        return new Vector3(state.SoulMarkerX, state.SoulMarkerY, state.SoulMarkerZ);
    }

    private Vector3 GetSoulMarkerVisualPosition(PlayerWorldState state)
    {
        var basePosition = GetSoulMarkerBasePosition(state);
        var expireUtc = state.SoulMarkerExpireUtcTicks > 0
            ? new DateTime(state.SoulMarkerExpireUtcTicks, DateTimeKind.Utc)
            : DateTime.MaxValue;
        var spawnedUtc = state.SoulMarkerSpawnedUtcTicks > 0
            ? new DateTime(state.SoulMarkerSpawnedUtcTicks, DateTimeKind.Utc)
            : DateTime.UtcNow;
        var releaseRemaining = 0f;
        if (expireUtc > DateTime.UtcNow && spawnedUtc <= DateTime.UtcNow)
        {
            var elapsed = (float)(DateTime.UtcNow - spawnedUtc).TotalSeconds;
            releaseRemaining = Math.Max(0f, SoulMarkerReleaseSeconds - elapsed);
        }

        var bob = releaseRemaining > 0f
            ? MathHelper.Lerp(0f, SoulMarkerRiseHeightBlocks * Scale.BlockSize, 1f - (releaseRemaining / SoulMarkerReleaseSeconds))
            : (SoulMarkerIdleHeightBlocks + MathF.Sin(_worldTimeSeconds * 1.15f) * SoulMarkerIdleBobBlocks) * Scale.BlockSize;
        return basePosition + new Vector3(0f, bob, 0f);
    }

    private static DateTime GetSoulMarkerExpireUtc(DateTime nowUtc, int difficulty)
    {
        return WorldDifficulty.Clamp(difficulty) switch
        {
            0 => DateTime.MaxValue,
            1 => nowUtc.AddMinutes(30),
            2 => nowUtc.AddMinutes(15),
            3 => nowUtc.AddMinutes(7),
            _ => nowUtc.AddMinutes(15)
        };
    }

    private void ClampPlayerToWorldBounds()
    {
        if (_meta == null || !HasFiniteWorldBounds())
            return;

        var maxX = Math.Max(0.5f, _meta.Size.Width - 0.5f);
        var maxZ = Math.Max(0.5f, _meta.Size.Depth - 0.5f);
        var pos = _player.Position;
        var clampedX = Math.Clamp(pos.X, 0.5f, maxX);
        var clampedZ = Math.Clamp(pos.Z, 0.5f, maxZ);
        if (MathF.Abs(clampedX - pos.X) < 0.0001f && MathF.Abs(clampedZ - pos.Z) < 0.0001f)
            return;

        _player.Position = new Vector3(clampedX, pos.Y, clampedZ);
    }

    private void ApplyPlayerSeparation(float dt)
    {
        if (_gameMode == GameMode.Veilseer || _player.NoClipEnabled)
            return;

        if (!_playerCollisionEnabled || _remotePlayers.Count == 0)
            return;

        var pos = _player.Position;
        var half = PlayerController.ColliderHalfWidth;
        var height = _player.ColliderHeight;
        var minDist = Math.Max(0.01f, half * 2f - PlayerPushSkin);
        var minDistSq = minDist * minDist;
        var totalPush = Vector3.Zero;

        foreach (var pair in _remotePlayers)
        {
            if (ShouldHideRemotePlayerFromLocal(pair.Key))
                continue;
                
            var model = pair.Value;
            var other = model.Position;
            var verticalOverlap = pos.Y < other.Y + model.ColliderHeight && pos.Y + height > other.Y;
            if (!verticalOverlap)
                continue;

            var dx = pos.X - other.X;
            var dz = pos.Z - other.Z;
            var distSq = dx * dx + dz * dz;
            if (distSq >= minDistSq)
                continue;

            Vector2 dir;
            float push;
            if (distSq < 0.0001f)
            {
                var f = _player.Forward;
                dir = new Vector2(f.X, f.Z);
                if (dir.LengthSquared() < 0.0001f)
                    dir = Vector2.UnitX;
                else
                    dir.Normalize();
                push = Math.Min(minDist * 0.5f, PlayerPushStrength * dt);
            }
            else
            {
                var dist = MathF.Sqrt(distSq);
                dir = new Vector2(dx / dist, dz / dist);
                var penetration = minDist - dist;
                push = Math.Min(penetration * 0.5f, PlayerPushStrength * dt);
            }

            push = Math.Min(push, PlayerPushMaxStep);
            totalPush += new Vector3(dir.X * push, 0f, dir.Y * push);
        }

        if (totalPush.LengthSquared() <= 0f)
            return;

        var candidate = pos + totalPush;
        if (!IsPlayerInsideSolid(candidate))
            _player.Position = candidate;
    }

    private void HandleBlockInteraction(GameTime gameTime, InputState input)
    {
        if (_world == null)
            return;
        if (_gameMode == GameMode.Veilseer)
            return;

        var dt = (float)gameTime.ElapsedGameTime.TotalSeconds;
        if (_interactCooldown > 0f)
            _interactCooldown = Math.Max(0f, _interactCooldown - dt);

        if (_interactCooldown > 0f)
            return;

        var leftDown = input.IsLeftDown();
        var newLeftClick = input.IsNewLeftClick();
        var origin = _player.Position + _player.HeadOffset;
        var dir = _player.Forward;
        if (input.IsNewRightClick() && TryHandleSoulRightClick(origin, dir))
        {
            _interactCooldown = InteractCooldownSeconds;
            return;
        }

        var hasBlockHit = VoxelRaycast.Raycast(origin, dir, InteractRange, _world.GetBlock, out var hit);
        var blockHitDistance = hasBlockHit
            ? Vector3.Distance(origin, new Vector3(hit.X + 0.5f, hit.Y + 0.5f, hit.Z + 0.5f))
            : float.MaxValue;

        if (newLeftClick && TryHandlePlayerMeleeClick(origin, dir, blockHitDistance))
            return;

        if (!hasBlockHit)
        {
            if (leftDown)
            {
                TriggerLocalActionSwing(dir);
                _interactCooldown = HeldAirSwingCooldownSeconds;
            }
            return;
        }

        if (leftDown)
        {
            var id = _world.GetBlock(hit.X, hit.Y, hit.Z);
            if (id != BlockIds.Air)
            {
                if (id == BlockIds.Nullblock && _gameMode == GameMode.Veilwalker)
                {
                    _interactCooldown = InteractCooldownSeconds;
                    return;
                }

                _world.SetBlock(hit.X, hit.Y, hit.Z, BlockIds.Air);
                _lanSession?.SendBlockSet(hit.X, hit.Y, hit.Z, BlockIds.Air);
                QueuePriorityRemeshForBlockEdit(hit.X, hit.Y, hit.Z);
                _blockBreakParticles.SpawnBlockBreak(hit.X, hit.Y, hit.Z, id);
                TriggerLocalActionSwing(GetDirectionToBlockCenter(origin, hit.X, hit.Y, hit.Z));
                
                if (_gameMode == GameMode.Veilwalker)
                    SpawnBlockDrop(hit.X, hit.Y, hit.Z, (BlockId)id);
                else
                {
                    if (!AlreadyOwnsItem((BlockId)id))
                    {
                        _inventory.Add((BlockId)id, 1);
                        MarkPlayerStateDirty(); // Mark dirty after inventory change
                    }
                }
                _interactCooldown = GetBlockBreakCooldownSeconds(id);
            }
        }
        else if (input.IsNewMiddleClick())
        {
            var id = _world.GetBlock(hit.X, hit.Y, hit.Z);
            if (id != BlockIds.Air)
            {
                _inventory.PickBlock((BlockId)id);
                _interactCooldown = InteractCooldownSeconds;
            }
        }
        else if (input.IsNewRightClick())
        {
            var id = _world.GetBlock(hit.PrevX, hit.PrevY, hit.PrevZ);
            var selected = _inventory.SelectedId;
            var sandbox = _gameMode == GameMode.Artificer;
            if (id == BlockIds.Air && selected == BlockId.WaterBucket && (sandbox || _inventory.SelectedCount > 0))
            {
                if (WouldBlockIntersectAnyPlayer(hit.PrevX, hit.PrevY, hit.PrevZ))
                {
                    _interactCooldown = InteractCooldownSeconds;
                    return;
                }

                _world.SetBlock(hit.PrevX, hit.PrevY, hit.PrevZ, BlockIds.Water);
                _lanSession?.SendBlockSet(hit.PrevX, hit.PrevY, hit.PrevZ, BlockIds.Water);
                QueuePriorityRemeshForBlockEdit(hit.PrevX, hit.PrevY, hit.PrevZ);
                TriggerLocalActionSwing(GetDirectionToBlockCenter(origin, hit.PrevX, hit.PrevY, hit.PrevZ));
                _interactCooldown = InteractCooldownSeconds;
                return;
            }

            if (id == BlockIds.Air && selected != BlockId.Air && (sandbox || _inventory.SelectedCount > 0))
            {
                if (WouldBlockIntersectAnyPlayer(hit.PrevX, hit.PrevY, hit.PrevZ))
                {
                    _interactCooldown = InteractCooldownSeconds;
                    return;
                }
                _world.SetBlock(hit.PrevX, hit.PrevY, hit.PrevZ, (byte)selected);
                _lanSession?.SendBlockSet(hit.PrevX, hit.PrevY, hit.PrevZ, (byte)selected);
                QueuePriorityRemeshForBlockEdit(hit.PrevX, hit.PrevY, hit.PrevZ);
                TriggerLocalActionSwing(GetDirectionToBlockCenter(origin, hit.PrevX, hit.PrevY, hit.PrevZ));
                
                if (!sandbox && _inventory.TryConsumeSelected(1))
                    _interactCooldown = InteractCooldownSeconds;
                if (sandbox)
                    _interactCooldown = InteractCooldownSeconds;
            }
        }
    }

    private float GetBlockBreakCooldownSeconds(byte id)
    {
        return BlockBreakCooldownSeconds;
    }

    private bool TryHandlePlayerMeleeClick(Vector3 origin, Vector3 dir, float blockHitDistance)
    {
        if (_lanSession == null || !_lanSession.IsConnected)
            return false;

        if (!IsCombatEnabledForMode(_gameMode))
            return false;
        if (_gameMode == GameMode.Veilwalker && (_survivalRespawnPending || _survivalVitals.IsDead))
            return false;

        if (!TryGetMeleePlayerTarget(origin, dir, Math.Min(PlayerMeleeRange, blockHitDistance), out var targetPlayerId, out _))
            return false;

        TriggerLocalActionSwing(dir);
        _interactCooldown = InteractCooldownSeconds;

        if (!_pvpEnabled && _gameMode != GameMode.Artificer)
        {
            SetCommandStatus("PvP is disabled in this world.", 2f, echoToChat: false);
            return true;
        }

        if (_lanSession.IsHost)
        {
            TryApplyAuthoritativePlayerHit(_lanSession.LocalPlayerId, targetPlayerId);
            return true;
        }

        if (_remotePlayers.TryGetValue(targetPlayerId, out var targetModel))
            RegisterRemoteHurtFeedback(targetPlayerId, targetModel.Position + new Vector3(0f, targetModel.ColliderHeight * 0.6f, 0f));

        _lanSession.SendPlayerCombat(new LanPlayerCombat
        {
            Kind = LanPlayerCombatKind.Request,
            TargetPlayerId = targetPlayerId,
            Damage = PlayerMeleeDamage
        });

        return true;
    }

    private bool TryGetMeleePlayerTarget(Vector3 origin, Vector3 dir, float maxDistance, out int targetPlayerId, out float hitDistance)
    {
        targetPlayerId = -1;
        hitDistance = float.MaxValue;
        if (maxDistance <= 0f || _remotePlayers.Count == 0)
            return false;

        foreach (var pair in _remotePlayers)
        {
            if (ShouldHideRemotePlayerFromLocal(pair.Key))
                continue;

            var model = pair.Value;
            var min = new Vector3(
                model.Position.X - PlayerController.ColliderHalfWidth,
                model.Position.Y,
                model.Position.Z - PlayerController.ColliderHalfWidth);
            var max = new Vector3(
                model.Position.X + PlayerController.ColliderHalfWidth,
                model.Position.Y + model.ColliderHeight,
                model.Position.Z + PlayerController.ColliderHalfWidth);

            if (!TryRayIntersectsAabbDistance(origin, dir, min, max, out var distance))
                continue;
            if (distance > maxDistance || distance >= hitDistance)
                continue;

            var targetCenter = model.Position + new Vector3(0f, model.ColliderHeight * 0.55f, 0f);
            var toTarget = targetCenter - origin;
            if (toTarget.LengthSquared() <= 0.0001f)
                continue;

            toTarget.Normalize();
            if (Vector3.Dot(dir, toTarget) < PlayerMeleeDotThreshold)
                continue;

            targetPlayerId = pair.Key;
            hitDistance = distance;
        }

        return targetPlayerId >= 0;
    }

    private void HandleNetworkPlayerCombat(LanPlayerCombat combat)
    {
        if (_lanSession == null || !_lanSession.IsConnected)
            return;

        if (_lanSession.IsHost)
        {
            if (combat.Kind == LanPlayerCombatKind.Request)
                TryApplyAuthoritativePlayerHit(combat.AttackerPlayerId, combat.TargetPlayerId);
            return;
        }

        if (combat.Kind != LanPlayerCombatKind.Result)
            return;
        if (combat.TargetPlayerId != _lanSession.LocalPlayerId)
            return;
        if (_gameMode != GameMode.Veilwalker)
            return;

        ApplyIncomingPlayerCombatResult(combat);
    }

    private bool TryApplyAuthoritativePlayerHit(int attackerPlayerId, int targetPlayerId)
    {
        if (_lanSession == null || !_lanSession.IsHost)
            return false;
        if (attackerPlayerId < 0 || targetPlayerId < 0 || attackerPlayerId == targetPlayerId)
            return false;
        if (!TryGetPlayerGameMode(attackerPlayerId, out var attackerMode) || !IsCombatEnabledForMode(attackerMode))
            return false;
        if (!_pvpEnabled && attackerMode != GameMode.Artificer)
            return false;
        if (!TryGetPlayerGameMode(targetPlayerId, out var targetMode) || !IsCombatDamageableMode(targetMode))
            return false;
        if (!TryGetCombatParticipantState(attackerPlayerId, out var attackerPosition, out var attackerOrigin, out var attackerForward, out _, out var attackerAlive))
            return false;
        if (!attackerAlive)
            return false;
        if (!TryGetCombatParticipantState(targetPlayerId, out var targetPosition, out _, out _, out var targetHeight, out var targetAlive))
            return false;
        if (!targetAlive)
            return false;

        var targetCenter = targetPosition + new Vector3(0f, targetHeight * 0.55f, 0f);
        var toTarget = targetCenter - attackerOrigin;
        var distance = toTarget.Length();
        if (distance <= 0.001f || distance > PlayerMeleeRange)
            return false;

        var direction = toTarget / distance;
        if (Vector3.Dot(attackerForward, direction) < PlayerMeleeDotThreshold)
            return false;

        var previousHealth = GetPlayerCombatHealth(targetPlayerId);
        if (previousHealth <= 0)
            return false;

        var newHealth = Math.Max(0, previousHealth - PlayerMeleeDamage);
        var knockback = BuildPlayerKnockback(attackerPosition, targetPosition, attackerForward);
        var impactPosition = targetPosition + new Vector3(0f, targetHeight * 0.6f, 0f);
        if (targetPlayerId == _lanSession.LocalPlayerId)
        {
            ApplyDamageToLocalPlayer(PlayerMeleeDamage, knockback);
            return true;
        }

        _remoteHealthByPlayerId[targetPlayerId] = newHealth;
        if (newHealth <= 0)
            _remoteRespawnPendingByPlayerId[targetPlayerId] = true;
        RegisterRemoteHurtFeedback(targetPlayerId, impactPosition);
        return _lanSession.SendPlayerCombat(new LanPlayerCombat
        {
            Kind = LanPlayerCombatKind.Result,
            AttackerPlayerId = attackerPlayerId,
            TargetPlayerId = targetPlayerId,
            Damage = PlayerMeleeDamage,
            TargetHealth = newHealth,
            TargetDied = newHealth <= 0,
            KnockbackX = knockback.X,
            KnockbackY = knockback.Y,
            KnockbackZ = knockback.Z
        });
    }

    private void ApplyIncomingPlayerCombatResult(LanPlayerCombat combat)
    {
        if (_survivalRespawnPending)
            return;

        var previousHealth = _survivalVitals.Health;
        _survivalVitals.Load(combat.TargetHealth, _survivalVitals.Hunger);
        ApplyLocalPlayerKnockback(new Vector3(combat.KnockbackX, combat.KnockbackY, combat.KnockbackZ));

        var damageTaken = Math.Max(0, previousHealth - _survivalVitals.Health);
        if (damageTaken > 0)
        {
            RegisterLocalHurtFeedback(_player.Position + new Vector3(0f, _player.ColliderHeight * 0.6f, 0f));
            TriggerDamageFeedback(damageTaken);
        }

        MarkPlayerStateDirty();
        if (_survivalVitals.IsDead)
            BeginVeilwalkerRespawn();
    }

    private void ApplyDamageToLocalPlayer(int damage, Vector3 knockback)
    {
        if (!IsCombatDamageableMode(_gameMode) || _survivalRespawnPending || _survivalVitals.IsDead || damage <= 0)
            return;

        if (!_survivalVitals.ApplyDamage(damage))
            return;

        ApplyLocalPlayerKnockback(knockback);
        RegisterLocalHurtFeedback(_player.Position + new Vector3(0f, _player.ColliderHeight * 0.6f, 0f));
        TriggerDamageFeedback(damage);
        MarkPlayerStateDirty();

        if (_survivalVitals.IsDead)
            BeginVeilwalkerRespawn();
    }

    private int GetPlayerCombatHealth(int playerId)
    {
        if (_lanSession != null && playerId == _lanSession.LocalPlayerId)
            return _survivalVitals.Health;

        return _remoteHealthByPlayerId.TryGetValue(playerId, out var health)
            ? health
            : SurvivalVitals.MaxHealth;
    }

    private bool TryGetCombatParticipantState(int playerId, out Vector3 position, out Vector3 origin, out Vector3 forward, out float height, out bool alive)
    {
        position = Vector3.Zero;
        origin = Vector3.Zero;
        forward = Vector3.Forward;
        height = PlayerController.ColliderStandingHeight;
        alive = false;

        if (_lanSession == null)
            return false;

        if (playerId == _lanSession.LocalPlayerId)
        {
            if (!IsCombatEnabledForMode(_gameMode))
                return false;

            position = _player.Position;
            origin = _player.Position + _player.HeadOffset;
            forward = _player.Forward;
            height = _player.ColliderHeight;
            alive = _gameMode == GameMode.Artificer || (!_survivalRespawnPending && !_survivalVitals.IsDead);
            return true;
        }

        if (!_remotePlayers.TryGetValue(playerId, out var model))
            return false;
        if (ShouldHideRemotePlayerFromLocal(playerId))
            return false;
        if (TryGetPlayerGameMode(playerId, out var remoteMode) && remoteMode == GameMode.Veilseer)
            return false;

        position = model.Position;
        height = model.ColliderHeight;
        origin = model.Position + new Vector3(0f, height * 0.85f, 0f);
        forward = PlayerController.GetForwardVector(model.Yaw, model.Pitch);
        alive = !TryGetPlayerGameMode(playerId, out remoteMode)
            || remoteMode == GameMode.Artificer
            || GetPlayerCombatHealth(playerId) > 0;
        return true;
    }

    private bool TryGetPlayerGameMode(int playerId, out GameMode mode)
    {
        mode = GameMode.Veilwalker;
        if (_lanSession != null && playerId == _lanSession.LocalPlayerId)
        {
            mode = _gameMode;
            return true;
        }

        if (_remoteGameModeByPlayerId.TryGetValue(playerId, out mode))
            return true;

        return _remotePlayers.ContainsKey(playerId);
    }

    private bool IsRemoteVeilseerPlayer(int playerId)
    {
        if (_remoteIsVeilseer.TryGetValue(playerId, out var isVeilseer) && isVeilseer)
            return true;

        return TryGetPlayerGameMode(playerId, out var mode) && mode == GameMode.Veilseer;
    }

    private bool ShouldHideRemotePlayerFromLocal(int playerId)
    {
        if (IsRemotePlayerRespawnPending(playerId))
            return true;

        return false;
    }

    private bool IsRemotePlayerRespawnPending(int playerId)
    {
        return _remoteRespawnPendingByPlayerId.TryGetValue(playerId, out var pending) && pending;
    }

    private bool HasActiveRemoteSoulMarker(int playerId)
    {
        return _remoteSoulStates.TryGetValue(playerId, out var remoteSoul)
            && remoteSoul.HasSoulMarker
            && HasAnySoulInventoryItems(remoteSoul.SoulInventory);
    }

    private bool ShouldRenderRemotePlayerAsVeilseerGhost(int playerId)
    {
        return _gameMode == GameMode.Veilseer && IsRemoteVeilseerPlayer(playerId);
    }

    private bool HasActiveRemoteInventoryView()
    {
        var localId = _lanSession?.LocalPlayerId ?? 0;
        return _currentLiveInventoryTarget >= 0 && _currentLiveInventoryTarget != localId;
    }

    private bool TryGetActiveRemoteInventoryView(out LanInventoryView liveView)
    {
        if (HasActiveRemoteInventoryView()
            && _liveInventoryViews.TryGetValue(_currentLiveInventoryTarget, out liveView))
        {
            return true;
        }

        liveView = default;
        return false;
    }

    private void ResetLiveInventoryMirrorState(int targetId = -1)
    {
        if (targetId >= 0)
            _liveInventoryViews.Remove(targetId);
        else
            _liveInventoryViews.Clear();

        _liveInventoryTargetPlayerId = -1;
        _liveInventoryTargetName = string.Empty;
        _liveInventoryState = null;
        _liveInventoryViewActive = false;
        _liveInventoryAutoSpectate = false;
        _liveInventoryPendingHostSubscription = false;
        _liveInventoryLastUpdateUtc = 0;
        _liveInventorySelectedIndex = 0;

        Array.Clear(_liveInventoryHotbar, 0, _liveInventoryHotbar.Length);
        Array.Clear(_liveInventoryGrid, 0, _liveInventoryGrid.Length);
    }

    private bool ShouldUseLiveInventoryHud(out LanInventoryView liveView)
    {
        if (TryGetActiveRemoteInventoryView(out liveView))
            return true;

        liveView = default;
        return false;
    }

    private void ApplyLiveInventorySnapshot(LanInventoryView inventoryView)
    {
        _liveInventoryTargetPlayerId = inventoryView.TargetPlayerId;
        _liveInventoryTargetName = ResolvePlayerName(inventoryView.TargetPlayerId);
        _liveInventoryViewActive = true;
        _liveInventoryLastUpdateUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        if (inventoryView.TargetPlayerId == _currentLiveInventoryTarget)
            SetCommandStatus($"InvView: snapshot applied for P{inventoryView.TargetPlayerId}.", 1.0f, echoToChat: false);

        UpdateLiveInventoryDisplay(inventoryView);

        var hotbarIds = inventoryView.HotbarIds ?? Array.Empty<byte>();
        var hotbarCounts = inventoryView.HotbarCounts ?? Array.Empty<byte>();
        var gridIds = inventoryView.GridIds ?? Array.Empty<byte>();
        var gridCounts = inventoryView.GridCounts ?? Array.Empty<byte>();

        Array.Clear(_liveInventoryHotbar, 0, _liveInventoryHotbar.Length);
        Array.Clear(_liveInventoryGrid, 0, _liveInventoryGrid.Length);

        for (int i = 0; i < Math.Min(hotbarIds.Length, Inventory.HotbarSize); i++)
        {
            _liveInventoryHotbar[i] = new HotbarSlot
            {
                Id = (BlockId)(hotbarIds[i]),
                Count = hotbarCounts.Length > i ? hotbarCounts[i] : (byte)0
            };
        }

        for (int i = 0; i < Math.Min(gridIds.Length, Inventory.GridSize); i++)
        {
            _liveInventoryGrid[i] = new HotbarSlot
            {
                Id = (BlockId)(gridIds[i]),
                Count = gridCounts.Length > i ? gridCounts[i] : (byte)0
            };
        }

        _liveInventorySelectedIndex = Math.Clamp(inventoryView.SelectedIndex, 0, Inventory.HotbarSize - 1);
    }

    private void UpdateSpectatedInventoryViewTarget()
    {
        if (_gameMode != GameMode.Veilseer || _veilseerSpectateTargetPlayerId < 0)
            return;

        RequestInventoryView(_veilseerSpectateTargetPlayerId, openUi: false);
    }

    private bool TryOpenVeilseerSpectatedInventory()
    {
        if (_gameMode != GameMode.Veilseer)
            return false;

        if (_veilseerSpectateTargetPlayerId < 0)
        {
            SetCommandStatus("Spectate a player first to view their live inventory.", 2.5f, echoToChat: false);
            return true;
        }

        RequestInventoryView(_veilseerSpectateTargetPlayerId, openUi: true);
        _inventoryOpen = true;
        _inventoryCatalogSearchFocused = false;
        _inventoryCatalogSearchCaret = 0;
        return true;
    }

    private void ResetSpectateCameraSmoothing()
    {
        _spectateCameraTargetPlayerId = -1;
        _spectateCameraInitialized = false;
        _spectateCameraForward = Vector3.UnitX;
    }

    private void UpdateSpectateCameraSmoothing(float dt)
    {
        if (_gameMode != GameMode.Veilseer
            || _veilseerSpectateTargetPlayerId < 0
            || !_remotePlayers.TryGetValue(_veilseerSpectateTargetPlayerId, out var observed))
        {
            ResetSpectateCameraSmoothing();
            return;
        }

        var observedVelocity = _remoteVelocityByPlayerId.TryGetValue(_veilseerSpectateTargetPlayerId, out var remoteVelocity)
            ? remoteVelocity
            : Vector3.Zero;
        var predictionLeadSeconds = 0.045f;
        var desiredEye = observed.Position + (observedVelocity * predictionLeadSeconds) + _player.HeadOffset;
        var desiredForward = PlayerController.GetForwardVector(observed.Yaw, observed.Pitch);
        if (desiredForward.LengthSquared() <= 0.0001f)
            desiredForward = Vector3.UnitX;
        else
            desiredForward.Normalize();

        if (!_spectateCameraInitialized || _spectateCameraTargetPlayerId != _veilseerSpectateTargetPlayerId)
        {
            _spectateCameraEye = desiredEye;
            _spectateCameraForward = desiredForward;
            _spectateCameraTargetPlayerId = _veilseerSpectateTargetPlayerId;
            _spectateCameraInitialized = true;
            return;
        }

        var safeDt = Math.Max(0f, dt);
        var positionLerp = 1f - MathF.Exp(-24f * safeDt);
        var forwardLerp = 1f - MathF.Exp(-20f * safeDt);
        _spectateCameraEye = Vector3.Lerp(_spectateCameraEye, desiredEye, positionLerp);
        _spectateCameraForward = Vector3.Lerp(_spectateCameraForward, desiredForward, forwardLerp);
        if (_spectateCameraForward.LengthSquared() <= 0.0001f)
            _spectateCameraForward = desiredForward;
        else
            _spectateCameraForward.Normalize();
    }

    private bool TryGetSpectatedCameraState(out Vector3 eye, out Vector3 forward)
    {
        if (_gameMode == GameMode.Veilseer
            && _veilseerSpectateTargetPlayerId >= 0
            && _remotePlayers.ContainsKey(_veilseerSpectateTargetPlayerId)
            && _spectateCameraInitialized)
        {
            eye = _spectateCameraEye;
            forward = _spectateCameraForward;
            return true;
        }

        eye = default;
        forward = default;
        return false;
    }

    private bool TryConsumeSelectedForWorldDrop(int amount, out BlockId id)
    {
        id = _inventory.SelectedId;
        if (amount <= 0 || id == BlockId.Air || _inventory.SelectedCount < amount)
            return false;

        if (_gameMode == GameMode.Artificer)
        {
            ref var slot = ref _inventory.Hotbar[_inventory.SelectedIndex];
            slot.Count -= amount;
            if (slot.Count <= 0)
            {
                slot.Id = BlockId.Air;
                slot.Count = 0;
            }

            MarkPlayerStateDirty();
            return true;
        }

        return _inventory.TryConsumeSelected(amount);
    }

    private static bool IsCombatEnabledForMode(GameMode mode)
    {
        return mode is GameMode.Artificer or GameMode.Veilwalker;
    }

    private static bool IsCombatDamageableMode(GameMode mode)
    {
        return mode == GameMode.Veilwalker;
    }

    private static Vector3 BuildPlayerKnockback(Vector3 attackerPosition, Vector3 targetPosition, Vector3 attackerForward)
    {
        var horizontal = new Vector2(targetPosition.X - attackerPosition.X, targetPosition.Z - attackerPosition.Z);
        if (horizontal.LengthSquared() < 0.0001f)
            horizontal = new Vector2(attackerForward.X, attackerForward.Z);

        if (horizontal.LengthSquared() < 0.0001f)
            horizontal = Vector2.UnitX;
        else
            horizontal.Normalize();

        return new Vector3(
            horizontal.X * PlayerMeleeKnockbackHorizontal,
            PlayerMeleeKnockbackVertical,
            horizontal.Y * PlayerMeleeKnockbackHorizontal);
    }

    private void ApplyLocalPlayerKnockback(Vector3 knockback)
    {
        _player.AddImpulse(knockback);
    }

    private void RegisterLocalHurtFeedback(Vector3 impactPosition)
    {
        _localHurtOutlineTimer = HurtOutlineDurationSeconds;
        SpawnHurtParticles(impactPosition);
    }

    private void RegisterRemoteHurtFeedback(int playerId, Vector3 impactPosition)
    {
        if (playerId < 0)
            return;

        _remoteHurtOutlineTimers[playerId] = HurtOutlineDurationSeconds;
        SpawnHurtParticles(impactPosition);
    }

    private void SpawnHurtParticles(Vector3 impactPosition)
    {
        if (ShouldUseReducedHurtFeedback())
            return;

        var overflow = (_hurtParticles.Count + HurtParticleSpawnCount) - HurtParticleMaxCount;
        if (overflow > 0)
            _hurtParticles.RemoveRange(0, Math.Min(overflow, _hurtParticles.Count));

        for (var i = 0; i < HurtParticleSpawnCount; i++)
        {
            var speed = 0.9f * Scale.BlockSize + (float)_hurtFeedbackRandom.NextDouble() * (2.6f * Scale.BlockSize);
            var horizontal = new Vector2(
                (float)_hurtFeedbackRandom.NextDouble() * 2f - 1f,
                (float)_hurtFeedbackRandom.NextDouble() * 2f - 1f);
            if (horizontal.LengthSquared() < 0.0001f)
                horizontal = Vector2.UnitX;
            else
                horizontal.Normalize();

            var upwardKick = 0.35f * Scale.BlockSize + (float)_hurtFeedbackRandom.NextDouble() * (1.25f * Scale.BlockSize);
            var sidewaysJitter = 0.08f * Scale.BlockSize + (float)_hurtFeedbackRandom.NextDouble() * (0.28f * Scale.BlockSize);

            _hurtParticles.Add(new HurtParticle
            {
                Position = impactPosition + new Vector3(
                    ((float)_hurtFeedbackRandom.NextDouble() - 0.5f) * 0.22f,
                    ((float)_hurtFeedbackRandom.NextDouble() - 0.15f) * 0.28f,
                    ((float)_hurtFeedbackRandom.NextDouble() - 0.5f) * 0.22f),
                Velocity = new Vector3(
                    horizontal.X * speed + (((float)_hurtFeedbackRandom.NextDouble() - 0.5f) * sidewaysJitter),
                    upwardKick,
                    horizontal.Y * speed + (((float)_hurtFeedbackRandom.NextDouble() - 0.5f) * sidewaysJitter)),
                Lifetime = HurtParticleLifetimeMin + (float)_hurtFeedbackRandom.NextDouble() * (HurtParticleLifetimeMax - HurtParticleLifetimeMin)
            });
        }
    }

    private void UpdateHurtFeedback(float dt)
    {
        _localHurtOutlineTimer = Math.Max(0f, _localHurtOutlineTimer - dt);

        if (_remoteHurtOutlineTimers.Count > 0)
        {
            foreach (var playerId in _remoteHurtOutlineTimers.Keys.ToArray())
            {
                var next = Math.Max(0f, _remoteHurtOutlineTimers[playerId] - dt);
                if (next <= 0f)
                    _remoteHurtOutlineTimers.Remove(playerId);
                else
                    _remoteHurtOutlineTimers[playerId] = next;
            }
        }

        for (var i = _hurtParticles.Count - 1; i >= 0; i--)
        {
            var particle = _hurtParticles[i];
            particle.Age += dt;
            if (particle.Age >= particle.Lifetime)
            {
                _hurtParticles.RemoveAt(i);
                continue;
            }

            particle.Velocity += new Vector3(0f, -HurtParticleGravity * dt, 0f);
            particle.Position += particle.Velocity * dt;
            _hurtParticles[i] = particle;
        }
    }

    private bool ShouldUseReducedHurtFeedback()
    {
        var preset = (_settings.ParticlePreset ?? string.Empty).Trim().ToUpperInvariant();
        return preset is "OFF";
    }

    private static bool TryRayIntersectsAabbDistance(Vector3 origin, Vector3 dir, Vector3 min, Vector3 max, out float distance)
    {
        const float epsilon = 0.0001f;
        var tMin = 0f;
        var tMax = float.MaxValue;

        if (!ClipRayAxis(origin.X, dir.X, min.X, max.X, ref tMin, ref tMax, epsilon)
            || !ClipRayAxis(origin.Y, dir.Y, min.Y, max.Y, ref tMin, ref tMax, epsilon)
            || !ClipRayAxis(origin.Z, dir.Z, min.Z, max.Z, ref tMin, ref tMax, epsilon))
        {
            distance = 0f;
            return false;
        }

        distance = Math.Max(0f, tMin);
        return tMax >= distance;
    }

    private void HandleHotbarInput(InputState input)
    {
        if (input.ScrollDelta != 0)
        {
            if (_gameMode == GameMode.Veilseer)
            {
                var speedStep = input.ScrollDelta > 0 ? 1 : -1;
                if (_player.AdjustFlySpeedMultiplier(speedStep))
                    ShowFlySpeedToast();
            }
            else if (_player.IsFlying && IsActionDown(input, "GamemodeModifier", Keys.LeftAlt))
            {
                var speedStep = input.ScrollDelta > 0 ? 1 : -1;
                if (_player.AdjustFlySpeedMultiplier(speedStep))
                    ShowFlySpeedToast();
            }
            else
            {
                var step = input.ScrollDelta > 0 ? -1 : 1;
                _inventory.Scroll(step);
            }
        }

        if (_gameMode == GameMode.Veilseer)
        {
            TryHandleVeilseerSpectateNumberInput(input);
            TryHandleVeilseerSpectateClick(input);
            return;
        }

        if (input.IsNewKeyPress(Keys.D1) || input.IsNewKeyPress(Keys.NumPad1)) _inventory.Select(0);
        if (input.IsNewKeyPress(Keys.D2) || input.IsNewKeyPress(Keys.NumPad2)) _inventory.Select(1);
        if (input.IsNewKeyPress(Keys.D3) || input.IsNewKeyPress(Keys.NumPad3)) _inventory.Select(2);
        if (input.IsNewKeyPress(Keys.D4) || input.IsNewKeyPress(Keys.NumPad4)) _inventory.Select(3);
        if (input.IsNewKeyPress(Keys.D5) || input.IsNewKeyPress(Keys.NumPad5)) _inventory.Select(4);
        if (input.IsNewKeyPress(Keys.D6) || input.IsNewKeyPress(Keys.NumPad6)) _inventory.Select(5);
        if (input.IsNewKeyPress(Keys.D7) || input.IsNewKeyPress(Keys.NumPad7)) _inventory.Select(6);
        if (input.IsNewKeyPress(Keys.D8) || input.IsNewKeyPress(Keys.NumPad8)) _inventory.Select(7);
        if (input.IsNewKeyPress(Keys.D9) || input.IsNewKeyPress(Keys.NumPad9)) _inventory.Select(8);

        if (input.IsNewLeftClick() && _hotbarRect.Contains(input.MousePosition))
        {
            for (int i = 0; i < _hotbarSlots.Length; i++)
            {
                if (_hotbarSlots[i].Contains(input.MousePosition))
                {
                    _inventory.Select(i);
                    break;
                }
            }
        }
    }

    private void ShowFlySpeedToast()
    {
        _flySpeedToastText = $"FLY SPEED {(_player.FlySpeedMultiplier * 100f):0}%";
        _flySpeedToastPercent = Math.Clamp(_player.FlySpeedNormalized, 0f, 1f);
        _flySpeedToastTimer = 1.8f;
    }

    private static Vector3 GetDirectionToBlockCenter(Vector3 origin, int x, int y, int z)
    {
        var target = new Vector3(x + 0.5f, y + 0.5f, z + 0.5f);
        var dir = target - origin;
        if (dir.LengthSquared() <= 0.0001f)
            return Vector3.UnitX;

        dir.Normalize();
        return dir;
    }

    private void TriggerLocalActionSwing(Vector3 worldAimDirection)
    {
        if (_localActionSwingTimer > LocalActionSwingRestartWindowSeconds)
            return;

        _localActionSwingTimer = LocalActionSwingDurationSeconds;
        _playerModel?.TriggerActionSwing(worldAimDirection);
    }

    private bool TryHandleVeilseerSpectateNumberInput(InputState input)
    {
        var shiftPressed = input.IsNewKeyPress(Keys.LeftShift) || input.IsNewKeyPress(Keys.RightShift);
        if (shiftPressed && _veilseerSpectateTargetPlayerId >= 0)
            return DetachVeilseerSpectateAtCurrentView("Detached to VeilSeer free camera.");

        var slot = -1;
        if (input.IsNewKeyPress(Keys.D1) || input.IsNewKeyPress(Keys.NumPad1)) slot = 0;
        else if (input.IsNewKeyPress(Keys.D2) || input.IsNewKeyPress(Keys.NumPad2)) slot = 1;
        else if (input.IsNewKeyPress(Keys.D3) || input.IsNewKeyPress(Keys.NumPad3)) slot = 2;
        else if (input.IsNewKeyPress(Keys.D4) || input.IsNewKeyPress(Keys.NumPad4)) slot = 3;
        else if (input.IsNewKeyPress(Keys.D5) || input.IsNewKeyPress(Keys.NumPad5)) slot = 4;
        else if (input.IsNewKeyPress(Keys.D6) || input.IsNewKeyPress(Keys.NumPad6)) slot = 5;
        else if (input.IsNewKeyPress(Keys.D7) || input.IsNewKeyPress(Keys.NumPad7)) slot = 6;
        else if (input.IsNewKeyPress(Keys.D8) || input.IsNewKeyPress(Keys.NumPad8)) slot = 7;
        else if (input.IsNewKeyPress(Keys.D9) || input.IsNewKeyPress(Keys.NumPad9)) slot = 8;
        else if (input.IsNewKeyPress(Keys.D0) || input.IsNewKeyPress(Keys.NumPad0))
        {
            return DetachVeilseerSpectateAtCurrentView("VeilSeer free camera restored.");
        }

        if (slot < 0)
            return false;

        var available = _remotePlayers.Keys
            .Where(id => !ShouldHideRemotePlayerFromLocal(id))
            .OrderBy(id => id)
            .ToArray();
        if (slot >= available.Length)
        {
            SetCommandStatus($"No player in VeilSeer slot {slot + 1}.", 2.5f);
            return false;
        }

        _veilseerSpectateTargetPlayerId = available[slot];
        _veilseerSpectateSlot = slot;
        var targetName = ResolvePlayerName(_veilseerSpectateTargetPlayerId);
        SetVeilseerSpectatePopup($"Spectating: {targetName}");
        if (_remotePlayers.TryGetValue(_veilseerSpectateTargetPlayerId, out var targetModel))
            PrimeStreamingAroundPosition(targetModel.Position);
        UpdateSpectatedInventoryViewTarget();
        SetCommandStatus($"VeilSeer spectating {targetName} (slot {slot + 1}).", 2.5f);
        return true;
    }

    private bool DetachVeilseerSpectateAtCurrentView(string statusMessage)
    {
        if (_veilseerSpectateTargetPlayerId < 0)
            return false;

        if (_remotePlayers.TryGetValue(_veilseerSpectateTargetPlayerId, out var observed))
        {
            _player.Position = observed.Position;
            _player.Yaw = observed.Yaw;
            _player.Pitch = observed.Pitch;
        }

        _veilseerSpectateTargetPlayerId = -1;
        _veilseerSpectateSlot = -1;
        ResetSpectateCameraSmoothing();
        if (HasActiveRemoteInventoryView())
            ClearInventoryView(preserveSpectate: true);
        SetVeilseerSpectatePopup("Free Camera");
        SetCommandStatus(statusMessage, 2.5f);
        return true;
    }

    private void SetVeilseerSpectatePopup(string text, float seconds = 2.2f)
    {
        _veilseerSpectatePopupText = text ?? string.Empty;
        _veilseerSpectatePopupTimer = Math.Max(0f, seconds);
    }

    private void TryHandleVeilseerSpectateClick(InputState input)
    {
        if (!input.IsNewLeftClick())
            return;

        // Don't allow clicking if already spectating a player
        if (_veilseerSpectateTargetPlayerId >= 0)
            return;

        // Ray-pick the closest visible remote player under the crosshair.
        var closestPlayerId = -1;
        var closestDistanceSq = float.MaxValue;
        var cameraPosition = _player.Position;
        var viewDirection = PlayerController.GetForwardVector(_player.Yaw, _player.Pitch);
        
        foreach (var pair in _remotePlayers)
        {
            // Skip hidden players.
            if (ShouldHideRemotePlayerFromLocal(pair.Key))
                continue;
                
            var targetPos = pair.Value.Position + new Vector3(0f, pair.Value.ColliderHeight * 0.5f, 0f);
            var toTarget = targetPos - cameraPosition;
            var distanceSq = toTarget.LengthSquared();
            
            // Simple distance-based selection (could be enhanced with actual raycasting)
            if (distanceSq < closestDistanceSq && distanceSq < 25f) // Within 5 blocks
            {
                var dot = Vector3.Dot(Vector3.Normalize(toTarget), viewDirection);
                if (dot > 0.7f) // Within ~45 degrees of crosshair
                {
                    closestDistanceSq = distanceSq;
                    closestPlayerId = pair.Key;
                }
            }
        }

        if (closestPlayerId >= 0)
        {
            _veilseerSpectateTargetPlayerId = closestPlayerId;
            var targetName = ResolvePlayerName(closestPlayerId);
            SetVeilseerSpectatePopup($"Spectating: {targetName}");
            if (_remotePlayers.TryGetValue(closestPlayerId, out var targetModel))
                PrimeStreamingAroundPosition(targetModel.Position);
            UpdateSpectatedInventoryViewTarget();
            SetCommandStatus($"VeilSeer spectating {targetName}.", 2.5f);
        }
        // On miss, do nothing (no detach) as per plan
    }

    private void PrimeStreamingAroundPosition(Vector3 worldPosition, int horizontalRadius = 2)
    {
        if (_world == null)
            return;

        var focusChunk = VoxelWorld.WorldToChunk(
            (int)MathF.Floor(worldPosition.X),
            (int)MathF.Floor(worldPosition.Y),
            (int)MathF.Floor(worldPosition.Z),
            out _, out _, out _);

        var radius = Math.Clamp(horizontalRadius, 1, 4);
        var radiusSq = radius * radius;
        var maxCy = GetStreamingMaxChunkY(focusChunk.Y);
        var minCy = Math.Max(0, focusChunk.Y - 1);
        var focusTopCy = Math.Min(maxCy, focusChunk.Y + 1);

        for (var dz = -radius; dz <= radius; dz++)
        {
            for (var dx = -radius; dx <= radius; dx++)
            {
                if (dx * dx + dz * dz > radiusSq)
                    continue;

                for (var cy = minCy; cy <= focusTopCy; cy++)
                {
                    var coord = new ChunkCoord(focusChunk.X + dx, cy, focusChunk.Z + dz);
                    if (!IsChunkWithinWorldBounds(coord))
                        continue;

                    if (!_world.TryGetChunk(coord, out var chunk) || chunk == null)
                        QueueChunkGeneration(coord);

                    QueuePriorityMeshBuild(coord);
                }
            }
        }
    }

    private bool WouldBlockIntersectAnyPlayer(int x, int y, int z)
    {
        var blockMin = new Vector3(x, y, z);
        var blockMax = new Vector3(x + 1f, y + 1f, z + 1f);

        if (IntersectsPlayerAabb(_player.Position, _player.ColliderHeight, blockMin, blockMax))
            return true;

        foreach (var model in _remotePlayers.Values)
        {
            if (IntersectsPlayerAabb(model.Position, model.ColliderHeight, blockMin, blockMax))
                return true;
        }

        return false;
    }

    private static bool IntersectsPlayerAabb(Vector3 pos, float height, Vector3 blockMin, Vector3 blockMax)
    {
        const float eps = 0.001f;
        var half = PlayerController.ColliderHalfWidth;
        var min = new Vector3(pos.X - half + eps, pos.Y + eps, pos.Z - half + eps);
        var max = new Vector3(pos.X + half - eps, pos.Y + height - eps, pos.Z + half - eps);
        return min.X < blockMax.X && max.X > blockMin.X
            && min.Y < blockMax.Y && max.Y > blockMin.Y
            && min.Z < blockMax.Z && max.Z > blockMin.Z;
    }

    private void UpdateHandoffTarget(InputState input)
    {
        _handoffPromptVisible = false;
        _handoffTargetId = -1;
        _handoffTargetName = string.Empty;

        if (_pauseMenuOpen || _inventoryOpen || _lanSession == null || (_gameMode != GameMode.Veilwalker && _gameMode != GameMode.Artificer))
            return;

        if (!_giveItemsEnabled)
            return;

        if (_inventory.SelectedId == BlockId.Air || _inventory.SelectedCount <= 0)
            return;

        if (_remotePlayers.Count == 0)
            return;

        var origin = _player.Position + _player.HeadOffset;
        var forward = _player.Forward;
        var bestDistSq = HandoffRange * HandoffRange;
        var targetId = -1;
        var targetName = "";

        foreach (var pair in _remotePlayers)
        {
            var id = pair.Key;
            var model = pair.Value;
            var targetPos = model.Position + new Vector3(0f, Scale.PlayerHeadHeight * 0.5f, 0f);
            var toTarget = targetPos - origin;
            var distSq = toTarget.LengthSquared();
            if (distSq > bestDistSq)
                continue;

            var dir = toTarget;
            if (dir.LengthSquared() <= 0.0001f)
                continue;
            dir.Normalize();

            if (Vector3.Dot(dir, forward) < HandoffDotThreshold)
                continue;

            bestDistSq = distSq;
            targetId = id;
            targetName = ResolvePlayerName(id);
        }

        if (targetId >= 0)
        {
            _handoffTargetId = targetId;
            _handoffTargetName = targetName;
            _handoffPromptVisible = true;
        }
    }

    private void HandleUseItem(InputState input)
    {
        if (_pauseMenuOpen || _inventoryOpen || _gameMode != GameMode.Veilwalker)
            return;

        if (!IsNewActionPress(input, "UseItem", Keys.R))
            return;

        if (!TryConsumeHeldVeilwalkerItem())
            SetCommandStatus("That item is not usable yet.", 1.8f, echoToChat: false);
    }

    private bool TryConsumeHeldVeilwalkerItem()
    {
        var selected = _inventory.SelectedId;
        if (selected == BlockId.Air || _inventory.SelectedCount <= 0)
            return false;

        if (!TryGetConsumableEffects(selected, out var hungerRestore, out var healthRestore, out var returnsPhial))
            return false;

        if (_survivalVitals.Hunger >= SurvivalVitals.MaxHunger && _survivalVitals.Health >= SurvivalVitals.MaxHealth)
        {
            SetCommandStatus("You are already fully recovered.", 1.8f, echoToChat: false);
            return true;
        }

        if (!_inventory.TryConsumeSelected(1))
            return false;

        var hungerChanged = _survivalVitals.RestoreHunger(hungerRestore);
        var healthChanged = _survivalVitals.RestoreHealth(healthRestore);
        if (returnsPhial)
            _inventory.Add(BlockId.CleanPhial, 1);

        MarkPlayerStateDirty();
        var effectParts = new List<string>(2);
        if (hungerChanged && hungerRestore > 0)
            effectParts.Add($"+{hungerRestore} hunger");
        if (healthChanged && healthRestore > 0)
            effectParts.Add($"+{healthRestore} health");
        if (effectParts.Count == 0)
            effectParts.Add("no effect");

        var itemName = BlockRegistry.Get(selected).Name;
        SetCommandStatus($"{itemName}: {string.Join(", ", effectParts)}.", 2.2f, echoToChat: false);
        return true;
    }

    private static bool TryGetConsumableEffects(BlockId item, out int hungerRestore, out int healthRestore, out bool returnsPhial)
    {
        returnsPhial = false;
        switch (item)
        {
            case BlockId.Swiftleaf:
                hungerRestore = 3;
                healthRestore = 0;
                return true;
            case BlockId.Driftcap:
                hungerRestore = 4;
                healthRestore = 0;
                return true;
            case BlockId.EchoBloom:
                hungerRestore = 2;
                healthRestore = 1;
                return true;
            case BlockId.FleetstepDraught:
                hungerRestore = 3;
                healthRestore = 1;
                returnsPhial = true;
                return true;
            case BlockId.SkyboundPhilter:
                hungerRestore = 2;
                healthRestore = 2;
                returnsPhial = true;
                return true;
            case BlockId.PyroskinTonic:
                hungerRestore = 1;
                healthRestore = 3;
                returnsPhial = true;
                return true;
            case BlockId.BrineveilElixir:
                hungerRestore = 0;
                healthRestore = 5;
                returnsPhial = true;
                return true;
            default:
                hungerRestore = 0;
                healthRestore = 0;
                return false;
        }
    }

    private void HandleDropAndGive(InputState input)
    {
        if (_pauseMenuOpen || _inventoryOpen || _gameMode == GameMode.Veilseer)
            return;

        if (_inventory.SelectedId == BlockId.Air || _inventory.SelectedCount <= 0)
            return;

        var fullStack = IsStackModifierDown(input);

        if ((_gameMode == GameMode.Veilwalker || _gameMode == GameMode.Artificer)
            && _giveItemsEnabled
            && _handoffTargetId >= 0
            && IsNewActionPress(input, "GiveItem", Keys.F))
        {
            var amount = fullStack ? _inventory.SelectedCount : 1;
            if (TryHandoffSelectedItemDirect(_handoffTargetId, amount, out var handoffStatus))
                SetCommandStatus(handoffStatus, 3f, echoToChat: true);
            return;
        }

        if (IsNewActionPress(input, "DropItem", Keys.Q))
        {
            var amount = fullStack ? _inventory.SelectedCount : 1;
            if (!TryConsumeSelectedForWorldDrop(amount, out var id))
                return;

            SpawnDroppedItem(id, amount);
        }
    }

    private bool IsStackModifierDown(InputState input)
    {
        if (_stackModifierKey == Keys.LeftShift || _stackModifierKey == Keys.RightShift)
            return input.IsKeyDown(Keys.LeftShift) || input.IsKeyDown(Keys.RightShift);
        return IsActionDown(input, "Crouch", Keys.LeftShift);
    }

    private bool TryGetHandoffTargetPosition(int targetId, out Vector3 position)
    {
        if (_remotePlayers.TryGetValue(targetId, out var model))
        {
            position = model.Position + new Vector3(0f, Scale.PlayerHeadHeight * 0.4f, 0f);
            return true;
        }

        position = default;
        return false;
    }

    private int NextItemId()
    {
        var owner = _lanSession?.LocalPlayerId ?? 0;
        var seq = _nextItemId++;
        return (owner << 24) | (seq & 0x00FFFFFF);
    }

    private void SpawnBlockDrop(int x, int y, int z, BlockId id)
    {
        var spawn = new LanItemSpawn
        {
            ItemId = NextItemId(),
            BlockId = (byte)id,
            Count = 1,
            X = x + 0.5f,
            Y = y + 0.5f,
            Z = z + 0.5f,
            VelX = 0f,
            VelY = 0f,
            VelZ = 0f,
            PickupDelay = ItemPickupDelaySeconds,
            PickupLockPlayerId = _lanSession?.LocalPlayerId ?? -1
        };
        SpawnWorldItem(spawn);
        SendItemSpawn(spawn);
    }

    private void SpawnDroppedItem(BlockId id, int count)
    {
        if (_world == null || count <= 0)
            return;

        var origin = _player.Position + _player.HeadOffset * 0.6f;
        var forward = _player.Forward;
        var tossDir = new Vector3(forward.X, 0f, forward.Z);
        if (tossDir.LengthSquared() < 0.001f)
            tossDir = Vector3.UnitZ;
        tossDir.Normalize();
        var spawnPos = origin + tossDir * 0.6f + new Vector3(0f, 0.1f, 0f);
        var velocity = tossDir * (3.0f * Scale.BlockSize) + new Vector3(0f, 2.5f * Scale.BlockSize, 0f);
        var spawn = new LanItemSpawn
        {
            ItemId = NextItemId(),
            BlockId = (byte)id,
            Count = count,
            X = spawnPos.X,
            Y = spawnPos.Y,
            Z = spawnPos.Z,
            VelX = velocity.X,
            VelY = velocity.Y,
            VelZ = velocity.Z,
            PickupDelay = ItemDropPickupDelaySeconds,
            PickupLockPlayerId = _lanSession?.LocalPlayerId ?? -1
        };
        SpawnWorldItem(spawn);
        SendItemSpawn(spawn);
    }

    private void SendItemSpawn(LanItemSpawn spawn)
    {
        if (_lanSession == null)
            return;
        _lanSession.SendItemSpawn(spawn);
    }

    private void SendItemPickup(int itemId)
    {
        if (_lanSession == null)
            return;
        _lanSession.SendItemPickup(itemId);
    }

    private void SpawnWorldItem(LanItemSpawn spawn)
    {
        if (_world == null)
            return;

        if (spawn.Count <= 0 || spawn.BlockId == (byte)BlockId.Air)
            return;

        if (_worldItems.ContainsKey(spawn.ItemId))
            return;

        var item = new WorldItem
        {
            ItemId = spawn.ItemId,
            BlockId = (BlockId)spawn.BlockId,
            Count = spawn.Count,
            Position = new Vector3(spawn.X, spawn.Y, spawn.Z),
            Velocity = new Vector3(spawn.VelX, spawn.VelY, spawn.VelZ),
            SpawnTime = _worldTimeSeconds,
            LastUpdateTime = _worldTimeSeconds,
            PickupDelay = spawn.PickupDelay,
            PickupLockPlayerId = spawn.PickupLockPlayerId
        };

        _worldItems[item.ItemId] = item;
    }

    private void RemoveWorldItem(int itemId)
    {
        _worldItems.Remove(itemId);
    }

    private void UpdateWorldItems()
    {
        if (_world == null || _worldItems.Count == 0)
            return;

        var playerPos = _player.Position + new Vector3(0f, Scale.PlayerHeadHeight * 0.5f, 0f);

        _worldItemRemove.Clear();
        foreach (var pair in _worldItems)
        {
            var item = pair.Value;
            if (item.Count <= 0 || item.BlockId == BlockId.Air)
            {
                _worldItemRemove.Add(item.ItemId);
                continue;
            }

            var dt = Math.Clamp(_worldTimeSeconds - item.LastUpdateTime, 0f, 0.1f);
            if (dt > 0f)
            {
                var vel = item.Velocity;
                if (!item.IsGrounded || vel.Y > 0f)
                    vel.Y += ItemGravity * dt;
                else
                    vel.Y = 0f;
                vel.X *= ItemAirDrag;
                vel.Z *= ItemAirDrag;

                var newPos = item.Position + vel * dt;
                var groundedThisFrame = false;

                if (vel.Y <= 0f && TrySnapToGround(newPos, out var groundedPos))
                {
                    newPos = groundedPos;
                    vel.Y = 0f;
                    vel.X *= ItemGroundFriction;
                    vel.Z *= ItemGroundFriction;
                    groundedThisFrame = true;
                }
                else if (IsSolidAt(newPos))
                {
                    var cellY = (int)Math.Floor(newPos.Y);
                    newPos.Y = cellY + 1f + ItemGroundOffset;
                    if (vel.Y < 0f)
                        vel.Y = 0f;
                    groundedThisFrame = true;
                }

                item.Position = newPos;
                item.Velocity = vel;
                item.LastUpdateTime = _worldTimeSeconds;
                if (groundedThisFrame)
                {
                    if (!item.IsGrounded)
                    {
                        item.GroundedTime = _worldTimeSeconds;
                        item.LandedBlockX = (int)MathF.Floor(newPos.X);
                        item.LandedBlockZ = (int)MathF.Floor(newPos.Z);
                        item.HasLandedBlock = true;
                    }
                    item.IsGrounded = true;
                    if (item.HasLandedBlock)
                    {
                        var minX = item.LandedBlockX + 0.14f;
                        var maxX = item.LandedBlockX + 0.86f;
                        var minZ = item.LandedBlockZ + 0.14f;
                        var maxZ = item.LandedBlockZ + 0.86f;
                        item.Position = new Vector3(
                            Math.Clamp(item.Position.X, minX, maxX),
                            item.Position.Y,
                            Math.Clamp(item.Position.Z, minZ, maxZ));
                        if (item.Position.X <= minX + 0.0001f || item.Position.X >= maxX - 0.0001f)
                            item.Velocity = new Vector3(0f, item.Velocity.Y, item.Velocity.Z);
                        if (item.Position.Z <= minZ + 0.0001f || item.Position.Z >= maxZ - 0.0001f)
                            item.Velocity = new Vector3(item.Velocity.X, item.Velocity.Y, 0f);
                    }
                }
                else
                {
                    item.IsGrounded = false;
                }
            }

            if (item.PickupDelay > 0f)
            {
                var elapsed = _worldTimeSeconds - item.SpawnTime;
                if (elapsed < item.PickupDelay)
                    continue;
            }

            if (item.IsGrounded && _worldTimeSeconds - item.GroundedTime < ItemGroundPickupDelaySeconds)
                continue;

            var distSq = Vector3.DistanceSquared(item.Position, playerPos);
            if (distSq > ItemPickupRadiusSq)
                continue;

            if (!_inventory.CanAdd(item.BlockId, item.Count))
                continue;

            var leftover = _inventory.Add(item.BlockId, item.Count);
            if (leftover <= 0)
            {
                _worldItemRemove.Add(item.ItemId);
                MarkPlayerStateDirty(); // Mark dirty after inventory change
                SendItemPickup(item.ItemId);
            }
        }

        for (int i = 0; i < _worldItemRemove.Count; i++)
            _worldItems.Remove(_worldItemRemove[i]);
    }

    private bool TrySnapToGround(Vector3 pos, out Vector3 grounded)
    {
        grounded = pos;
        if (_world == null)
            return false;

        var bx = (int)Math.Floor(pos.X);
        var by = (int)Math.Floor(pos.Y - ItemHalfHeight - ItemGroundSnap - 0.001f);
        var bz = (int)Math.Floor(pos.Z);
        if (BlockRegistry.IsSolid(_world.GetBlock(bx, by, bz)))
        {
            var targetY = by + 1f + ItemGroundOffset;
            if (pos.Y <= targetY + ItemGroundSnap)
            {
                grounded.Y = targetY;
                return true;
            }
        }
        return false;
    }

    private bool IsSolidAt(Vector3 pos)
    {
        if (_world == null)
            return false;

        var bx = (int)Math.Floor(pos.X);
        var by = (int)Math.Floor(pos.Y);
        var bz = (int)Math.Floor(pos.Z);
        return BlockRegistry.IsSolid(_world.GetBlock(bx, by, bz));
    }

    private void UpdateHotbarLayout()
    {
        var slotSize = Math.Clamp((int)(_viewport.Width * 0.05f), 36, 64);
        var gap = 6;
        var totalW = slotSize * Inventory.HotbarSize + gap * (Inventory.HotbarSize - 1);
        var startX = _viewport.X + (_viewport.Width - totalW) / 2;
        var y = _viewport.Bottom - slotSize - 18;

        _hotbarRect = new Rectangle(startX, y, totalW, slotSize);
        for (int i = 0; i < _hotbarSlots.Length; i++)
        {
            var x = startX + i * (slotSize + gap);
            _hotbarSlots[i] = new Rectangle(x, y, slotSize, slotSize);
        }
    }

    private void UpdateInventoryLayout()
    {
        var tabsVisible = _gameMode == GameMode.Artificer;
        var headerHeight = tabsVisible ? InventoryTitleHeightWithTabs : InventoryTitleHeight;
        var maxW = _viewport.Width - 40;
        var maxH = _viewport.Height - 40;
        var slotSize = InventorySlotSize;
        var gridW = InventoryCols * slotSize + (InventoryCols - 1) * InventorySlotGap;
        var gridH = InventoryRows * slotSize + (InventoryRows - 1) * InventorySlotGap;
        var windowW = InventoryPadding * 2 + gridW;
        var windowH = InventoryPadding * 2 + headerHeight + gridH + InventoryFooterHeight;

        if (windowW > maxW)
        {
            slotSize = Math.Clamp((maxW - InventoryPadding * 2 - InventorySlotGap * (InventoryCols - 1)) / InventoryCols, 36, InventorySlotSize);
            gridW = InventoryCols * slotSize + (InventoryCols - 1) * InventorySlotGap;
            windowW = InventoryPadding * 2 + gridW;
        }

        if (windowH > maxH)
        {
            var maxSlot = (maxH - InventoryPadding * 2 - headerHeight - InventoryFooterHeight - InventorySlotGap * (InventoryRows - 1)) / InventoryRows;
            slotSize = Math.Clamp(Math.Min(slotSize, maxSlot), 32, InventorySlotSize);
            gridH = InventoryRows * slotSize + (InventoryRows - 1) * InventorySlotGap;
            windowH = InventoryPadding * 2 + headerHeight + gridH + InventoryFooterHeight;
        }

        var visualWidth = Math.Min(maxW, (int)MathF.Round(windowW * InventoryPanelVisualScale));
        var visualHeight = Math.Min(maxH, (int)MathF.Round(windowH * InventoryPanelVisualScale));
        var inventoryY = _viewport.Y + (_viewport.Height - windowH) / 2;
        if (TryGetSigilHudRect(out var inventorySigilRect))
        {
            var maxBottom = inventorySigilRect.Y - 20;
            var visualTopInset = (visualHeight - windowH) / 2;
            var visualBottomInset = visualHeight - windowH - visualTopInset;
            inventoryY = Math.Min(inventoryY, maxBottom - windowH - visualBottomInset);
        }

        inventoryY = Math.Clamp(inventoryY, _viewport.Y + 12, Math.Max(_viewport.Y + 12, _viewport.Bottom - windowH - 12));
        _inventoryRect = new Rectangle(
            _viewport.X + (_viewport.Width - windowW) / 2,
            inventoryY,
            windowW,
            windowH);

        _inventoryPanelVisualRect = new Rectangle(
            _inventoryRect.Center.X - visualWidth / 2,
            _inventoryRect.Center.Y - visualHeight / 2,
            visualWidth,
            visualHeight);

        if (tabsVisible)
        {
            var tabY = _inventoryRect.Y + InventoryPadding;
            _inventoryCatalogTabRect = new Rectangle(_inventoryRect.X + InventoryPadding, tabY, InventoryTabWidth, InventoryTabHeight);
            _inventoryStorageTabRect = new Rectangle(_inventoryCatalogTabRect.Right + 10, tabY, InventoryTabWidth, InventoryTabHeight);
        }
        else
        {
            _inventoryCatalogTabRect = Rectangle.Empty;
            _inventoryStorageTabRect = Rectangle.Empty;
        }

        var startX = _inventoryRect.X + InventoryPadding;
        var startY = _inventoryRect.Y + InventoryPadding + headerHeight;

        for (int row = 0; row < InventoryRows; row++)
        {
            for (int col = 0; col < InventoryCols; col++)
            {
                var idx = row * InventoryCols + col;
                var x = startX + col * (slotSize + InventorySlotGap);
                var y = startY + row * (slotSize + InventorySlotGap);
                _inventoryGridSlots[idx] = new Rectangle(x, y, slotSize, slotSize);
            }
        }

        // Initialize inventory hotbar slots (above the grid)
        var hotbarStartY = startY - slotSize - InventorySlotGap - 10;
        for (int i = 0; i < Inventory.HotbarSize; i++)
        {
            var x = startX + i * (slotSize + InventorySlotGap);
            _inventoryHotbarSlots[i] = new Rectangle(x, hotbarStartY, slotSize, slotSize);
        }

        _inventoryClose.Bounds = new Rectangle(_inventoryRect.Right - 40, _inventoryRect.Y + 9, 32, 32);
        _inventoryClear.Bounds = new Rectangle(_inventoryRect.X + 16, _inventoryRect.Bottom - 50, 220, 38);

        var gridBounds = GetInventoryGridBounds();
        _inventoryCatalogHeaderRect = gridBounds.Width > 0
            ? new Rectangle(gridBounds.X, gridBounds.Y, gridBounds.Width, CatalogHeaderHeight)
            : Rectangle.Empty;

        if (_inventoryCatalogHeaderRect.Width > 0)
        {
            var favoritesWidth = 130;
            var searchWidth = Math.Max(120, _inventoryCatalogHeaderRect.Width - favoritesWidth - 12);
            _inventoryCatalogSearchRect = new Rectangle(
                _inventoryCatalogHeaderRect.X,
                _inventoryCatalogHeaderRect.Y + 6,
                searchWidth,
                CatalogSearchHeight);
            _inventoryCatalogSearchClearRect = new Rectangle(
                _inventoryCatalogSearchRect.Right - 30,
                _inventoryCatalogSearchRect.Y + 2,
                26,
                _inventoryCatalogSearchRect.Height - 4);
            _inventoryCatalogFavoritesRect = new Rectangle(
                _inventoryCatalogSearchRect.Right + 12,
                _inventoryCatalogSearchRect.Y,
                favoritesWidth - 12,
                CatalogSearchHeight);
            _inventoryCatalogListRect = new Rectangle(
                gridBounds.X,
                _inventoryCatalogHeaderRect.Bottom + 4,
                gridBounds.Width,
                Math.Max(0, gridBounds.Height - _inventoryCatalogHeaderRect.Height - 4));
        }
        else
        {
            _inventoryCatalogSearchRect = Rectangle.Empty;
            _inventoryCatalogSearchClearRect = Rectangle.Empty;
            _inventoryCatalogFavoritesRect = Rectangle.Empty;
            _inventoryCatalogListRect = Rectangle.Empty;
        }
    }

    private void UpdateSoulLootLayout()
    {
        var maxW = _viewport.Width - 40;
        var maxH = _viewport.Height - 40;
        var slotSize = Math.Clamp(InventorySlotSize - 4, 34, InventorySlotSize);
        var rowWidth = InventoryCols * slotSize + (InventoryCols - 1) * InventorySlotGap;
        var soulRowsHeight = (slotSize * 4) + (InventorySlotGap * 3);
        var playerRowsHeight = (slotSize * InventoryRows) + (InventorySlotGap * (InventoryRows - 1));
        var sectionGap = 18;
        var headerHeight = 56;
        var footerHeight = 60;
        var windowW = InventoryPadding * 2 + rowWidth;
        var windowH = InventoryPadding * 2 + headerHeight + soulRowsHeight + sectionGap + playerRowsHeight + footerHeight;

        if (windowW > maxW || windowH > maxH)
        {
            var maxSlotByWidth = (maxW - InventoryPadding * 2 - InventorySlotGap * (InventoryCols - 1)) / InventoryCols;
            var maxSlotByHeight = (maxH - InventoryPadding * 2 - headerHeight - footerHeight - sectionGap - InventorySlotGap * 5) / 7;
            slotSize = Math.Clamp(Math.Min(slotSize, Math.Min(maxSlotByWidth, maxSlotByHeight)), 28, InventorySlotSize);
            rowWidth = InventoryCols * slotSize + (InventoryCols - 1) * InventorySlotGap;
            soulRowsHeight = (slotSize * 4) + (InventorySlotGap * 3);
            playerRowsHeight = (slotSize * InventoryRows) + (InventorySlotGap * (InventoryRows - 1));
            windowW = InventoryPadding * 2 + rowWidth;
            windowH = InventoryPadding * 2 + headerHeight + soulRowsHeight + sectionGap + playerRowsHeight + footerHeight;
        }

        var centeredX = _viewport.X + (_viewport.Width - windowW) / 2;
        var desiredBottom = _hotbarRect.Y > 0
            ? _hotbarRect.Y - 52
            : _viewport.Bottom - 18;
        var liftedY = desiredBottom - windowH;
        var clampedY = Math.Clamp(liftedY, _viewport.Y + 12, Math.Max(_viewport.Y + 12, _viewport.Bottom - windowH - 12));

        _soulLootRect = new Rectangle(
            centeredX,
            clampedY,
            windowW,
            windowH);

        var visualWidth = Math.Min(maxW, (int)MathF.Round(windowW * InventoryPanelVisualScale));
        var visualHeight = Math.Min(maxH, (int)MathF.Round(windowH * InventoryPanelVisualScale));
        _soulLootPanelVisualRect = new Rectangle(
            _soulLootRect.Center.X - visualWidth / 2,
            _soulLootRect.Center.Y - visualHeight / 2,
            visualWidth,
            visualHeight);

        var startX = _soulLootRect.X + InventoryPadding;
        var startY = _soulLootRect.Y + InventoryPadding + headerHeight;

        for (var col = 0; col < Inventory.HotbarSize; col++)
        {
            _soulLootSoulHotbarSlots[col] = new Rectangle(
                startX + col * (slotSize + InventorySlotGap),
                startY,
                slotSize,
                slotSize);
        }

        var soulGridStartY = startY + slotSize + InventorySlotGap;
        for (var row = 0; row < InventoryRows; row++)
        {
            for (var col = 0; col < InventoryCols; col++)
            {
                var idx = row * InventoryCols + col;
                _soulLootSoulGridSlots[idx] = new Rectangle(
                    startX + col * (slotSize + InventorySlotGap),
                    soulGridStartY + row * (slotSize + InventorySlotGap),
                    slotSize,
                    slotSize);
            }
        }

        var playerGridStartY = soulGridStartY + (slotSize * InventoryRows) + (InventorySlotGap * (InventoryRows - 1)) + sectionGap + 18;
        for (var row = 0; row < InventoryRows; row++)
        {
            for (var col = 0; col < InventoryCols; col++)
            {
                var idx = row * InventoryCols + col;
                _soulLootPlayerGridSlots[idx] = new Rectangle(
                    startX + col * (slotSize + InventorySlotGap),
                    playerGridStartY + row * (slotSize + InventorySlotGap),
                    slotSize,
                    slotSize);
            }
        }

        for (var col = 0; col < Inventory.HotbarSize; col++)
        {
            _soulLootPlayerHotbarSlots[col] = Rectangle.Empty;
        }

        _soulLootClear.Bounds = new Rectangle(_soulLootRect.X + 16, _soulLootRect.Bottom - 50, 170, 38);
        _soulLootTakeAll.Bounds = new Rectangle(_soulLootClear.Bounds.Right + 12, _soulLootRect.Bottom - 50, 170, 38);
        _soulLootClose.Bounds = new Rectangle(_soulLootRect.Right - 40, _soulLootRect.Y + 9, 32, 32);
    }

    private void UpdateInventory(InputState input, float dt)
    {
        if (!_inventoryOpen)
            return;

        if (_viewport != UiLayout.Viewport)
        {
            _viewport = UiLayout.Viewport;
            UpdateHotbarLayout();
            UpdateInventoryLayout();
        }

        _inventoryMousePos = input.MousePosition;
        var p = _inventoryMousePos;
        var isLiveView = HasActiveRemoteInventoryView();
        var showArtificerTabs = _gameMode == GameMode.Artificer && !isLiveView;
        var isCatalogView = showArtificerTabs && _artificerInventoryView == ArtificerInventoryView.Catalog;
        var searchFocusLocked = isCatalogView && _inventoryCatalogSearchFocused;

        if (_inventoryClearConfirmPending)
        {
            _inventoryClearConfirmTimer = Math.Max(0f, _inventoryClearConfirmTimer - Math.Max(0f, dt));
            if (_inventoryClearConfirmTimer <= 0f)
                _inventoryClearConfirmPending = false;
        }

        _inventoryClear.Visible = _gameMode == GameMode.Artificer && !isLiveView;
        _inventoryClear.Enabled = _gameMode == GameMode.Artificer && !isLiveView;
        _inventoryClear.Label = _inventoryClearConfirmPending ? "CONFIRM CLEAR" : "CLEAR INVENTORY";

        if (searchFocusLocked)
        {
            if (input.IsNewKeyPress(Keys.Escape))
            {
                _inventoryCatalogSearchFocused = false;
                return;
            }

            if (input.IsNewLeftClick())
            {
                var clickInsideSearchUi = _inventoryCatalogSearchRect.Contains(p)
                    || _inventoryCatalogSearchClearRect.Contains(p);
                if (!clickInsideSearchUi)
                {
                    _inventoryCatalogSearchFocused = false;
                    return;
                }

                if (_inventoryCatalogSearchClearRect.Contains(p) && !string.IsNullOrEmpty(_inventory.SandboxCatalogSearchQuery))
                {
                    _inventory.ClearSandboxCatalogSearchQuery();
                    _inventoryCatalogSearchCaret = 0;
                    ClampInventoryCatalogScroll(resetVelocityWhenClamped: true);
                    return;
                }
            }

            // While focused, only search-text editing keys are accepted.
            UpdateInventoryCatalogSearchInput(input);
            return;
        }

        if (IsNewActionPress(input, "Inventory", Keys.E))
        {
            CloseInventory();
            return;
        }

        if (input.IsNewKeyPress(Keys.Escape))
        {
            CloseInventory();
            return;
        }

        if (isCatalogView)
        {
            if (_inventoryCatalogListRect.Contains(p) && input.ScrollDelta != 0)
            {
                var wheelSteps = input.ScrollDelta / 120f;
                if (Math.Abs(wheelSteps) < 0.01f)
                    wheelSteps = Math.Sign(input.ScrollDelta);
                _inventoryCatalogScrollVelocityPxPerSec -= wheelSteps * CatalogScrollWheelImpulse;
            }

            var scrollDecay = MathF.Exp(-CatalogScrollDamping * Math.Max(0f, dt));
            _inventoryCatalogScrollVelocityPxPerSec *= scrollDecay;
            if (MathF.Abs(_inventoryCatalogScrollVelocityPxPerSec) < 1f)
                _inventoryCatalogScrollVelocityPxPerSec = 0f;

            _inventoryCatalogScrollOffsetPx += _inventoryCatalogScrollVelocityPxPerSec * Math.Max(0f, dt);
            ClampInventoryCatalogScroll(resetVelocityWhenClamped: true);

            UpdateInventoryCatalogSearchInput(input);
        }
        else
        {
            _inventoryCatalogSearchFocused = false;
            _inventoryCatalogScrollVelocityPxPerSec = 0f;
            ClampInventoryCatalogScroll(resetVelocityWhenClamped: false);
        }

        _inventoryClose.Update(input);
        _inventoryClear.Update(input);
        if (!_inventoryOpen)
            return;

        // Hover detection
        var hoveredAny = false;
        if (isLiveView)
        {
            if (TryGetActiveRemoteInventoryView(out var liveView))
            {
                for (int i = 0; i < _inventoryHotbarSlots.Length; i++)
                {
                    if (_inventoryHotbarSlots[i].Contains(p))
                    {
                        var blockId = i < liveView.HotbarIds.Length ? (BlockId)liveView.HotbarIds[i] : BlockId.Air;
                        var count = i < liveView.HotbarCounts.Length ? liveView.HotbarCounts[i] : 0;
                        if (blockId != BlockId.Air && count > 0)
                        {
                            SetDisplayName(BlockRegistry.Get(blockId).Name);
                            hoveredAny = true;
                        }
                        break;
                    }
                }

                if (!hoveredAny)
                {
                    for (int i = 0; i < _inventoryGridSlots.Length; i++)
                    {
                        if (_inventoryGridSlots[i].Contains(p))
                        {
                            var blockId = i < liveView.GridIds.Length ? (BlockId)liveView.GridIds[i] : BlockId.Air;
                            var count = i < liveView.GridCounts.Length ? liveView.GridCounts[i] : 0;
                            if (blockId != BlockId.Air && count > 0)
                            {
                                SetDisplayName(BlockRegistry.Get(blockId).Name);
                                hoveredAny = true;
                            }
                            break;
                        }
                    }
                }
            }

            if (!input.IsNewLeftClick())
                return;

            return;
        }
        else if (isCatalogView)
        {
            if (TryGetInventoryCatalogRowAtPoint(p, out var hoveredIndex, out _, out _) && hoveredIndex >= 0)
            {
                var slot = _inventory.GetSandboxCatalogFilteredEntryAt(hoveredIndex);
                if (slot.Id != BlockId.Air && slot.Count > 0)
                {
                    SetDisplayName(BlockRegistry.Get(slot.Id).Name);
                    hoveredAny = true;
                }
            }
        }
        else
        {
            for (int i = 0; i < _inventoryGridSlots.Length; i++)
            {
                if (_inventoryGridSlots[i].Contains(p))
                {
                    var slot = _inventory.Grid[i];
                    if (slot.Id != BlockId.Air && slot.Count > 0)
                    {
                        SetDisplayName(BlockRegistry.Get(slot.Id).Name);
                        hoveredAny = true;
                    }
                    break;
                }
            }
        }

        if (!hoveredAny && !isLiveView)
        {
            for (int i = 0; i < _hotbarSlots.Length; i++)
            {
                if (_hotbarSlots[i].Contains(p))
                {
                    var slot = _inventory.Hotbar[i];
                    if (slot.Id != BlockId.Air && slot.Count > 0)
                    {
                        SetDisplayName(BlockRegistry.Get(slot.Id).Name);
                        hoveredAny = true;
                    }
                    break;
                }
            }
        }

        if (showArtificerTabs)
        {
            if (input.IsNewLeftClick() && _inventoryCatalogTabRect.Contains(p))
            {
                _artificerInventoryView = ArtificerInventoryView.Catalog;
                _lastArtificerInventoryView = _artificerInventoryView;
                _inventoryCatalogSearchFocused = false;
                return;
            }

            if (input.IsNewLeftClick() && _inventoryStorageTabRect.Contains(p))
            {
                _artificerInventoryView = ArtificerInventoryView.Inventory;
                _lastArtificerInventoryView = _artificerInventoryView;
                _inventoryCatalogSearchFocused = false;
                return;
            }
        }

        if (isCatalogView)
        {
            if (input.IsNewLeftClick() && _inventoryCatalogSearchClearRect.Contains(p) && !string.IsNullOrEmpty(_inventory.SandboxCatalogSearchQuery))
            {
                _inventory.ClearSandboxCatalogSearchQuery();
                _inventoryCatalogSearchCaret = 0;
                ClampInventoryCatalogScroll(resetVelocityWhenClamped: true);
                return;
            }

            if (input.IsNewLeftClick() && _inventoryCatalogSearchRect.Contains(p))
            {
                _inventoryCatalogSearchSelectAll = _inventoryCatalogSearchFocused && !string.IsNullOrEmpty(_inventory.SandboxCatalogSearchQuery);
                _inventoryCatalogSearchFocused = true;
                _inventoryCatalogSearchCaret = _inventory.SandboxCatalogSearchQuery.Length;
                return;
            }

            if (input.IsNewLeftClick() && _inventoryCatalogFavoritesRect.Contains(p))
            {
                _inventory.SetSandboxCatalogFavoritesOnly(!_inventory.SandboxCatalogFavoritesOnly);
                ClampInventoryCatalogScroll(resetVelocityWhenClamped: true);
                return;
            }

            _inventoryCatalogSearchFocused = false;
            _inventoryCatalogSearchSelectAll = false;

            if (TryGetInventoryCatalogRowAtPoint(p, out var selectedIndex, out _, out var favoriteRect))
            {
                var catalogSlot = _inventory.GetSandboxCatalogFilteredEntryAt(selectedIndex);
                if (catalogSlot.Count <= 0 || catalogSlot.Id == BlockId.Air)
                    return;

                if (input.IsNewLeftClick() && favoriteRect.Contains(p))
                {
                    if (_inventory.ToggleSandboxCatalogFavorite((int)catalogSlot.Id))
                        MarkPlayerStateDirty();
                    ClampInventoryCatalogScroll(resetVelocityWhenClamped: true);
                    return;
                }

                if (input.IsNewLeftClick())
                {
                    _inventoryHeld = catalogSlot;
                    _inventoryHeld.Count = _inventory.GetMaxStackSize(catalogSlot.Id);
                    _inventoryHasHeld = true;
                    _heldFrom = InventorySlotGroup.None;
                    _heldIndex = -1;
                    return;
                }

                if (input.IsNewRightClick())
                {
                    TryCollectCatalogItemToCursor(catalogSlot.Id, 1);
                    return;
                }
            }
        }
        else
        {
            _inventoryCatalogSearchFocused = false;
            for (int i = 0; i < _inventoryGridSlots.Length; i++)
            {
                if (_inventoryGridSlots[i].Contains(p))
                {
                    ref var slot = ref _inventory.Grid[i];
                    if (input.IsNewLeftClick())
                        HandleInventorySlotClick(ref slot, InventorySlotGroup.Grid, i, sandboxCatalogMode: false);
                    else if (input.IsNewRightClick())
                        HandleInventorySlotRightClick(ref slot, InventorySlotGroup.Grid, i, sandboxCatalogMode: false);
                    return;
                }
            }
        }

        for (int i = 0; i < _hotbarSlots.Length; i++)
        {
            if (_hotbarSlots[i].Contains(p))
            {
                ref var slot = ref _inventory.Hotbar[i];
                if (input.IsNewLeftClick())
                    HandleInventorySlotClick(ref slot, InventorySlotGroup.Hotbar, i, sandboxCatalogMode: isCatalogView);
                else if (input.IsNewRightClick())
                    HandleInventorySlotRightClick(ref slot, InventorySlotGroup.Hotbar, i, sandboxCatalogMode: isCatalogView);
                return;
            }
        }
    }

    private Rectangle GetInventoryGridBounds()
    {
        if (_inventoryGridSlots.Length == 0)
            return Rectangle.Empty;

        var left = int.MaxValue;
        var top = int.MaxValue;
        var right = int.MinValue;
        var bottom = int.MinValue;

        for (var i = 0; i < _inventoryGridSlots.Length; i++)
        {
            var rect = _inventoryGridSlots[i];
            if (rect.Width <= 0 || rect.Height <= 0)
                continue;

            left = Math.Min(left, rect.Left);
            top = Math.Min(top, rect.Top);
            right = Math.Max(right, rect.Right);
            bottom = Math.Max(bottom, rect.Bottom);
        }

        if (right <= left || bottom <= top)
            return Rectangle.Empty;

        return new Rectangle(left, top, right - left, bottom - top);
    }

    private void ClampInventoryCatalogScroll(bool resetVelocityWhenClamped)
    {
        if (_inventoryCatalogListRect.Width <= 0 || _inventoryCatalogListRect.Height <= 0)
        {
            _inventoryCatalogScrollOffsetPx = 0f;
            if (resetVelocityWhenClamped)
                _inventoryCatalogScrollVelocityPxPerSec = 0f;
            return;
        }

        var totalRows = _inventory.GetSandboxCatalogFilteredCount();
        var maxScroll = Math.Max(0f, totalRows * CatalogRowHeight - _inventoryCatalogListRect.Height);
        var clamped = Math.Clamp(_inventoryCatalogScrollOffsetPx, 0f, maxScroll);
        if (Math.Abs(clamped - _inventoryCatalogScrollOffsetPx) > 0.001f && resetVelocityWhenClamped)
            _inventoryCatalogScrollVelocityPxPerSec = 0f;

        _inventoryCatalogScrollOffsetPx = clamped;
    }

    private bool TryGetInventoryCatalogRowAtPoint(Point point, out int filteredIndex, out Rectangle rowRect, out Rectangle favoriteRect)
    {
        filteredIndex = -1;
        rowRect = Rectangle.Empty;
        favoriteRect = Rectangle.Empty;

        if (_inventoryCatalogListRect.Width <= 0 || _inventoryCatalogListRect.Height <= 0)
            return false;
        if (!_inventoryCatalogListRect.Contains(point))
            return false;

        var totalRows = _inventory.GetSandboxCatalogFilteredCount();
        if (totalRows <= 0)
            return false;

        var contentY = (point.Y - _inventoryCatalogListRect.Y) + _inventoryCatalogScrollOffsetPx;
        filteredIndex = (int)MathF.Floor(contentY / CatalogRowHeight);
        if (filteredIndex < 0 || filteredIndex >= totalRows)
            return false;

        var rowTop = _inventoryCatalogListRect.Y + (int)MathF.Floor(filteredIndex * CatalogRowHeight - _inventoryCatalogScrollOffsetPx);
        rowRect = new Rectangle(_inventoryCatalogListRect.X + 2, rowTop, _inventoryCatalogListRect.Width - 4, CatalogRowHeight - 2);
        if (!rowRect.Contains(point))
            return false;

        favoriteRect = new Rectangle(rowRect.Right - 32, rowRect.Y + 8, 22, 22);
        return true;
    }

    private void UpdateInventoryCatalogSearchInput(InputState input)
    {
        if (!_inventoryCatalogSearchFocused)
            return;

        var query = _inventory.SandboxCatalogSearchQuery;
        if (!string.IsNullOrEmpty(query) && _inventoryCatalogSearchRect.Contains(input.MousePosition) && input.IsLeftDragActive())
            _inventoryCatalogSearchSelectAll = true;
        _inventoryCatalogSearchCaret = Math.Clamp(_inventoryCatalogSearchCaret, 0, query.Length);

        if (input.IsNewKeyPress(Keys.Left))
            _inventoryCatalogSearchCaret = Math.Max(0, _inventoryCatalogSearchCaret - 1);
        if (input.IsNewKeyPress(Keys.Right))
            _inventoryCatalogSearchCaret = Math.Min(query.Length, _inventoryCatalogSearchCaret + 1);
        if (input.IsNewKeyPress(Keys.Home))
            _inventoryCatalogSearchCaret = 0;
        if (input.IsNewKeyPress(Keys.End))
            _inventoryCatalogSearchCaret = query.Length;

        var changed = false;

        if (TryHandleWholeFieldClipboard(input, ref query, CatalogSearchMaxLength, ref _inventoryCatalogSearchSelectAll))
        {
            _inventoryCatalogSearchCaret = query.Length;
            if (query.Length > CatalogSearchMaxLength)
                query = query.Substring(0, CatalogSearchMaxLength);

            _inventory.SetSandboxCatalogSearchQuery(query);
            _inventoryCatalogSearchCaret = Math.Clamp(_inventoryCatalogSearchCaret, 0, _inventory.SandboxCatalogSearchQuery.Length);
            _inventoryCatalogScrollOffsetPx = 0f;
            _inventoryCatalogScrollVelocityPxPerSec = 0f;
            ClampInventoryCatalogScroll(resetVelocityWhenClamped: true);
            return;
        }

        var shift = input.IsKeyDown(Keys.LeftShift) || input.IsKeyDown(Keys.RightShift);
        foreach (var key in input.GetTextInputKeys())
        {
            if (key is Keys.Tab or Keys.Enter or Keys.Left or Keys.Right or Keys.Home or Keys.End)
                continue;

            if (key == Keys.Back)
            {
                if (_inventoryCatalogSearchSelectAll)
                {
                    query = string.Empty;
                    _inventoryCatalogSearchCaret = 0;
                    _inventoryCatalogSearchSelectAll = false;
                    changed = true;
                }
                else if (_inventoryCatalogSearchCaret > 0)
                {
                    query = query.Remove(_inventoryCatalogSearchCaret - 1, 1);
                    _inventoryCatalogSearchCaret--;
                    changed = true;
                }
                continue;
            }

            if (key == Keys.Delete)
            {
                if (_inventoryCatalogSearchSelectAll)
                {
                    query = string.Empty;
                    _inventoryCatalogSearchCaret = 0;
                    _inventoryCatalogSearchSelectAll = false;
                    changed = true;
                }
                else if (_inventoryCatalogSearchCaret < query.Length)
                {
                    query = query.Remove(_inventoryCatalogSearchCaret, 1);
                    changed = true;
                }
                continue;
            }

            if (!TryMapCommandInputKey(key, shift, out var c))
                continue;

            if (query.Length >= CatalogSearchMaxLength)
                continue;

            if (_inventoryCatalogSearchSelectAll)
            {
                query = c.ToString();
                _inventoryCatalogSearchCaret = 1;
                _inventoryCatalogSearchSelectAll = false;
            }
            else
            {
                query = query.Insert(_inventoryCatalogSearchCaret, c.ToString());
                _inventoryCatalogSearchCaret++;
            }
            changed = true;
        }

        if (!changed)
            return;

        if (query.Length > CatalogSearchMaxLength)
            query = query.Substring(0, CatalogSearchMaxLength);

        _inventory.SetSandboxCatalogSearchQuery(query);
        _inventoryCatalogSearchCaret = Math.Clamp(_inventoryCatalogSearchCaret, 0, _inventory.SandboxCatalogSearchQuery.Length);
        _inventoryCatalogScrollOffsetPx = 0f;
        _inventoryCatalogScrollVelocityPxPerSec = 0f;
        ClampInventoryCatalogScroll(resetVelocityWhenClamped: true);
    }

    private void DrawInventoryCatalogPanel(SpriteBatch sb)
    {
        if (_inventoryCatalogHeaderRect.Width <= 0 || _inventoryCatalogListRect.Width <= 0)
            return;

        EnsureCatalogLoreLoaded();

        sb.Draw(_pixel, _inventoryCatalogHeaderRect, new Color(14, 18, 24, 210));
        DrawBorder(sb, _inventoryCatalogHeaderRect, new Color(100, 120, 140));

        sb.Draw(_pixel, _inventoryCatalogSearchRect, new Color(10, 10, 14, 235));
        DrawBorder(sb, _inventoryCatalogSearchRect, _inventoryCatalogSearchFocused ? new Color(230, 230, 140) : new Color(170, 170, 170));
        var query = _inventory.SandboxCatalogSearchQuery;
        var queryDisplay = string.IsNullOrEmpty(query) ? "Search blocks..." : query;
        var queryColor = string.IsNullOrEmpty(query) ? new Color(150, 150, 150) : Color.White;
        var queryPos = new Vector2(_inventoryCatalogSearchRect.X + 8, _inventoryCatalogSearchRect.Y + 8);
        TextFieldVisuals.DrawWholeFieldSelection(sb, _pixel, _font, query, queryPos, _inventoryCatalogSearchRect, _inventoryCatalogSearchSelectAll, new Color(88, 148, 218, 170));
        _font.DrawString(sb, queryDisplay, queryPos, queryColor);

        if (!string.IsNullOrEmpty(query))
        {
            sb.Draw(_pixel, _inventoryCatalogSearchClearRect, new Color(26, 30, 36, 240));
            DrawBorder(sb, _inventoryCatalogSearchClearRect, new Color(205, 205, 205));
            var clearText = "X";
            var clearSize = _font.MeasureString(clearText);
            _font.DrawString(
                sb,
                clearText,
                new Vector2(_inventoryCatalogSearchClearRect.Center.X - clearSize.X / 2f, _inventoryCatalogSearchClearRect.Center.Y - clearSize.Y / 2f),
                Color.White);
        }

        if (_inventoryCatalogSearchFocused && !_inventoryCatalogSearchSelectAll && ((int)(_worldTimeSeconds * 2f) % 2 == 0))
        {
            var caret = Math.Clamp(_inventoryCatalogSearchCaret, 0, query.Length);
            var caretPrefix = caret <= 0 ? string.Empty : query.Substring(0, caret);
            var caretOffsetX = _font.MeasureString(caretPrefix).X;
            var caretX = _inventoryCatalogSearchRect.X + 8 + (int)MathF.Round(caretOffsetX);
            var caretRect = new Rectangle(caretX, _inventoryCatalogSearchRect.Y + 6, 2, _inventoryCatalogSearchRect.Height - 12);
            sb.Draw(_pixel, caretRect, new Color(245, 245, 245));
        }

        var favoritesOnly = _inventory.SandboxCatalogFavoritesOnly;
        sb.Draw(_pixel, _inventoryCatalogFavoritesRect, favoritesOnly ? new Color(48, 86, 132, 235) : new Color(18, 20, 24, 235));
        DrawBorder(sb, _inventoryCatalogFavoritesRect, favoritesOnly ? new Color(220, 235, 255) : new Color(160, 160, 160));
        _font.DrawString(
            sb,
            favoritesOnly ? "FAVORITES ON" : "FAVORITES",
            new Vector2(_inventoryCatalogFavoritesRect.X + 10, _inventoryCatalogFavoritesRect.Y + 8),
            Color.White);

        sb.Draw(_pixel, _inventoryCatalogListRect, new Color(9, 10, 12, 220));
        DrawBorder(sb, _inventoryCatalogListRect, new Color(170, 170, 170));

        var totalRows = _inventory.GetSandboxCatalogFilteredCount();
        if (totalRows <= 0)
        {
            _font.DrawString(sb, "No blocks match search.", new Vector2(_inventoryCatalogListRect.X + 12, _inventoryCatalogListRect.Y + 12), new Color(220, 220, 220));
            return;
        }

        var first = Math.Max(0, (int)MathF.Floor(_inventoryCatalogScrollOffsetPx / CatalogRowHeight) - CatalogRowOverscan);
        var visible = Math.Max(1, (int)MathF.Ceiling(_inventoryCatalogListRect.Height / (float)CatalogRowHeight) + CatalogRowOverscan * 2);
        var last = Math.Min(totalRows - 1, first + visible - 1);
        var hoveredBlockId = BlockId.Air;
        var hoveredRowRect = Rectangle.Empty;

        var device = _graphics.GraphicsDevice;
        var priorScissor = device.ScissorRectangle;
        var clipRect = UiLayout.ToScreenRect(_inventoryCatalogListRect);
        if (clipRect.Width <= 0 || clipRect.Height <= 0)
            return;

        sb.End();
        device.ScissorRectangle = clipRect;
        sb.Begin(samplerState: SamplerState.PointClamp, transformMatrix: UiLayout.Transform, rasterizerState: ScissorState);

        for (var index = first; index <= last; index++)
        {
            var rowTop = _inventoryCatalogListRect.Y + (int)MathF.Floor(index * CatalogRowHeight - _inventoryCatalogScrollOffsetPx);
            var rowRect = new Rectangle(_inventoryCatalogListRect.X + 2, rowTop, _inventoryCatalogListRect.Width - 4, CatalogRowHeight - 2);
            if (rowRect.Bottom <= _inventoryCatalogListRect.Top || rowRect.Top >= _inventoryCatalogListRect.Bottom)
                continue;

            var hovered = rowRect.Contains(_inventoryMousePos);
            sb.Draw(_pixel, rowRect, hovered ? new Color(34, 44, 58, 220) : new Color(20, 24, 30, 210));
            DrawBorder(sb, rowRect, hovered ? new Color(188, 214, 252) : new Color(88, 96, 110));

            var slot = _inventory.GetSandboxCatalogFilteredEntryAt(index);
            var iconRect = new Rectangle(rowRect.X + 8, rowRect.Y + 4, CatalogRowIconSize, CatalogRowIconSize);
            var icon = GetBlockIconIfReady(slot.Id, iconRect.Width);
            if (icon != null)
                sb.Draw(icon, iconRect, Color.White);
            else if (_atlas != null)
                sb.Draw(_atlas.Texture, iconRect, _atlas.GetFaceSourceRect((byte)slot.Id, FaceDirection.PosY), Color.White);

            var def = BlockRegistry.Get(slot.Id);
            var name = def.Name.ToUpperInvariant();
            var rarity = ResolveCatalogRarity(slot.Id, def);
            var nameColor = GetCatalogRarityColor(rarity);
            var nameY = rowRect.Y + (rowRect.Height - _font.LineHeight) / 2f;

            var favoriteRect = new Rectangle(rowRect.Right - 32, rowRect.Y + 8, 22, 22);
            var favorite = _inventory.IsSandboxCatalogFavorite((int)slot.Id);
            sb.Draw(_pixel, favoriteRect, favorite ? new Color(64, 112, 84, 245) : new Color(34, 34, 34, 245));
            DrawBorder(sb, favoriteRect, favorite ? new Color(210, 245, 220) : new Color(150, 150, 150));
            _font.DrawString(sb, favorite ? "*" : "+", new Vector2(favoriteRect.X + 7, favoriteRect.Y + 3), Color.White);
            var nameMaxWidth = Math.Max(40, favoriteRect.Left - (iconRect.Right + 8) - 10);
            var displayName = TruncateCatalogLabel(name, nameMaxWidth);
            _font.DrawString(sb, displayName, new Vector2(iconRect.Right + 8, nameY), nameColor);

            if (hovered)
            {
                hoveredBlockId = slot.Id;
                hoveredRowRect = rowRect;
            }
        }

        sb.End();
        device.ScissorRectangle = priorScissor;
        sb.Begin(samplerState: SamplerState.PointClamp, transformMatrix: UiLayout.Transform);

        if (hoveredRowRect != Rectangle.Empty)
            DrawCatalogHoverTooltip(sb, hoveredBlockId, hoveredRowRect);
    }

    private void EnsureCatalogLoreLoaded()
    {
        if (_catalogLoreLoaded)
            return;

        _catalogLoreLoaded = true;
        _catalogLoreByBlock.Clear();

        try
        {
            if (!_assets.TryLoadAssetBytes(CatalogLoreAssetPath, out var bytes) || bytes.Length == 0)
                return;

            var json = Encoding.UTF8.GetString(bytes);
            var options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
            var payload = JsonSerializer.Deserialize<CatalogLoreFile>(json, options);
            if (payload?.Blocks == null || payload.Blocks.Count == 0)
                return;

            for (var i = 0; i < payload.Blocks.Count; i++)
            {
                var source = payload.Blocks[i];
                if (source == null || !TryResolveCatalogLoreBlockId(source, out var blockId))
                    continue;

                var def = BlockRegistry.Get(blockId);
                if (def.Id != blockId || blockId == BlockId.Air || !def.IsVisibleInInventory)
                    continue;

                var description = BuildCatalogLoreDescription(source, def);
                if (string.IsNullOrWhiteSpace(description))
                    description = BuildDefaultCatalogDescription(def);

                var displayName = string.IsNullOrWhiteSpace(source.DisplayNameOverride)
                    ? def.Name
                    : source.DisplayNameOverride.Trim();
                var tags = NormalizeCatalogLoreTags(source.Tags);
                var rarity = ResolveCatalogRarity(blockId, def, tags);
                _catalogLoreByBlock[blockId] = new CatalogLoreEntry(displayName, description, tags, rarity);
            }
        }
        catch (Exception ex)
        {
            _log.Warn($"Catalog lore load failed: {ex.Message}");
        }
    }

    private static bool TryResolveCatalogLoreBlockId(CatalogLoreBlockDto source, out BlockId blockId)
    {
        blockId = BlockId.Air;

        if (source.ByteId > 0 && source.ByteId <= byte.MaxValue)
        {
            var byteBlock = (BlockId)source.ByteId;
            if (BlockRegistry.Get(byteBlock).Id == byteBlock)
            {
                blockId = byteBlock;
                return true;
            }
        }

        if (string.IsNullOrWhiteSpace(source.BlockEnum))
            return false;

        if (!Enum.TryParse<BlockId>(source.BlockEnum.Trim(), ignoreCase: true, out var parsed))
            return false;

        if (BlockRegistry.Get(parsed).Id != parsed)
            return false;

        blockId = parsed;
        return true;
    }

    private static string[] NormalizeCatalogLoreTags(string[]? tags)
    {
        if (tags == null || tags.Length == 0)
            return Array.Empty<string>();

        var output = new List<string>(tags.Length);
        for (var i = 0; i < tags.Length; i++)
        {
            var normalized = (tags[i] ?? string.Empty).Trim().ToLowerInvariant();
            if (normalized.Length > 0)
                output.Add(normalized);
        }

        if (output.Count == 0)
            return Array.Empty<string>();

        return output.Distinct(StringComparer.Ordinal).ToArray();
    }

    private static string BuildCatalogLoreDescription(CatalogLoreBlockDto source, BlockDef def)
    {
        if (source.LoreLines != null)
        {
            for (var i = 0; i < source.LoreLines.Length; i++)
            {
                var line = NormalizeCatalogLoreLine(source.LoreLines[i]);
                if (!string.IsNullOrWhiteSpace(line))
                    return line;
            }
        }

        return BuildDefaultCatalogDescription(def);
    }

    private static string NormalizeCatalogLoreLine(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw))
            return string.Empty;

        var trimmed = raw.Trim();
        return string.Join(' ', trimmed.Split(' ', StringSplitOptions.RemoveEmptyEntries));
    }

    private static string BuildDefaultCatalogDescription(BlockDef def)
    {
        var token = def.Id.ToString().ToLowerInvariant();
        if (def.Id == BlockId.Water)
            return "A flowing liquid block used to shape waterways and terrain basins.";
        if (token.Contains("leaf", StringComparison.Ordinal))
            return "Foliage block for shaping canopies and natural-looking tree crowns.";
        if (token.Contains("glass", StringComparison.Ordinal))
            return "Transparent construction block for clear windows and observation views.";
        if (token.Contains("ore", StringComparison.Ordinal) || token is "coal" or "iron" or "gold" or "diamond")
            return "Resource-bearing block used for progression materials and crafted tools.";
        if (token.Contains("bench", StringComparison.Ordinal) || token.Contains("table", StringComparison.Ordinal))
            return "Workstation block used for crafting and advanced build workflows.";
        if (!def.IsSolid)
            return "Light crafted component used in advanced recipes and utility builds.";
        if (def.Hardness < 0f)
            return "A foundational boundary block that anchors the world where it stands.";
        return "Reliable structural block for building, landscaping, and terrain shaping.";
    }

    private CatalogRarity ResolveCatalogRarity(BlockId blockId, BlockDef def)
    {
        if (_catalogLoreByBlock.TryGetValue(blockId, out var lore))
            return lore.Rarity;

        return ResolveCatalogRarity(blockId, def, Array.Empty<string>());
    }

    private static CatalogRarity ResolveCatalogRarity(BlockId blockId, BlockDef def, IReadOnlyList<string> tags)
    {
        var token = blockId.ToString().ToLowerInvariant();

        if (def.Hardness < 0f
            || token.Contains("evergatecore", StringComparison.Ordinal)
            || tags.Contains("null"))
            return CatalogRarity.Legendary;

        if (token.Contains("evergate", StringComparison.Ordinal)
            || token.Contains("keystone", StringComparison.Ordinal)
            || token.Contains("axiom", StringComparison.Ordinal)
            || token.Contains("resonancecore", StringComparison.Ordinal)
            || token.Contains("runicanvil", StringComparison.Ordinal)
            || tags.Contains("keystone")
            || tags.Contains("continuist"))
            return CatalogRarity.Rare;

        if (token.Contains("ore", StringComparison.Ordinal)
            || token.Contains("glass", StringComparison.Ordinal)
            || token.Contains("runestone", StringComparison.Ordinal)
            || token.Contains("veinstone", StringComparison.Ordinal)
            || token.Contains("staff", StringComparison.Ordinal)
            || token.Contains("regulator", StringComparison.Ordinal)
            || token.Contains("plinth", StringComparison.Ordinal)
            || token.Contains("sigil", StringComparison.Ordinal)
            || token.Contains("philter", StringComparison.Ordinal)
            || token.Contains("elixir", StringComparison.Ordinal)
            || token.Contains("draught", StringComparison.Ordinal)
            || tags.Contains("ore")
            || tags.Contains("metal")
            || tags.Contains("crafting")
            || tags.Contains("station")
            || tags.Contains("precision"))
            return CatalogRarity.Uncommon;

        return CatalogRarity.Common;
    }

    private static Color GetCatalogRarityColor(CatalogRarity rarity)
    {
        return rarity switch
        {
            CatalogRarity.Common => new Color(236, 236, 236),
            CatalogRarity.Uncommon => new Color(132, 232, 148),
            CatalogRarity.Rare => new Color(132, 186, 255),
            CatalogRarity.Legendary => new Color(255, 214, 118),
            _ => Color.White
        };
    }

    private void DrawCatalogHoverTooltip(SpriteBatch sb, BlockId blockId, Rectangle hoveredRowRect)
    {
        var def = BlockRegistry.Get(blockId);
        var lore = _catalogLoreByBlock.TryGetValue(blockId, out var entry)
            ? entry
            : new CatalogLoreEntry(def.Name, BuildDefaultCatalogDescription(def), Array.Empty<string>(), ResolveCatalogRarity(blockId, def));
        var rarity = lore.Rarity;
        var rarityColor = GetCatalogRarityColor(rarity);
        var rarityLabel = rarity switch
        {
            CatalogRarity.Common => "COMMON",
            CatalogRarity.Uncommon => "UNCOMMON",
            CatalogRarity.Rare => "RARE",
            CatalogRarity.Legendary => "LEGENDARY",
            _ => "COMMON"
        };

        var title = lore.DisplayName.ToUpperInvariant();
        var description = string.IsNullOrWhiteSpace(lore.Description)
            ? BuildDefaultCatalogDescription(def)
            : lore.Description;
        var wrapped = WrapOverlayText(description, CatalogTooltipMaxWidth - 30);
        var maxTextWidth = _font.MeasureString(title).X + 14 + _font.MeasureString(rarityLabel).X;
        for (var i = 0; i < wrapped.Count; i++)
            maxTextWidth = Math.Max(maxTextWidth, _font.MeasureString(wrapped[i]).X);

        var panelWidth = (int)Math.Ceiling(Math.Clamp(maxTextWidth + 20f, 240f, CatalogTooltipMaxWidth));
        var panelHeight = 12 + _font.LineHeight + 8 + (wrapped.Count * (_font.LineHeight + 2)) + 10;

        var x = _inventoryMousePos.X + 18;
        var y = _inventoryMousePos.Y + 18;
        var minX = _viewport.X + 8;
        var minY = _viewport.Y + 8;
        var maxX = _viewport.Right - panelWidth - 8;
        var maxY = _viewport.Bottom - panelHeight - 8;
        if (maxX < minX)
            x = minX;
        else
            x = Math.Clamp(x, minX, maxX);

        if (maxY < minY)
            y = minY;
        else
            y = Math.Clamp(y, minY, maxY);

        if (y + panelHeight > _inventoryCatalogListRect.Bottom && hoveredRowRect.Top - panelHeight - 8 >= _viewport.Y + 8)
            y = hoveredRowRect.Top - panelHeight - 8;

        var panel = new Rectangle(x, y, panelWidth, panelHeight);
        sb.Draw(_pixel, panel, new Color(8, 10, 14, 244));
        DrawBorder(sb, panel, new Color(208, 218, 234, 220));

        var divider = new Rectangle(panel.X + 10, panel.Y + 12 + _font.LineHeight + 2, panel.Width - 20, 1);
        sb.Draw(_pixel, divider, new Color(76, 90, 112, 210));

        var titlePos = new Vector2(panel.X + 10, panel.Y + 10);
        var titleShadow = titlePos + new Vector2(1f, 1f);
        _font.DrawString(sb, title, titleShadow, new Color(0, 0, 0, 210));
        _font.DrawString(sb, title, titlePos, rarityColor);

        var raritySize = _font.MeasureString(rarityLabel);
        var rarityPos = new Vector2(panel.Right - raritySize.X - 10, panel.Y + 10);
        _font.DrawString(sb, rarityLabel, rarityPos + new Vector2(1f, 1f), new Color(0, 0, 0, 210));
        _font.DrawString(sb, rarityLabel, rarityPos, rarityColor);

        var textY = divider.Bottom + 6;
        for (var i = 0; i < wrapped.Count; i++)
        {
            var linePos = new Vector2(panel.X + 10, textY + i * (_font.LineHeight + 2));
            _font.DrawString(sb, wrapped[i], linePos + new Vector2(1f, 1f), new Color(0, 0, 0, 200));
            _font.DrawString(sb, wrapped[i], linePos, new Color(236, 242, 255));
        }
    }

    private string TruncateCatalogLabel(string text, int maxWidth)
    {
        if (string.IsNullOrEmpty(text) || maxWidth <= 0)
            return string.Empty;

        if (_font.MeasureString(text).X <= maxWidth)
            return text;

        const string ellipsis = "...";
        if (_font.MeasureString(ellipsis).X > maxWidth)
            return string.Empty;

        for (var length = text.Length - 1; length > 0; length--)
        {
            var candidate = text.Substring(0, length) + ellipsis;
            if (_font.MeasureString(candidate).X <= maxWidth)
                return candidate;
        }

        return ellipsis;
    }

    private void WarmBlockIcons()
    {
        if (_blockIconCache == null)
            return;

        const int pad = 6;
        var hotbarSize = _hotbarSlots.Length > 0 && _hotbarSlots[0].Width > 0
            ? _hotbarSlots[0].Width - pad * 2
            : InventorySlotSize - pad * 2;

        WarmIconSlots(_inventory.Hotbar, hotbarSize);

        if (_inventoryOpen)
        {
            var gridSize = _inventoryGridSlots.Length > 0 && _inventoryGridSlots[0].Width > 0
                ? _inventoryGridSlots[0].Width - pad * 2
                : InventorySlotSize - pad * 2;
            if (_gameMode == GameMode.Artificer && _artificerInventoryView == ArtificerInventoryView.Catalog)
                WarmVisibleCatalogIcons(CatalogRowIconSize);
            else
                WarmIconSlots(_inventory.Grid, gridSize);
        }

        if (_inventoryHasHeld && _inventoryHeld.Id != BlockId.Air)
        {
            var heldSize = _inventoryGridSlots.Length > 0 && _inventoryGridSlots[0].Width > 0
                ? _inventoryGridSlots[0].Width - pad * 2
                : InventorySlotSize - pad * 2;
            _blockIconCache.Warm(_inventoryHeld.Id, heldSize, BlockModelContext.Gui);
        }
    }

    private void WarmIconSlots(HotbarSlot[] slots, int size)
    {
        for (var i = 0; i < slots.Length; i++)
        {
            var slot = slots[i];
            if (slot.Count <= 0 || slot.Id == BlockId.Air)
                continue;

            _blockIconCache?.Warm(slot.Id, size, BlockModelContext.Gui);
        }
    }

    private void WarmVisibleCatalogIcons(int size)
    {
        if (_inventoryCatalogListRect.Width <= 0 || _inventoryCatalogListRect.Height <= 0)
            return;

        var total = _inventory.GetSandboxCatalogFilteredCount();
        if (total <= 0)
            return;

        var first = Math.Max(0, (int)MathF.Floor(_inventoryCatalogScrollOffsetPx / CatalogRowHeight) - CatalogRowOverscan);
        var visible = Math.Max(1, (int)MathF.Ceiling(_inventoryCatalogListRect.Height / (float)CatalogRowHeight) + CatalogRowOverscan * 2);
        var last = Math.Min(total - 1, first + visible - 1);
        for (var i = first; i <= last; i++)
        {
            var slot = _inventory.GetSandboxCatalogFilteredEntryAt(i);
            if (slot.Id == BlockId.Air || slot.Count <= 0)
                continue;

            _blockIconCache?.Warm(slot.Id, size, BlockModelContext.Gui);
        }
    }

    private Texture2D? GetBlockIcon(BlockId id, int size)
    {
        return _blockIconCache?.GetOrCreate(id, size, BlockModelContext.Gui);
    }

    private Texture2D? GetBlockIconIfReady(BlockId id, int size)
    {
        return _blockIconCache?.GetIfReady(id, size, BlockModelContext.Gui);
    }

    private void CloseInventory()
    {
        if (_soulLootOpen)
        {
            ReturnHeldSoulLootItemToSourceOrFallback();
            var shouldDismissClearedSoul = _soulLootPendingClearRemoval && _soulMarker.Active && !HasSoulInventoryItems();
            _soulLootOpen = false;
            _soulLootSourcePlayerId = -1;
            _soulLootClearConfirmPending = false;
            _soulLootPendingClearRemoval = false;
            _soulLootTitleText = string.Empty;
            _soulLootStatusText = string.Empty;
            _inventoryOpen = false;
            if (shouldDismissClearedSoul)
                ClearSoulMarker(saveImmediately: true);
            return;
        }

        if (_inventoryHasHeld && _inventoryHeld.Id != BlockId.Air && _inventoryHeld.Count > 0)
        {
            if (_inventory.Mode != GameMode.Veilwalker)
            {
                var leftover = _inventory.Add(_inventoryHeld.Id, _inventoryHeld.Count);
                if (leftover > 0)
                    SpawnDroppedItem(_inventoryHeld.Id, leftover);
                MarkPlayerStateDirty(); // Mark dirty after inventory change
            }

            _inventoryHeld = default;
            _inventoryHasHeld = false;
            _heldFrom = InventorySlotGroup.None;
            _heldIndex = -1;
        }

        if (HasActiveRemoteInventoryView())
        {
            ClearInventoryView(preserveSpectate: true);
            return;
        }

        _inventoryCatalogSearchFocused = false;
        _inventoryCatalogSearchCaret = 0;
        _inventoryOpen = false;
    }

    private void HandleInventorySlotClick(ref HotbarSlot slot, InventorySlotGroup group, int index, bool sandboxCatalogMode)
    {
        if (sandboxCatalogMode)
        {
            HandleSandboxInventoryClick(ref slot, group, index);
            return;
        }

        if (!_inventoryHasHeld)
        {
            if (slot.Count <= 0 || slot.Id == BlockId.Air)
                return;
            _inventoryHeld = slot;
            _inventoryHasHeld = true;
            _heldFrom = group;
            _heldIndex = index;
            slot = default;
            return;
        }

        var temp = slot;
        slot = _inventoryHeld;
        _inventoryHeld = temp;
        _inventoryHasHeld = _inventoryHeld.Count > 0 && _inventoryHeld.Id != BlockId.Air;
        if (_inventoryHasHeld)
        {
            _heldFrom = group;
            _heldIndex = index;
        }
        else
        {
            _heldFrom = InventorySlotGroup.None;
            _heldIndex = -1;
        }

        // Non-artificer mode keeps standard move/swap behavior.
    }

    private void HandleInventorySlotRightClick(ref HotbarSlot slot, InventorySlotGroup group, int index, bool sandboxCatalogMode)
    {
        if (sandboxCatalogMode)
        {
            HandleSandboxInventoryRightClick(ref slot, group, index);
            return;
        }

        if (_inventoryHasHeld && _inventoryHeld.Id != BlockId.Air && _inventoryHeld.Count > 0)
        {
            var max = _inventory.GetMaxStackSize(_inventoryHeld.Id);
            if (slot.Id != BlockId.Air && slot.Id != _inventoryHeld.Id)
                return;

            if (slot.Count >= max)
                return;

            if (slot.Id == BlockId.Air || slot.Count <= 0)
                slot = new HotbarSlot { Id = _inventoryHeld.Id, Count = 0 };

            slot.Count++;
            _inventoryHeld.Count--;
            if (_inventoryHeld.Count <= 0)
            {
                _inventoryHeld = default;
                _inventoryHasHeld = false;
                _heldFrom = InventorySlotGroup.None;
                _heldIndex = -1;
            }
            return;
        }

        if (slot.Id == BlockId.Air || slot.Count <= 0)
            return;

        var take = (slot.Count + 1) / 2;
        _inventoryHeld = new HotbarSlot { Id = slot.Id, Count = take };
        _inventoryHasHeld = true;
        _heldFrom = group;
        _heldIndex = index;
        slot.Count -= take;
        if (slot.Count <= 0)
            slot = default;
    }

    private void ClampSandboxSlot(ref HotbarSlot slot)
    {
        if (slot.Id == BlockId.Air || slot.Count <= 0)
        {
            slot = default;
            return;
        }

        var max = _inventory.GetMaxStackSize(slot.Id);
        if (slot.Count > max)
            slot.Count = max;
    }

    private void HandleSandboxInventoryClick(ref HotbarSlot slot, InventorySlotGroup group, int index)
    {
        if (group == InventorySlotGroup.Grid)
        {
            if (slot.Count <= 0 || slot.Id == BlockId.Air)
                return;

            _inventoryHeld = slot;
            _inventoryHasHeld = true;
            _heldFrom = InventorySlotGroup.None;
            _heldIndex = -1;
            return;
        }

        // Hotbar: place copies from held, or pick up existing hotbar items.
        if (_inventoryHasHeld)
        {
            slot = _inventoryHeld;
            ClampSandboxSlot(ref slot);
            _inventoryHeld = default;
            _inventoryHasHeld = false;
            _heldFrom = InventorySlotGroup.None;
            _heldIndex = -1;
            return;
        }

        if (slot.Count <= 0 || slot.Id == BlockId.Air)
            return;

        _inventoryHeld = slot;
        _inventoryHasHeld = true;
        _heldFrom = InventorySlotGroup.None;
        _heldIndex = -1;
        slot = default;
    }

    private void HandleSandboxInventoryRightClick(ref HotbarSlot slot, InventorySlotGroup group, int index)
    {
        if (group == InventorySlotGroup.Grid)
        {
            if (slot.Count <= 0 || slot.Id == BlockId.Air)
                return;

            TryCollectCatalogItemToCursor(slot.Id, 1);
            return;
        }

        if (_inventoryHasHeld && _inventoryHeld.Id != BlockId.Air && _inventoryHeld.Count > 0)
        {
            var max = _inventory.GetMaxStackSize(_inventoryHeld.Id);
            if (slot.Id != BlockId.Air && slot.Id != _inventoryHeld.Id)
                return;

            if (slot.Id == BlockId.Air || slot.Count <= 0)
                slot = new HotbarSlot { Id = _inventoryHeld.Id, Count = 0 };

            if (slot.Count >= max)
                return;

            slot.Count++;
            ClampSandboxSlot(ref slot);
            return;
        }

        if (slot.Count <= 0 || slot.Id == BlockId.Air)
            return;

        _inventoryHeld = new HotbarSlot { Id = slot.Id, Count = 1 };
        _inventoryHasHeld = true;
        _heldFrom = InventorySlotGroup.None;
        _heldIndex = -1;
    }

    private bool TryCollectCatalogItemToCursor(BlockId id, int amount)
    {
        if (id == BlockId.Air || amount <= 0)
            return false;

        var max = _inventory.GetMaxStackSize(id);
        if (max <= 0)
            return false;

        if (!_inventoryHasHeld || _inventoryHeld.Id == BlockId.Air || _inventoryHeld.Count <= 0)
        {
            _inventoryHeld = new HotbarSlot
            {
                Id = id,
                Count = Math.Min(amount, max)
            };
            _inventoryHasHeld = _inventoryHeld.Count > 0;
            _heldFrom = InventorySlotGroup.None;
            _heldIndex = -1;
            return _inventoryHasHeld;
        }

        if (_inventoryHeld.Id != id || _inventoryHeld.Count >= max)
            return false;

        _inventoryHeld.Count = Math.Min(max, _inventoryHeld.Count + amount);
        return true;
    }

    private bool AlreadyOwnsItem(BlockId id)
    {
        if (id == BlockId.Air)
            return false;

        if (_inventory.Contains(id))
            return true;

        return _inventoryHasHeld && _inventoryHeld.Id == id && _inventoryHeld.Count > 0;
    }

    private enum InventorySlotGroup
    {
        None,
        Grid,
        Hotbar,
        SoulHotbar,
        SoulGrid
    }

    private enum ArtificerInventoryView
    {
        Catalog,
        Inventory
    }

    private ArtificerInventoryView _artificerInventoryView = ArtificerInventoryView.Catalog;
    private ArtificerInventoryView _lastArtificerInventoryView = ArtificerInventoryView.Catalog;

    private void DrawHotbar(SpriteBatch sb)
    {
        DrawHotbar(sb, _inventory.Hotbar, _inventory.SelectedIndex, _overlayMousePos, enableHover: true);
    }

    private void DrawHotbar(SpriteBatch sb, HotbarSlot[] slots, int selectedIndex, Point mousePosition, bool enableHover)
    {
        var hotbarIds = new byte[Inventory.HotbarSize];
        var hotbarCounts = new byte[Inventory.HotbarSize];
        for (int i = 0; i < Math.Min(Inventory.HotbarSize, slots.Length); i++)
        {
            hotbarIds[i] = (byte)slots[i].Id;
            hotbarCounts[i] = (byte)Math.Min(slots[i].Count, 255);
        }

        DrawHotbar(sb, hotbarIds, hotbarCounts, selectedIndex, mousePosition, enableHover);
    }

    private void DrawHotbar(SpriteBatch sb, byte[]? hotbarIds, byte[]? hotbarCounts, int selectedIndex, Point mousePosition, bool enableHover)
    {
        if (_viewport != UiLayout.Viewport)
            UpdateHotbarLayout();

        var panelRect = new Rectangle(
            _hotbarRect.X - HotbarBackdropPadX,
            _hotbarRect.Y - HotbarBackdropPadY,
            _hotbarRect.Width + HotbarBackdropPadX * 2,
            _hotbarRect.Height + HotbarBackdropPadY * 2);
        sb.Draw(_pixel, panelRect, new Color(18, 28, 46, 170));
        var innerPanelRect = new Rectangle(panelRect.X + 3, panelRect.Y + 3, panelRect.Width - 6, panelRect.Height - 6);
        sb.Draw(_pixel, innerPanelRect, new Color(28, 42, 68, 125));
        DrawBorder(sb, panelRect, new Color(170, 190, 220, 155));

        for (int i = 0; i < _hotbarSlots.Length; i++)
        {
            var rect = _hotbarSlots[i];
            var selected = i == selectedIndex;
            var bg = selected ? new Color(70, 70, 70, 220) : new Color(20, 20, 20, 180);
            sb.Draw(_pixel, rect, bg);
            if (enableHover && rect.Contains(mousePosition))
                sb.Draw(_pixel, rect, new Color(150, 150, 150, 70));
            DrawBorder(sb, rect, selected ? Color.Yellow : Color.White);

            var slotId = i < (hotbarIds?.Length ?? 0) ? (BlockId)hotbarIds![i] : BlockId.Air;
            var slotCount = i < (hotbarCounts?.Length ?? 0) ? hotbarCounts![i] : 0;
            if (slotCount > 0 && slotId != BlockId.Air && _atlas != null)
            {
                var src = _atlas.GetFaceSourceRect((byte)slotId, FaceDirection.PosY);
                var pad = 6;
                var dst = new Rectangle(rect.X + pad, rect.Y + pad, rect.Width - pad * 2, rect.Height - pad * 2);
                var icon = GetBlockIcon(slotId, dst.Width);
                if (icon != null)
                    sb.Draw(icon, dst, Color.White);
                else
                    sb.Draw(_atlas.Texture, dst, src, Color.White);
            }

            if (slotCount > 1)
            {
                var text = slotCount.ToString();
                var size = _font.MeasureString(text);
                var pos = new Vector2(rect.Right - size.X - 4, rect.Bottom - size.Y - 2);
                _font.DrawString(sb, text, pos, Color.White);
            }
        }
    }

    private bool TryHandleSoulRightClick(Vector3 origin, Vector3 dir)
    {
        if (!TrySelectSoulLootTarget(origin, dir, out var targetPlayerId))
            return false;

        _soulLootSourcePlayerId = targetPlayerId;
        OpenSoulLootGui();
        return true;
    }

    private static bool RayIntersectsSphere(Vector3 origin, Vector3 dir, Vector3 center, float radius)
    {
        var oc = origin - center;
        var a = Vector3.Dot(dir, dir);
        var b = 2f * Vector3.Dot(oc, dir);
        var c = Vector3.Dot(oc, oc) - radius * radius;
        var discriminant = b * b - 4f * a * c;
        if (discriminant < 0f)
            return false;

        var sqrt = MathF.Sqrt(discriminant);
        var t0 = (-b - sqrt) / (2f * a);
        var t1 = (-b + sqrt) / (2f * a);
        return t0 >= 0f || t1 >= 0f;
    }

    private bool RayIntersectsSoulBody(Vector3 soulPosition, Vector3 origin, Vector3 dir)
    {
        var bodyMin = soulPosition + new Vector3(-0.7f, -0.08f, -0.7f);
        var bodyMax = soulPosition + new Vector3(0.7f, 1.98f, 0.7f);
        if (RayIntersectsAabb(origin, dir, bodyMin, bodyMax))
            return true;

        var torsoCenter = soulPosition + new Vector3(0f, 0.92f, 0f);
        return RayIntersectsSphere(origin, dir, torsoCenter, 1.05f);
    }

    private bool TrySelectSoulLootTarget(Vector3 origin, Vector3 dir, out int targetPlayerId)
    {
        targetPlayerId = -1;
        var normalizedDir = Vector3.Normalize(dir);
        var closestDistSq = float.MaxValue;

        if (_soulMarker.Active && HasSoulInventoryItems())
        {
            var toSoul = _soulMarker.Position - origin;
            var distSq = toSoul.LengthSquared();
            if (distSq <= InteractRange * InteractRange && RayIntersectsSoulBody(_soulMarker.Position, origin, normalizedDir))
            {
                targetPlayerId = _lanSession?.LocalPlayerId ?? 0;
                closestDistSq = distSq;
            }
        }

        if (_sharedSoulAccessEnabled)
        {
            foreach (var pair in _remoteSoulStates)
            {
                var soulPosition = GetSoulMarkerVisualPosition(pair.Value);
                var toSoul = soulPosition - origin;
                var distSq = toSoul.LengthSquared();
                if (distSq > InteractRange * InteractRange || distSq >= closestDistSq)
                    continue;
                if (!RayIntersectsSoulBody(soulPosition, origin, normalizedDir))
                    continue;

                targetPlayerId = pair.Key;
                closestDistSq = distSq;
            }
        }

        return targetPlayerId >= 0;
    }

    private static bool RayIntersectsAabb(Vector3 origin, Vector3 dir, Vector3 min, Vector3 max)
    {
        const float epsilon = 0.0001f;
        var tMin = 0f;
        var tMax = float.MaxValue;

        if (!ClipRayAxis(origin.X, dir.X, min.X, max.X, ref tMin, ref tMax, epsilon))
            return false;
        if (!ClipRayAxis(origin.Y, dir.Y, min.Y, max.Y, ref tMin, ref tMax, epsilon))
            return false;
        if (!ClipRayAxis(origin.Z, dir.Z, min.Z, max.Z, ref tMin, ref tMax, epsilon))
            return false;

        return tMax >= Math.Max(0f, tMin);
    }

    private static bool ClipRayAxis(float origin, float dir, float min, float max, ref float tMin, ref float tMax, float epsilon)
    {
        if (MathF.Abs(dir) < epsilon)
            return origin >= min && origin <= max;

        var invDir = 1f / dir;
        var t0 = (min - origin) * invDir;
        var t1 = (max - origin) * invDir;
        if (t0 > t1)
            (t0, t1) = (t1, t0);

        tMin = Math.Max(tMin, t0);
        tMax = Math.Min(tMax, t1);
        return tMax >= tMin;
    }

    private void UpdateSoulLoot(InputState input)
    {
        if (!_inventoryOpen || !_soulLootOpen)
            return;

        if (_soulLootRect.Width <= 0 || _soulLootRect.Height <= 0)
            UpdateSoulLootLayout();

        if (IsNewActionPress(input, "Inventory", Keys.E) || input.IsNewKeyPress(Keys.Escape))
        {
            CloseInventory();
            return;
        }

        _inventoryMousePos = input.MousePosition;
        _soulLootClear.Visible = true;
        _soulLootClear.Enabled = IsViewingLocalSoul() && IsLocalPlayersSoul();
        _soulLootClear.Label = _soulLootClearConfirmPending ? "CONFIRM CLEAR" : "CLEAR SOUL";
        _soulLootTakeAll.Visible = true;
        _soulLootTakeAll.Enabled = CanTakeFromViewedSoul();
        _soulLootClose.Visible = true;
        _soulLootClose.Enabled = true;
        _soulLootClose.Update(input);
        if (IsViewingLocalSoul() && IsLocalPlayersSoul())
            _soulLootClear.Update(input);
        if (CanTakeFromViewedSoul())
            _soulLootTakeAll.Update(input);
        if (!_inventoryOpen || !_soulLootOpen)
            return;

        var p = _inventoryMousePos;
        var viewedSoulInventory = GetViewedSoulInventory();
        for (var i = 0; i < _soulLootSoulHotbarSlots.Length; i++)
        {
            if (!_soulLootSoulHotbarSlots[i].Contains(p))
                continue;

            var slot = i < viewedSoulInventory.Length ? viewedSoulInventory[i] : default;
            if (slot.Id != BlockId.Air && slot.Count > 0)
                SetDisplayName(BlockRegistry.Get(slot.Id).Name);
            break;
        }

        for (var i = 0; i < _soulLootSoulGridSlots.Length; i++)
        {
            if (!_soulLootSoulGridSlots[i].Contains(p))
                continue;

            var slot = Inventory.HotbarSize + i < viewedSoulInventory.Length ? viewedSoulInventory[Inventory.HotbarSize + i] : default;
            if (slot.Id != BlockId.Air && slot.Count > 0)
                SetDisplayName(BlockRegistry.Get(slot.Id).Name);
            break;
        }

        for (var i = 0; i < _soulLootPlayerGridSlots.Length; i++)
        {
            if (!_soulLootPlayerGridSlots[i].Contains(p))
                continue;

            var slot = _inventory.Grid[i];
            if (slot.Id != BlockId.Air && slot.Count > 0)
                SetDisplayName(BlockRegistry.Get(slot.Id).Name);
            break;
        }

        for (var i = 0; i < _hotbarSlots.Length; i++)
        {
            if (!_hotbarSlots[i].Contains(p))
                continue;

            var slot = _inventory.Hotbar[i];
            if (slot.Id != BlockId.Air && slot.Count > 0)
                SetDisplayName(BlockRegistry.Get(slot.Id).Name);
            break;
        }

        if (!input.IsNewLeftClick())
            return;

        var shiftDown = input.IsKeyDown(Keys.LeftShift) || input.IsKeyDown(Keys.RightShift);

        for (var i = 0; i < _soulLootSoulHotbarSlots.Length; i++)
        {
            if (!_soulLootSoulHotbarSlots[i].Contains(p))
                continue;

            if (IsViewingLocalSoul())
            {
                if (!CanModifyViewedSoul())
                    return;
            }
            else if (!CanTakeFromViewedSoul())
            {
                return;
            }

            if (shiftDown || !IsViewingLocalSoul())
                ShiftTransferSoulSlotToPlayer(i);
            else
                HandleSoulLootSlotClick(InventorySlotGroup.SoulHotbar, i);
            return;
        }

        for (var i = 0; i < _soulLootSoulGridSlots.Length; i++)
        {
            if (!_soulLootSoulGridSlots[i].Contains(p))
                continue;

            if (IsViewingLocalSoul())
            {
                if (!CanModifyViewedSoul())
                    return;
            }
            else if (!CanTakeFromViewedSoul())
            {
                return;
            }

            if (shiftDown || !IsViewingLocalSoul())
                ShiftTransferSoulSlotToPlayer(Inventory.HotbarSize + i);
            else
                HandleSoulLootSlotClick(InventorySlotGroup.SoulGrid, i);
            return;
        }

        if (!IsViewingLocalSoul() || !CanModifyViewedSoul())
            return;

        for (var i = 0; i < _soulLootPlayerGridSlots.Length; i++)
        {
            if (!_soulLootPlayerGridSlots[i].Contains(p))
                continue;

            if (shiftDown)
                ShiftTransferPlayerSlotToSoul(InventorySlotGroup.Grid, i);
            else
                HandleSoulLootSlotClick(InventorySlotGroup.Grid, i);
            return;
        }

        for (var i = 0; i < _hotbarSlots.Length; i++)
        {
            if (!_hotbarSlots[i].Contains(p))
                continue;

            if (shiftDown)
                ShiftTransferPlayerSlotToSoul(InventorySlotGroup.Hotbar, i);
            else
                HandleSoulLootSlotClick(InventorySlotGroup.Hotbar, i);
            return;
        }
    }

    private bool TryGetObservedVitals(out int health, out int hunger, out float sigilAtonement, out float sigilCurse)
    {
        if (_gameMode == GameMode.Veilwalker)
        {
            health = _survivalVitals.Health;
            hunger = _survivalVitals.Hunger;
            sigilAtonement = _debugSigilPositiveFraction;
            sigilCurse = _debugSigilNegativeFraction;
            return true;
        }

        if (_gameMode == GameMode.Veilseer
            && _veilseerSpectateTargetPlayerId >= 0
            && _remoteHealthByPlayerId.TryGetValue(_veilseerSpectateTargetPlayerId, out health))
        {
            hunger = _remoteHungerByPlayerId.TryGetValue(_veilseerSpectateTargetPlayerId, out var remoteHunger)
                ? remoteHunger
                : SurvivalVitals.MaxHunger;
            sigilAtonement = _remoteSigilAtonementByPlayerId.TryGetValue(_veilseerSpectateTargetPlayerId, out var remoteAtonement)
                ? remoteAtonement
                : 0f;
            sigilCurse = _remoteSigilCurseByPlayerId.TryGetValue(_veilseerSpectateTargetPlayerId, out var remoteCurse)
                ? remoteCurse
                : 0f;
            return true;
        }

        health = 0;
        hunger = 0;
        sigilAtonement = 0f;
        sigilCurse = 0f;
        return false;
    }

    private void DrawSurvivalHud(SpriteBatch sb)
    {
        if (_hotbarRect.Width <= 0 || !TryGetObservedVitals(out var health, out var hunger, out var sigilAtonement, out var sigilCurse))
            return;

        const int segmentCount = 10;
        const int healthSegmentWidth = 24;
        const int healthSegmentHeight = 27;
        const int healthSegmentGap = 2;
        const int hungerSegmentWidth = 24;
        const int hungerSegmentHeight = 27;
        const int hungerSegmentGap = 2;
        var hungerClusterWidth = segmentCount * hungerSegmentWidth + (segmentCount - 1) * hungerSegmentGap;
        var top = GetSurvivalHudTop(healthSegmentHeight, hungerSegmentHeight);
        var leftStartX = _hotbarRect.X;
        var rightStartX = _hotbarRect.Right - hungerClusterWidth;

        if (TryGetSigilHudRect(out var sigilRect))
        {
            DrawSigilMeter(sb, sigilRect, sigilAtonement, sigilCurse);
            DrawSigilHoverLabel(sb, sigilRect, sigilAtonement, sigilCurse);
        }

        DrawSurvivalSegments(
            sb,
            leftStartX,
            top,
            health,
            new Color(74, 12, 18, 210),
            new Color(236, 72, 98),
            new Color(255, 214, 220),
            alignRight: false,
            healthSegmentWidth,
            healthSegmentHeight,
            healthSegmentGap,
            SurvivalPipStyle.Diamond,
            _healthHudTexture,
            HealthFullIconSource,
            HealthEmptyIconSource);
        var healthRect = new Rectangle(leftStartX, top, segmentCount * healthSegmentWidth + (segmentCount - 1) * healthSegmentGap, healthSegmentHeight);
        DrawSurvivalHoverLabel(sb, healthRect, "HEALTH", health, SurvivalVitals.MaxHealth);

        DrawSurvivalSegments(
            sb,
            rightStartX,
            top,
            hunger,
            GetHungerEmptyColor(hunger),
            GetHungerFillColor(hunger),
            GetHungerShineColor(hunger),
            alignRight: true,
            hungerSegmentWidth,
            hungerSegmentHeight,
            hungerSegmentGap,
            SurvivalPipStyle.Cookie,
            _hungerHudTexture,
            HungerFullIconSource,
            HungerEmptyIconSource,
            fillFromRight: false);
        var hungerRect = new Rectangle(rightStartX, top, hungerClusterWidth, hungerSegmentHeight);
        DrawSurvivalHoverLabel(sb, hungerRect, "HUNGER", hunger, SurvivalVitals.MaxHunger);
    }

    private Color GetHungerEmptyColor(int hunger)
    {
        var fraction = Math.Clamp(hunger / (float)SurvivalVitals.MaxHunger, 0f, 1f);
        if (fraction <= 0.30f)
            return new Color(86, 22, 18, 225);
        if (fraction <= 0.60f)
            return new Color(94, 52, 16, 215);
        return new Color(76, 48, 10, 210);
    }

    private Color GetHungerFillColor(int hunger)
    {
        var fraction = Math.Clamp(hunger / (float)SurvivalVitals.MaxHunger, 0f, 1f);
        if (fraction <= 0.30f)
        {
            var pulse = 0.75f + (((MathF.Sin(_worldTimeSeconds * 6f) + 1f) * 0.5f) * 0.25f);
            return Color.Lerp(new Color(200, 56, 36), new Color(255, 114, 84), pulse);
        }

        if (fraction <= 0.60f)
            return new Color(230, 138, 52);

        return new Color(244, 180, 60);
    }

    private Color GetHungerShineColor(int hunger)
    {
        var fraction = Math.Clamp(hunger / (float)SurvivalVitals.MaxHunger, 0f, 1f);
        if (fraction <= 0.30f)
            return new Color(255, 214, 196);
        if (fraction <= 0.60f)
            return new Color(255, 224, 164);
        return new Color(255, 236, 190);
    }

    private void DrawSoulMarkerHud(SpriteBatch sb, GraphicsDevice device, Matrix view, Matrix proj)
    {
        if (!_soulMarkerGuidanceEnabled || _hotbarRect.Width <= 0)
            return;

        var hasLocalSoul = _soulMarker.Active;
        var hasRemoteSoul = _remoteSoulStates.Values.Any(state => state.HasSoulMarker && HasAnySoulInventoryItems(state.SoulInventory));
        if (!hasLocalSoul && !hasRemoteSoul)
            return;

        if (hasLocalSoul)
            DrawSoulMarkerNameLabel(sb, device, view, proj, _soulMarker.Position, _soulMarker.OwnerUsername);

        foreach (var pair in _remoteSoulStates)
        {
            if (!pair.Value.HasSoulMarker || !HasAnySoulInventoryItems(pair.Value.SoulInventory))
                continue;

            DrawSoulMarkerNameLabel(sb, device, view, proj, GetSoulMarkerVisualPosition(pair.Value), pair.Value.SoulOwnerUsername);
        }

        if (!hasLocalSoul)
            return;

        var soulAnchor = _soulMarker.Position + new Vector3(0f, 0.92f, 0f);
        var distanceBlocks = Vector3.Distance(_player.Position, _soulMarker.BasePosition) / Scale.BlockSize;
        var label = $"SOUL {MathF.Round(distanceBlocks):0}m";

        if (TryProjectWorldPointToUi(device, soulAnchor, view, proj, out var uiPos, out _))
        {
            var size = _font.MeasureString(label);
            var rect = new Rectangle(
                (int)MathF.Round(uiPos.X - size.X * 0.5f - 6f),
                (int)MathF.Round(uiPos.Y - _font.LineHeight - 10f),
                (int)MathF.Ceiling(size.X) + 12,
                _font.LineHeight + 8);
            sb.Draw(_pixel, rect, new Color(0, 0, 0, 155));
            DrawBorder(sb, rect, new Color(174, 239, 255, 185));
            _font.DrawString(sb, label, new Vector2(rect.X + 6, rect.Y + 4), new Color(232, 246, 255));
        }
        else
        {
            var delta = _soulMarker.BasePosition - _player.Position;
            var horizontal = new Vector2(delta.X, delta.Z);
            var dirText = horizontal.LengthSquared() > 0.001f
                ? $"SOUL {MathF.Round(distanceBlocks):0}m"
                : "SOUL";
            var topRect = new Rectangle(_viewport.Center.X - 94, _viewport.Y + 52, 188, _font.LineHeight + 10);
            sb.Draw(_pixel, topRect, new Color(0, 0, 0, 135));
            DrawBorder(sb, topRect, new Color(174, 239, 255, 165));
            _font.DrawString(sb, dirText, new Vector2(topRect.X + 12, topRect.Y + 5), new Color(232, 246, 255));
        }

        if (CanInteractWithSoul()
            && !_inventoryOpen
            && Vector3.Distance(_player.Position, _soulMarker.BasePosition) <= SoulMarkerRecoverRadiusBlocks * Scale.BlockSize)
        {
            var prompt = _soulRecoverStatusTimer > 0f && !string.IsNullOrWhiteSpace(_soulRecoverStatusText)
                ? _soulRecoverStatusText
                : "Crouch to reclaim all or right-click to open.";
            var promptSize = _font.MeasureString(prompt);
            var promptRect = new Rectangle(
                _viewport.Center.X - (int)MathF.Ceiling(promptSize.X * 0.5f) - 10,
                _viewport.Center.Y + 42,
                (int)MathF.Ceiling(promptSize.X) + 20,
                _font.LineHeight + 12);
            if (TryProjectWorldPointToUi(device, soulAnchor + new Vector3(0f, 0.45f, 0f), view, proj, out var promptPos, out _))
            {
                promptRect.X = (int)MathF.Round(promptPos.X - promptRect.Width * 0.5f);
                promptRect.Y = (int)MathF.Round(promptPos.Y - promptRect.Height - 10f);
            }

            sb.Draw(_pixel, promptRect, new Color(0, 0, 0, 170));
            DrawBorder(sb, promptRect, new Color(174, 239, 255, 135));
            _font.DrawString(sb, prompt, new Vector2(promptRect.X + 10, promptRect.Y + 6), new Color(232, 246, 255));

            if (_soulRecoverHoldActive)
            {
                var progress = Math.Clamp(_soulRecoverHoldElapsed / SoulRecoverHoldSeconds, 0f, 1f);
                var barRect = new Rectangle(promptRect.X + 14, promptRect.Bottom + 6, promptRect.Width - 28, 10);
                var fillRect = new Rectangle(barRect.X + 1, barRect.Y + 1, Math.Max(0, (int)((barRect.Width - 2) * progress)), Math.Max(0, barRect.Height - 2));
                sb.Draw(_pixel, barRect, new Color(20, 20, 20, 220));
                sb.Draw(_pixel, fillRect, new Color(90, 205, 140, 220));
                DrawBorder(sb, barRect, new Color(220, 240, 255, 170));
            }
        }
    }

    private int GetSurvivalHudTop(int healthSegmentHeight, int hungerSegmentHeight)
    {
        return _hotbarRect.Y - Math.Max(healthSegmentHeight, hungerSegmentHeight) - HotbarBackdropPadY;
    }

    private bool TryGetSigilHudRect(out Rectangle rect)
    {
        rect = Rectangle.Empty;
        if ((_gameMode != GameMode.Veilwalker && _gameMode != GameMode.Veilseer) || _hotbarRect.Width <= 0 || !_sigilPowerEnabled)
            return false;

        const int sigilSize = 132;
        var top = _hotbarRect.Y - sigilSize - 10;
        rect = new Rectangle(_hotbarRect.Center.X - sigilSize / 2, top, sigilSize, sigilSize);
        return true;
    }

    private void DrawSigilMeter(SpriteBatch sb, Rectangle rect, float positiveFraction, float negativeFraction)
    {
        var positive = Math.Clamp(positiveFraction, 0f, 1f);
        var negative = Math.Clamp(negativeFraction, 0f, 1f);
        if (_sigilHudTexture != null)
        {
            var baseSrc = new Rectangle(0, 0, SigilHudCellSize, SigilHudCellSize);
            sb.Draw(_sigilHudTexture, rect, baseSrc, Color.White);

            var positiveFrame = GetSigilFillFrameIndex(positive);
            if (positiveFrame > 0)
            {
                var positiveSrc = new Rectangle(positiveFrame * SigilHudCellSize, SigilHudCellSize, SigilHudCellSize, SigilHudCellSize);
                sb.Draw(_sigilHudTexture, rect, positiveSrc, Color.White);
            }

            var negativeFrame = GetSigilFillFrameIndex(negative);
            if (negativeFrame > 0)
            {
                var negativeSrc = new Rectangle(negativeFrame * SigilHudCellSize, SigilHudCellSize * 2, SigilHudCellSize, SigilHudCellSize);
                sb.Draw(_sigilHudTexture, rect, negativeSrc, Color.White);
            }
            return;
        }

        var outerColor = new Color(188, 196, 220);
        var innerColor = new Color(66, 74, 104);
        var positiveFill = new Color(92, 188, 228);
        var positiveGlow = new Color(216, 250, 255);
        var negativeFill = new Color(204, 76, 88);
        var negativeGlow = new Color(255, 212, 132);
        var backingColor = new Color(8, 8, 14, 150);

        sb.Draw(_pixel, new Rectangle(rect.X, rect.Y + 2, rect.Width, rect.Height - 4), backingColor);
        var outer = new Rectangle(rect.X + 3, rect.Y + 4, rect.Width - 6, rect.Height - 10);
        var inner = new Rectangle(rect.X + 9, rect.Y + 8, rect.Width - 18, rect.Height - 18);
        DrawBorder(sb, outer, outerColor);
        DrawBorder(sb, inner, innerColor);
        sb.Draw(_pixel, new Rectangle(rect.Center.X - 1, inner.Y + 1, 3, inner.Height - 2), outerColor);
        sb.Draw(_pixel, new Rectangle(inner.X + 1, rect.Center.Y - 4, inner.Width - 2, 2), outerColor);
        sb.Draw(_pixel, new Rectangle(inner.X + 1, rect.Center.Y + 3, inner.Width - 2, 2), outerColor);

        var leftArea = new Rectangle(inner.X + 1, inner.Y + 2, Math.Max(1, rect.Center.X - (inner.X + 2)), inner.Height - 4);
        var positiveWidth = Math.Clamp((int)MathF.Round(leftArea.Width * positive), 0, leftArea.Width);
        if (positiveWidth > 0)
        {
            var fillRect = new Rectangle(leftArea.Right - positiveWidth, leftArea.Y, positiveWidth, leftArea.Height);
            sb.Draw(_pixel, fillRect, positiveFill);
            sb.Draw(_pixel, new Rectangle(fillRect.X, fillRect.Y, Math.Min(3, fillRect.Width), fillRect.Height), positiveGlow);
        }

        var rightArea = new Rectangle(rect.Center.X + 2, inner.Y + 2, Math.Max(1, inner.Right - rect.Center.X - 3), inner.Height - 4);
        var negativeWidth = Math.Clamp((int)MathF.Round(rightArea.Width * negative), 0, rightArea.Width);
        if (negativeWidth > 0)
        {
            var fillRect = new Rectangle(rightArea.X, rightArea.Y, negativeWidth, rightArea.Height);
            sb.Draw(_pixel, fillRect, negativeFill);
            sb.Draw(_pixel, new Rectangle(Math.Max(fillRect.Right - 3, fillRect.X), fillRect.Y, Math.Min(3, fillRect.Width), fillRect.Height), negativeGlow);
        }

        var coreColor = positive >= negative ? positiveGlow : negativeGlow;
        sb.Draw(_pixel, new Rectangle(rect.Center.X - 2, rect.Center.Y - 2, 5, 5), coreColor);
    }

    private void DrawSigilHoverLabel(SpriteBatch sb, Rectangle rect, float positiveFraction, float negativeFraction)
    {
        if (!rect.Contains(_overlayMousePos))
            return;

        var label = _overlayMousePos.X < rect.Center.X ? SigilPositiveLabel : SigilNegativeLabel;
        var fraction = _overlayMousePos.X < rect.Center.X ? positiveFraction : negativeFraction;
        var text = $"{label} {MathF.Round(Math.Clamp(fraction, 0f, 1f) * 100f):0}%";
        var size = _font.MeasureString(text);
        var width = (int)Math.Ceiling(size.X) + 14;
        var height = _font.LineHeight + 8;
        var panelRect = new Rectangle(rect.Center.X - width / 2, rect.Y + 8, width, height);

        sb.Draw(_pixel, panelRect, new Color(232, 232, 224, 210));
        DrawBorder(sb, panelRect, new Color(84, 86, 90, 225));
        _font.DrawString(sb, text, new Vector2(panelRect.X + 7, panelRect.Y + 4), new Color(36, 38, 42));
    }

    private void DrawSurvivalHoverLabel(SpriteBatch sb, Rectangle rect, string label, int value, int maxValue)
    {
        if (!rect.Contains(_overlayMousePos) || maxValue <= 0)
            return;

        var percent = Math.Clamp(value / (float)maxValue, 0f, 1f) * 100f;
        var text = $"{label} {percent:0}%";
        var size = _font.MeasureString(text);
        var width = (int)MathF.Ceiling(size.X) + 14;
        var height = _font.LineHeight + 8;
        var panelRect = new Rectangle(
            rect.Center.X - width / 2,
            rect.Y - height - 6,
            width,
            height);

        sb.Draw(_pixel, panelRect, new Color(232, 232, 224, 210));
        DrawBorder(sb, panelRect, new Color(84, 86, 90, 225));
        _font.DrawString(sb, text, new Vector2(panelRect.X + 7, panelRect.Y + 4), new Color(36, 38, 42));
    }

    private static int GetSigilFillFrameIndex(float fraction)
    {
        var clamped = Math.Clamp(fraction, 0f, 1f);
        if (clamped <= 0f)
            return 0;

        return Math.Clamp((int)MathF.Ceiling(clamped * (SigilHudFrameCount - 1)), 1, SigilHudFrameCount - 1);
    }

    private void GetChatOverlayLayout(out int x, out int overlayWidth, out int overlayTop, out int overlayBottom)
    {
        x = _viewport.X + 20;
        overlayWidth = Math.Clamp((int)MathF.Round(_viewport.Width * ChatOverlayWidthRatio), ChatOverlayMinWidth, ChatOverlayMaxWidth);

        var bottomLimit = _hotbarRect.Y > 0
            ? _hotbarRect.Y - 92
            : _viewport.Bottom - 20;

        if (TryGetSigilHudRect(out var sigilRect))
        {
            bottomLimit = Math.Min(bottomLimit, sigilRect.Y - ChatOverlayHudClearance);
            var safeRight = sigilRect.X - ChatOverlayHudClearance;
            var maxWidthBeforeHud = safeRight - x;
            if (maxWidthBeforeHud > 220)
                overlayWidth = Math.Min(overlayWidth, maxWidthBeforeHud);
        }

        overlayBottom = Math.Min(_viewport.Bottom - 20, bottomLimit);
        overlayBottom = Math.Max(_viewport.Y + 160, overlayBottom);
        overlayTop = _viewport.Y + 120;
    }

    private void UpdateAttunementWipPopupLayout()
    {
        if (_viewport.Width <= 0 || _viewport.Height <= 0)
        {
            _attunementWipPopupRect = Rectangle.Empty;
            return;
        }

        var width = Math.Clamp(_viewport.Width - 240, 480, 800);
        var height = 250;
        _attunementWipPopupRect = new Rectangle(
            _viewport.Center.X - width / 2,
            _viewport.Center.Y - height / 2,
            width,
            height);
    }

    private void UpdateAttunementWipPopup(InputState input)
    {
        if (input.IsNewLeftClick()
            || input.IsNewKeyPress(Keys.Enter)
            || input.IsNewKeyPress(Keys.Space)
            || input.IsNewKeyPress(Keys.Escape))
        {
            _attunementWipPopupVisible = false;
            if (!_hasSeenAttunementWipPopup)
            {
                _hasSeenAttunementWipPopup = true;
                MarkPlayerStateDirty();
                SavePlayerState();
            }
        }
    }

    private void TryShowAttunementWipPopup()
    {
        if (_gameMode != GameMode.Veilwalker || _hasSeenAttunementWipPopup)
            return;

        _attunementWipPopupVisible = true;
        UpdateAttunementWipPopupLayout();
    }

    private void DrawAttunementWipPopup(SpriteBatch sb)
    {
        UpdateAttunementWipPopupLayout();
        if (_attunementWipPopupRect == Rectangle.Empty)
            return;

        sb.Begin(samplerState: SamplerState.PointClamp);
        sb.Draw(_pixel, UiLayout.WindowViewport, new Color(0, 0, 0, 168));
        sb.End();

        sb.Begin(samplerState: SamplerState.PointClamp, transformMatrix: UiLayout.Transform);
        sb.Draw(_pixel, _attunementWipPopupRect, new Color(222, 216, 202, 236));
        DrawBorder(sb, _attunementWipPopupRect, Color.Black);

        var title = "ATTUNEMENT BAR (WIP)";
        _font.DrawString(sb, title, new Vector2(_attunementWipPopupRect.X + 18, _attunementWipPopupRect.Y + 16), new Color(28, 28, 28));

        var previewRect = new Rectangle(_attunementWipPopupRect.X + 24, _attunementWipPopupRect.Y + 58, 96, 96);
        if (_sigilHudTexture != null)
        {
            GetAttunementPopupPreviewFractions(out var previewPositiveFraction, out var previewNegativeFraction);
            DrawSigilMeter(sb, previewRect, previewPositiveFraction, previewNegativeFraction);
        }
        else
        {
            sb.Draw(_pixel, previewRect, new Color(34, 34, 38));
            DrawBorder(sb, previewRect, Color.Black);
        }

        var textX = previewRect.Right + 18;
        var bodyMaxWidth = Math.Max(120, _attunementWipPopupRect.Right - textX - 18);
        var bodyLines = new List<string>();
        bodyLines.AddRange(WrapOverlayText("The Attunement bar is still work in progress.", bodyMaxWidth));
        bodyLines.Add(string.Empty);
        bodyLines.AddRange(WrapOverlayText("It will not be finalized until the default gameplay loop is complete.", bodyMaxWidth));
        bodyLines.Add(string.Empty);
        bodyLines.AddRange(WrapOverlayText("Atonement and Curse values are temporary placeholder-facing systems.", bodyMaxWidth));

        var bodyLineHeight = _font.LineHeight + 4;
        var bodyBlockHeight = Math.Max(0, bodyLines.Count * bodyLineHeight - 4);
        var textY = previewRect.Y + Math.Max(0, (previewRect.Height - bodyBlockHeight) / 2);
        for (int i = 0; i < bodyLines.Count; i++)
            _font.DrawString(sb, bodyLines[i], new Vector2(textX, textY + i * bodyLineHeight), new Color(38, 38, 42));

        var footer = "PRESS ENTER, SPACE, ESC, OR CLICK TO CONTINUE";
        var footerLines = WrapOverlayText(footer, _attunementWipPopupRect.Width - 36);
        var footerTop = _attunementWipPopupRect.Bottom - footerLines.Count * _font.LineHeight - 28;
        for (int i = 0; i < footerLines.Count; i++)
        {
            var footerLine = footerLines[i];
            var footerSize = _font.MeasureString(footerLine);
            _font.DrawString(
                sb,
                footerLine,
                new Vector2(_attunementWipPopupRect.Center.X - footerSize.X / 2f, footerTop + i * _font.LineHeight),
                new Color(54, 54, 58));
        }
        sb.End();
    }

    private void GetAttunementPopupPreviewFractions(out float positiveFraction, out float negativeFraction)
    {
        const float stageDuration = 1.6f;
        const float holdDuration = 0.45f;
        var cycle = stageDuration * 2f + holdDuration * 2f;
        var time = cycle <= 0f ? 0f : _worldTimeSeconds % cycle;

        if (time < stageDuration)
        {
            positiveFraction = Math.Clamp(time / stageDuration, 0f, 1f);
            negativeFraction = 0f;
            return;
        }

        time -= stageDuration;
        if (time < holdDuration)
        {
            positiveFraction = 1f;
            negativeFraction = 0f;
            return;
        }

        time -= holdDuration;
        if (time < stageDuration)
        {
            positiveFraction = 0f;
            negativeFraction = Math.Clamp(time / stageDuration, 0f, 1f);
            return;
        }

        positiveFraction = 0f;
        negativeFraction = 1f;
    }

    private enum SurvivalPipStyle
    {
        Diamond,
        Cookie
    }

    private static readonly Rectangle HealthFullIconSource = new(0, 458, 136, 152);
    private static readonly Rectangle HealthEmptyIconSource = new(800, 458, 139, 146);
    private static readonly Rectangle HungerFullIconSource = new(0, 458, 136, 152);
    private static readonly Rectangle HungerEmptyIconSource = new(800, 458, 139, 146);

    private void DrawSurvivalSegments(
        SpriteBatch sb,
        int startX,
        int top,
        int value,
        Color emptyColor,
        Color fillColor,
        Color shineColor,
        bool alignRight,
        int segmentWidth,
        int segmentHeight,
        int segmentGap,
        SurvivalPipStyle pipStyle,
        Texture2D? hudTexture,
        Rectangle fullIconSource,
        Rectangle emptyIconSource,
        bool? fillFromRight = null)
    {
        const int segmentCount = 10;
        const int segmentsPerRow = 10;
        var shouldFillFromRight = fillFromRight ?? alignRight;

        var filledSegments = Math.Clamp((int)MathF.Ceiling(value / 2f), 0, segmentCount);
        var halfFilled = value % 2 == 1;

        for (var i = 0; i < segmentCount; i++)
        {
            var column = i % segmentsPerRow;
            var drawColumn = alignRight ? (segmentsPerRow - 1 - column) : column;
            var drawIndex = alignRight ? (segmentCount - 1 - i) : i;
            var x = startX + (drawColumn * (segmentWidth + segmentGap));
            var y = top;
            var rect = new Rectangle(x, y, segmentWidth, segmentHeight);
            var fillFraction = drawIndex < filledSegments
                ? (halfFilled && drawIndex == filledSegments - 1 ? 0.5f : 1f)
                : 0f;
            if (hudTexture != null)
            {
                var assetRect = pipStyle == SurvivalPipStyle.Cookie
                    ? new Rectangle(rect.X + 1, rect.Y + 1, Math.Max(1, rect.Width - 2), Math.Max(1, rect.Height - 2))
                    : rect;
                DrawHudAssetPip(sb, hudTexture, assetRect, fillFraction, fullIconSource, emptyIconSource, shouldFillFromRight);
                continue;
            }
            switch (pipStyle)
            {
                case SurvivalPipStyle.Cookie:
                    DrawCookiePip(sb, rect, fillFraction, emptyColor, fillColor, shineColor, shouldFillFromRight);
                    break;
                default:
                    DrawDiamondPip(sb, rect, fillFraction, emptyColor, fillColor, shineColor, shouldFillFromRight);
                    break;
            }
        }
    }

    private void DrawDiamondPip(SpriteBatch sb, Rectangle rect, float fillFraction, Color emptyColor, Color fillColor, Color shineColor, bool alignRight)
    {
        ReadOnlySpan<int> insets = [10, 8, 6, 4, 2, 2, 4, 6, 8, 10];
        var frameColor = new Color(10, 12, 18, 220);
        var darkEdge = new Color(24, 27, 34, 220);
        var fill = Math.Clamp(fillFraction, 0f, 1f);

        for (var row = 0; row < insets.Length; row++)
        {
            var inset = insets[row];
            var rowY = rect.Y + row + 1;
            var rowWidth = rect.Width - (inset * 2);
            if (rowWidth <= 0 || rowY >= rect.Bottom - 1)
                continue;

            var rowX = rect.X + inset;
            sb.Draw(_pixel, new Rectangle(rowX - 1, rowY, rowWidth + 2, 1), frameColor);
            sb.Draw(_pixel, new Rectangle(rowX, rowY, rowWidth, 1), emptyColor);

            if (fill > 0f)
            {
                var filledWidth = Math.Clamp((int)MathF.Round(rowWidth * fill), 0, rowWidth);
                if (filledWidth > 0)
                {
                    var fillX = alignRight ? rowX + rowWidth - filledWidth : rowX;
                    sb.Draw(_pixel, new Rectangle(fillX, rowY, filledWidth, 1), fillColor);

                    var shineWidth = Math.Max(1, filledWidth - 1);
                    if (row <= 2 && shineWidth > 0)
                    {
                        var shineX = alignRight ? fillX + filledWidth - shineWidth : fillX;
                        sb.Draw(_pixel, new Rectangle(shineX, rowY, shineWidth, 1), shineColor);
                    }
                }
            }
        }

        var cutWidth = 3;
        var cutHeight = 2;
        var cutX = rect.Center.X - (cutWidth / 2);
        var cutY = rect.Center.Y - (cutHeight / 2);
        sb.Draw(_pixel, new Rectangle(cutX, cutY, cutWidth, cutHeight), frameColor);

        sb.Draw(_pixel, new Rectangle(rect.Center.X - 3, rect.Y + 2, 6, 1), darkEdge);
        sb.Draw(_pixel, new Rectangle(rect.Center.X - 3, rect.Bottom - 3, 6, 1), darkEdge);
    }

    private void DrawHudAssetPip(SpriteBatch sb, Texture2D texture, Rectangle rect, float fillFraction, Rectangle fullSource, Rectangle emptySource, bool alignRight)
    {
        sb.Draw(texture, rect, emptySource, Color.White);

        var fill = Math.Clamp(fillFraction, 0f, 1f);
        if (fill <= 0f)
            return;

        var srcWidth = Math.Max(1, (int)MathF.Round(fullSource.Width * fill));
        var dstWidth = Math.Max(1, (int)MathF.Round(rect.Width * fill));
        Rectangle src;
        Rectangle dst;
        if (alignRight)
        {
            src = new Rectangle(fullSource.Right - srcWidth, fullSource.Y, srcWidth, fullSource.Height);
            dst = new Rectangle(rect.Right - dstWidth, rect.Y, dstWidth, rect.Height);
        }
        else
        {
            src = new Rectangle(fullSource.X, fullSource.Y, srcWidth, fullSource.Height);
            dst = new Rectangle(rect.X, rect.Y, dstWidth, rect.Height);
        }

        sb.Draw(texture, dst, src, Color.White);
    }

    private void DrawCookiePip(SpriteBatch sb, Rectangle rect, float fillFraction, Color emptyColor, Color fillColor, Color shineColor, bool alignRight)
    {
        var frameColor = new Color(58, 36, 12, 230);
        var fill = Math.Clamp(fillFraction, 0f, 1f);
        var body = new Rectangle(rect.X + 1, rect.Y + 2, rect.Width - 2, rect.Height - 4);

        for (var row = 0; row < body.Height; row++)
        {
            var curve = row switch
            {
                0 or 1 or 2 or 10 or 11 => 4,
                3 or 9 => 2,
                _ => 1
            };
            var biteTrim = row switch
            {
                3 or 4 => 2,
                5 or 6 or 7 => 4,
                8 => 2,
                _ => 0
            };
            var rowY = body.Y + row;
            var rowX = body.X + curve + (alignRight ? biteTrim : 0);
            var rowWidth = body.Width - (curve * 2) - biteTrim;
            if (rowWidth <= 0)
                continue;

            sb.Draw(_pixel, new Rectangle(rowX - 1, rowY, rowWidth + 2, 1), frameColor);
            sb.Draw(_pixel, new Rectangle(rowX, rowY, rowWidth, 1), emptyColor);

            if (fill > 0f)
            {
                var filledWidth = Math.Clamp((int)MathF.Round(rowWidth * fill), 0, rowWidth);
                if (filledWidth > 0)
                {
                    var fillX = alignRight ? rowX + rowWidth - filledWidth : rowX;
                    sb.Draw(_pixel, new Rectangle(fillX, rowY, filledWidth, 1), fillColor);
                    if (row <= 3)
                    {
                        var shineWidth = Math.Max(1, filledWidth - 2);
                        var shineX = alignRight ? fillX + filledWidth - shineWidth : fillX + 1;
                        sb.Draw(_pixel, new Rectangle(shineX, rowY, shineWidth, 1), shineColor);
                    }
                }
            }
        }

        DrawCookieChip(sb, rect.X + 6, rect.Y + 5, new Color(122, 72, 24));
        DrawCookieChip(sb, rect.Center.X - 1, rect.Y + 8, new Color(126, 76, 26));
        DrawCookieChip(sb, rect.Right - 8, rect.Y + 6, new Color(128, 78, 28));
    }

    private void DrawCookieChip(SpriteBatch sb, int x, int y, Color color)
    {
        sb.Draw(_pixel, new Rectangle(x, y, 2, 2), color);
        sb.Draw(_pixel, new Rectangle(x + 1, y + 1, 1, 1), new Color(152, 96, 40));
    }

    private void UpdateDeathScreenLayout()
    {
        var width = Math.Clamp(_viewport.Width - 320, 420, 660);
        var height = 220;
        _deathPopupRect = new Rectangle(
            _viewport.Center.X - width / 2,
            _viewport.Center.Y - height / 2,
            width,
            height);

        var buttonWidth = Math.Clamp((width - 84) / 2, 140, 220);
        var buttonHeight = 42;
        var buttonY = _deathPopupRect.Bottom - 62;
        _deathRespawn.Bounds = new Rectangle(_deathPopupRect.X + 28, buttonY, buttonWidth, buttonHeight);
        _deathQuit.Bounds = new Rectangle(_deathPopupRect.Right - buttonWidth - 28, buttonY, buttonWidth, buttonHeight);
    }

    private void UpdateDeathScreen(InputState input)
    {
        if (!_survivalRespawnPending)
            return;

        UpdateDeathScreenLayout();
        _deathRespawn.Update(input);
        _deathQuit.Update(input);

        if (input.IsNewKeyPress(Keys.Enter) || input.IsNewKeyPress(Keys.Space))
        {
            RespawnVeilwalkerPlayer();
            return;
        }

        if (input.IsNewKeyPress(Keys.Escape))
            SaveAndExit();
    }

    private void DrawRespawnOverlay(SpriteBatch sb)
    {
        if (!_survivalRespawnPending)
            return;

        UpdateDeathScreenLayout();
        sb.Draw(_pixel, _viewport, new Color(48, 48, 48, 180));

        if (_pausePanel != null)
            sb.Draw(_pausePanel, _deathPopupRect, Color.White);
        else
        {
            sb.Draw(_pixel, _deathPopupRect, new Color(18, 22, 28, 236));
            DrawBorder(sb, _deathPopupRect, new Color(180, 188, 200));
        }

        var title = "YOU DIED";
        var titleSize = _font.MeasureString(title);
        _font.DrawString(sb, title, new Vector2(_deathPopupRect.Center.X - titleSize.X / 2f, _deathPopupRect.Y + 20), new Color(244, 244, 244));

        var bodyLines = WrapOverlayText("Respawn at your spawn point, or quit out of the world.", _deathPopupRect.Width - 56);
        var textY = _deathPopupRect.Y + 68;
        for (var i = 0; i < bodyLines.Count; i++)
        {
            var line = bodyLines[i];
            var lineSize = _font.MeasureString(line);
            _font.DrawString(sb, line, new Vector2(_deathPopupRect.Center.X - lineSize.X / 2f, textY + i * (_font.LineHeight + 4)), new Color(214, 220, 228));
        }

        _deathRespawn.Draw(sb, _pixel, _font);
        _deathQuit.Draw(sb, _pixel, _font);
    }

    private void DrawDamageOverlay(SpriteBatch sb)
    {
        if (_damageFlashTimer <= 0f || _damageFlashStrength <= 0f)
            return;

        var normalized = Math.Clamp(_damageFlashTimer / DamageFlashDurationSeconds, 0f, 1f);
        var fade = MathF.Sin(normalized * MathF.PI);
        var alpha = MathF.Pow(fade, 1.6f) * _damageFlashStrength;
        var layers = 6;
        var maxThickness = Math.Max(18, Math.Min(_viewport.Width, _viewport.Height) / 18);
        var cornerSpanX = Math.Max(64, _viewport.Width / 5);
        var cornerSpanY = Math.Max(48, _viewport.Height / 5);
        for (var i = 0; i < layers; i++)
        {
            var t = i / (float)(layers - 1);
            var thickness = Math.Max(2, (int)MathF.Round(MathHelper.Lerp(maxThickness, 2f, t)));
            var inset = (int)MathF.Round(t * maxThickness * 1.85f);
            var layerAlpha = Math.Clamp((int)((1f - t) * (1f - t) * alpha * 8f), 0, 8);
            if (layerAlpha <= 0)
                continue;

            var tint = new Color(160, 24, 30, layerAlpha);
            var left = _viewport.X + inset;
            var top = _viewport.Y + inset;
            var width = _viewport.Width - (inset * 2);
            var height = _viewport.Height - (inset * 2);
            if (width <= 0 || height <= 0)
                break;

            var spanX = Math.Min(cornerSpanX, width / 2);
            var spanY = Math.Min(cornerSpanY, height / 2);

            sb.Draw(_pixel, new Rectangle(left, top, spanX, thickness), tint);
            sb.Draw(_pixel, new Rectangle(left, top, thickness, spanY), tint);

            sb.Draw(_pixel, new Rectangle(left + width - spanX, top, spanX, thickness), tint);
            sb.Draw(_pixel, new Rectangle(left + width - thickness, top, thickness, spanY), tint);

            sb.Draw(_pixel, new Rectangle(left, top + height - thickness, spanX, thickness), tint);
            sb.Draw(_pixel, new Rectangle(left, top + height - spanY, thickness, spanY), tint);

            sb.Draw(_pixel, new Rectangle(left + width - spanX, top + height - thickness, spanX, thickness), tint);
            sb.Draw(_pixel, new Rectangle(left + width - thickness, top + height - spanY, thickness, spanY), tint);
        }
    }

    private float GetDamageCameraKickAmount()
    {
        if (_damageCameraKickTimer <= 0f || _damageCameraKickStrength <= 0f)
            return 0f;

        var normalized = Math.Clamp(_damageCameraKickTimer / DamageCameraKickDurationSeconds, 0f, 1f);
        return MathF.Sin(normalized * MathF.PI) * _damageCameraKickStrength;
    }

    private void DrawContextIndicators(SpriteBatch sb)
    {
        if (!_indicatorsEnabled)
            return;

        var iconSize = Math.Clamp(_hotbarRect.Height, 24, 72);
        var sidePadding = Math.Max(10, iconSize / 5);
        var iconY = _hotbarRect.Y - HotbarBackdropPadY - iconSize - 4;

        if (_player.IsSprinting)
        {
            var footRect = new Rectangle(_hotbarRect.Left - iconSize - sidePadding, iconY, iconSize, iconSize);
            DrawIndicatorBadge(sb, footRect, new Color(44, 58, 32, 210), new Color(152, 214, 122));
            DrawFootIndicatorGlyph(sb, footRect, new Color(224, 255, 224));
        }

        var drawEye = _player.IsSneaking;
        var drawWing = _player.IsFlying && _gameMode != GameMode.Veilseer;
        var showRightIndicator = drawEye || drawWing;

        if (!showRightIndicator)
            return;

        var rightRect = new Rectangle(_hotbarRect.Right + sidePadding, iconY, iconSize, iconSize);
        if (drawEye)
        {
            DrawIndicatorBadge(sb, rightRect, new Color(30, 52, 72, 215), new Color(142, 214, 255));
            DrawEyeIndicatorGlyph(sb, rightRect, new Color(224, 245, 255));
        }
        else if (drawWing)
        {
            DrawIndicatorBadge(sb, rightRect, new Color(42, 52, 76, 215), new Color(198, 214, 255));
            DrawWingIndicatorGlyph(sb, rightRect, new Color(236, 242, 255));
        }
    }

    private void DrawIndicatorBadge(SpriteBatch sb, Rectangle rect, Color fill, Color border)
    {
        sb.Draw(_pixel, rect, fill);
        DrawBorder(sb, rect, border);
    }

    private void DrawFootIndicatorGlyph(SpriteBatch sb, Rectangle rect, Color color)
    {
        var soleH = ScaleGlyph(rect, 4f);
        var soleMargin = ScaleGlyph(rect, 4f);
        var heelW = ScaleGlyph(rect, 7f);
        var heelH = ScaleGlyph(rect, 4f);
        var heelX = rect.X + ScaleGlyph(rect, 5f);
        var heelY = rect.Bottom - ScaleGlyph(rect, 12f);
        var ankleW = ScaleGlyph(rect, 5f);
        var ankleH = ScaleGlyph(rect, 7f);
        var ankleX = rect.X + ScaleGlyph(rect, 8f);
        var ankleY = rect.Y + ScaleGlyph(rect, 5f);

        var sole = new Rectangle(rect.X + soleMargin, rect.Bottom - ScaleGlyph(rect, 8f), Math.Max(2, rect.Width - soleMargin * 2), soleH);
        var heel = new Rectangle(heelX, heelY, heelW, heelH);
        var ankle = new Rectangle(ankleX, ankleY, ankleW, ankleH);
        sb.Draw(_pixel, sole, color);
        sb.Draw(_pixel, heel, color);
        sb.Draw(_pixel, ankle, color);
    }

    private void DrawWingIndicatorGlyph(SpriteBatch sb, Rectangle rect, Color color)
    {
        var left = new Vector2(rect.X + ScaleGlyph(rect, 5f), rect.Center.Y + ScaleGlyph(rect, 4f));
        var center = new Vector2(rect.Center.X + ScaleGlyph(rect, 1f), rect.Y + ScaleGlyph(rect, 6f));
        var right = new Vector2(rect.Right - ScaleGlyph(rect, 5f), rect.Center.Y + ScaleGlyph(rect, 5f));
        var lineThickness = ScaleGlyph(rect, 2f);
        DrawLine(sb, left, center, color, lineThickness);
        DrawLine(sb, center, right, color, lineThickness);
        DrawLine(sb, left + new Vector2(0f, ScaleGlyph(rect, 3f)), center + new Vector2(-ScaleGlyph(rect, 1f), ScaleGlyph(rect, 3f)), color, lineThickness);
        DrawLine(sb, center + new Vector2(-ScaleGlyph(rect, 1f), ScaleGlyph(rect, 3f)), right + new Vector2(0f, ScaleGlyph(rect, 3f)), color, lineThickness);
    }

    private void DrawEyeIndicatorGlyph(SpriteBatch sb, Rectangle rect, Color color)
    {
        var left = new Vector2(rect.X + ScaleGlyph(rect, 4f), rect.Center.Y);
        var top = new Vector2(rect.Center.X, rect.Y + ScaleGlyph(rect, 6f));
        var right = new Vector2(rect.Right - ScaleGlyph(rect, 4f), rect.Center.Y);
        var bottom = new Vector2(rect.Center.X, rect.Bottom - ScaleGlyph(rect, 6f));
        var lineThickness = ScaleGlyph(rect, 2f);
        DrawLine(sb, left, top, color, lineThickness);
        DrawLine(sb, top, right, color, lineThickness);
        DrawLine(sb, right, bottom, color, lineThickness);
        DrawLine(sb, bottom, left, color, lineThickness);

        var pupilSize = ScaleGlyph(rect, 4f);
        sb.Draw(_pixel, new Rectangle(rect.Center.X - pupilSize / 2, rect.Center.Y - pupilSize / 2, pupilSize, pupilSize), color);
    }

    private static int ScaleGlyph(Rectangle rect, float baseline)
    {
        var scale = rect.Width / 24f;
        return Math.Max(1, (int)MathF.Round(baseline * scale));
    }

    private void DrawWorldNametags(SpriteBatch sb, GraphicsDevice device, Matrix view, Matrix proj)
    {
        if (_remotePlayers.Count == 0)
            return;

        var mode = NormalizeNametagMode(_nametagMode);
        if (string.Equals(mode, "Off", StringComparison.OrdinalIgnoreCase))
            return;

        var alpha = 1f;
        if (string.Equals(mode, "Fade", StringComparison.OrdinalIgnoreCase))
        {
            if (Keyboard.GetState().IsKeyDown(Keys.Tab))
            {
                alpha = 1f;
            }
            else
            {
                if (_nametagFadeSeconds <= 0.001f || _nametagFadeTimer <= 0f)
                    return;
                alpha = Math.Clamp(_nametagFadeTimer / _nametagFadeSeconds, 0f, 1f);
            }
        }

        if (alpha <= 0.01f)
            return;

        foreach (var pair in _remotePlayers)
        {
            // Skip Veilseer players (hidden from nametags)
            if (ShouldHideRemotePlayerFromLocal(pair.Key))
                continue;
                
            var name = ResolvePlayerName(pair.Key);
            if (string.IsNullOrWhiteSpace(name))
                continue;

            var anchor = pair.Value.Position + new Vector3(0f, pair.Value.ColliderHeight + 0.45f, 0f);
            if (!TryProjectWorldPointToUi(device, anchor, view, proj, out var uiPos, out _))
                continue;

            var textSize = _font.MeasureString(name);
            var rect = new Rectangle(
                (int)MathF.Round(uiPos.X - textSize.X * 0.5f - 6f),
                (int)MathF.Round(uiPos.Y - _font.LineHeight - 14f),
                (int)MathF.Ceiling(textSize.X) + 12,
                _font.LineHeight + 8);

            if (rect.Right < _viewport.Left || rect.Left > _viewport.Right || rect.Bottom < _viewport.Top || rect.Top > _viewport.Bottom)
                continue;

            var bg = new Color(0, 0, 0, Math.Clamp((int)(160f * alpha), 0, 255));
            var border = new Color(208, 228, 255, Math.Clamp((int)(220f * alpha), 0, 255));
            var textColor = new Color(245, 245, 245, Math.Clamp((int)(255f * alpha), 0, 255));
            sb.Draw(_pixel, rect, bg);
            DrawBorder(sb, rect, border);
            _font.DrawString(sb, name, new Vector2(rect.X + 6, rect.Y + 4), textColor);
        }
    }

    private static bool TryProjectWorldPointToUi(GraphicsDevice device, Vector3 worldPoint, Matrix view, Matrix projection, out Vector2 uiPoint, out float depth)
    {
        var projected = device.Viewport.Project(worldPoint, projection, view, Matrix.Identity);
        depth = projected.Z;
        uiPoint = default;

        if (float.IsNaN(projected.X) || float.IsNaN(projected.Y) || float.IsNaN(projected.Z))
            return false;
        if (depth < 0f || depth > 1f)
            return false;

        var scale = UiLayout.Scale <= 0.0001f ? 1f : UiLayout.Scale;
        uiPoint = new Vector2(
            (projected.X - UiLayout.Offset.X) / scale,
            (projected.Y - UiLayout.Offset.Y) / scale);
        return true;
    }

    private void DrawPlayerList(SpriteBatch sb)
    {
        if (_lanSession == null || _playerNames.Count == 0)
            return;
        if (IsAnyTextCaptureActive || _pauseMenuOpen || _inventoryOpen || _homeGuiOpen || _structureFinderOpen)
            return;
        if (!Keyboard.GetState().IsKeyDown(Keys.Tab))
            return;

        var entries = new List<KeyValuePair<int, string>>(_playerNames);
        // Filter out Veilseer players from the player list
        entries.RemoveAll(entry => ShouldHideRemotePlayerFromLocal(entry.Key));
        entries.Sort((a, b) => a.Key.CompareTo(b.Key));
        ProcessPauseInviteAvatarLoads();

        var avatarSize = Math.Max(38, _font.LineHeight + 16);
        var rowH = avatarSize + 12;
        var rowGap = 6;
        var padding = 10;
        var maxRows = Math.Max(1, (_viewport.Height - 64 - (padding * 2) - _font.LineHeight - 8) / (rowH + rowGap));
        var visibleCount = Math.Min(entries.Count, maxRows);
        var hiddenCount = Math.Max(0, entries.Count - visibleCount);
        var title = hiddenCount > 0 ? $"PLAYERS +{hiddenCount}" : "PLAYERS";
        var maxWidth = _font.MeasureString(title).X;

        for (var i = 0; i < visibleCount; i++)
        {
            var label = FormatPlayerLabel(entries[i]);
            var width = avatarSize + 30 + _font.MeasureString(label).X;
            if (width > maxWidth)
                maxWidth = width;
        }

        var minWidth = 330;
        var maxPanelWidth = Math.Max(minWidth, _viewport.Width - 40);
        var widthPixels = Math.Clamp((int)MathF.Ceiling(maxWidth) + padding * 2, minWidth, maxPanelWidth);
        var heightPixels = padding * 2 + _font.LineHeight + 8 + (visibleCount * rowH) + (Math.Max(0, visibleCount - 1) * rowGap);

        var x = _viewport.Right - widthPixels - 20;
        var y = _viewport.Y + 20;
        var rect = new Rectangle(x, y, widthPixels, heightPixels);

        sb.Draw(_pixel, rect, new Color(0, 0, 0, 165));
        DrawBorder(sb, rect, new Color(225, 235, 255, 230));

        var cursor = new Vector2(rect.X + padding, rect.Y + padding);
        _font.DrawString(sb, title, cursor, Color.White);
        cursor.Y += _font.LineHeight + 8;

        for (var i = 0; i < visibleCount; i++)
        {
            var entry = entries[i];
            var rowRect = new Rectangle(rect.X + padding, (int)cursor.Y, rect.Width - (padding * 2), rowH);
            var avatarRect = new Rectangle(rowRect.X + 8, rowRect.Y + (rowRect.Height - avatarSize) / 2, avatarSize, avatarSize);
            var nameRect = new Rectangle(avatarRect.Right + 10, rowRect.Y + 6, Math.Max(40, rowRect.Right - avatarRect.Right - 18), rowRect.Height - 12);
            var label = FormatPlayerLabel(entry);
            var pictureUrl = ResolvePlayerPictureUrl(entry.Key, entry.Value);
            var bannerUrl = ResolvePlayerBannerUrl(entry.Key, entry.Value);
            var avatarKey = ResolvePlayerVisualCacheKey(entry.Key, entry.Value, "avatar");
            var bannerKey = ResolvePlayerVisualCacheKey(entry.Key, entry.Value, "banner");

            sb.Draw(_pixel, rowRect, new Color(18, 24, 34, 218));
            if (TryGetPauseInviteAvatarTexture(bannerKey, bannerUrl, out var bannerTexture))
                sb.Draw(bannerTexture!, nameRect, Color.White * 0.35f);
            else
                sb.Draw(_pixel, nameRect, new Color(36, 48, 70, 150));
            sb.Draw(_pixel, nameRect, new Color(0, 0, 0, 110));

            if (TryGetPauseInviteAvatarTexture(avatarKey, pictureUrl, out var avatarTexture))
                sb.Draw(avatarTexture!, avatarRect, Color.White);
            else
                DrawPauseInviteAvatarFallback(sb, avatarRect, entry.Value);

            DrawBorder(sb, avatarRect, Color.White);
            DrawBorder(sb, nameRect, new Color(185, 205, 235, 150));
            DrawBorder(sb, rowRect, new Color(205, 222, 248, 190));

            var fittedLabel = TrimTextToWidth(label, Math.Max(1, nameRect.Width - 14));
            DrawBoldPixelText(sb, fittedLabel, new Vector2(nameRect.X + 7, nameRect.Y + Math.Max(0, (nameRect.Height - _font.LineHeight) / 2)), Color.White);
            cursor.Y += rowH + rowGap;
        }
    }

    private void DrawSoulMarkerNameLabel(SpriteBatch sb, GraphicsDevice device, Matrix view, Matrix proj, Vector3 markerPosition, string ownerName)
    {
        var name = string.IsNullOrWhiteSpace(ownerName) ? "PLAYER" : ownerName.Trim();
        var anchor = markerPosition + new Vector3(0f, 1.55f, 0f);
        if (!TryProjectWorldPointToUi(device, anchor, view, proj, out var uiPos, out var depth) || depth <= 0f || depth >= 1f)
            return;

        var size = _font.MeasureString(name);
        var rect = new Rectangle(
            (int)MathF.Round(uiPos.X - size.X * 0.5f - 8f),
            (int)MathF.Round(uiPos.Y - _font.LineHeight - 8f),
            (int)MathF.Ceiling(size.X) + 16,
            _font.LineHeight + 8);
        sb.Draw(_pixel, rect, new Color(0, 0, 0, 150));
        DrawBorder(sb, rect, new Color(174, 239, 255, 175));
        _font.DrawString(sb, name, new Vector2(rect.X + 8, rect.Y + 4), new Color(232, 246, 255));
    }

    private string ResolvePlayerPictureUrl(int playerId, string displayName)
    {
        if (_lanSession != null && playerId == _lanSession.LocalPlayerId)
            return (GetLocalProfileVisualCache()?.PictureUrl ?? string.Empty).Trim();

        if (TryResolveCachedFriendVisual(playerId, displayName, out var pictureUrl, out _))
            return pictureUrl;

        return string.Empty;
    }

    private string ResolvePlayerBannerUrl(int playerId, string displayName)
    {
        if (_lanSession != null && playerId == _lanSession.LocalPlayerId)
            return (GetLocalProfileVisualCache()?.BannerUrl ?? string.Empty).Trim();

        if (TryResolveCachedFriendVisual(playerId, displayName, out _, out var bannerUrl))
            return bannerUrl;

        return string.Empty;
    }

    private bool TryResolveCachedFriendVisual(int playerId, string displayName, out string pictureUrl, out string bannerUrl)
    {
        pictureUrl = string.Empty;
        bannerUrl = string.Empty;
        var authorityId = ResolvePlayerAuthorityId(playerId);
        var snapshot = _socialState.GetSnapshot();
        for (var i = 0; i < snapshot.Friends.Count; i++)
        {
            var friend = snapshot.Friends[i];
            if (!string.IsNullOrWhiteSpace(authorityId)
                && string.Equals((friend.ProductUserId ?? string.Empty).Trim(), authorityId, StringComparison.OrdinalIgnoreCase))
            {
                pictureUrl = (friend.PictureUrl ?? string.Empty).Trim();
                bannerUrl = (friend.BannerUrl ?? string.Empty).Trim();
                return true;
            }

            if (!string.IsNullOrWhiteSpace(displayName)
                && (string.Equals((friend.DisplayName ?? string.Empty).Trim(), displayName.Trim(), StringComparison.OrdinalIgnoreCase)
                    || string.Equals((friend.Username ?? string.Empty).Trim(), displayName.Trim(), StringComparison.OrdinalIgnoreCase)))
            {
                pictureUrl = (friend.PictureUrl ?? string.Empty).Trim();
                bannerUrl = (friend.BannerUrl ?? string.Empty).Trim();
                return true;
            }
        }

        for (var i = 0; i < _profile.Friends.Count; i++)
        {
            var friend = _profile.Friends[i];
            if (!string.IsNullOrWhiteSpace(authorityId)
                && string.Equals((friend.UserId ?? string.Empty).Trim(), authorityId, StringComparison.OrdinalIgnoreCase))
            {
                pictureUrl = (friend.PictureUrl ?? string.Empty).Trim();
                bannerUrl = (friend.BannerUrl ?? string.Empty).Trim();
                return true;
            }

            if (!string.IsNullOrWhiteSpace(displayName)
                && (string.Equals((friend.Label ?? string.Empty).Trim(), displayName.Trim(), StringComparison.OrdinalIgnoreCase)
                    || string.Equals((friend.LastKnownDisplayName ?? string.Empty).Trim(), displayName.Trim(), StringComparison.OrdinalIgnoreCase)))
            {
                pictureUrl = (friend.PictureUrl ?? string.Empty).Trim();
                bannerUrl = (friend.BannerUrl ?? string.Empty).Trim();
                return true;
            }
        }

        return false;
    }

    private string ResolvePlayerVisualCacheKey(int playerId, string displayName, string kind)
    {
        var authorityId = ResolvePlayerAuthorityId(playerId);
        if (!string.IsNullOrWhiteSpace(authorityId))
            return $"{kind}:{authorityId.Trim()}";

        if (_lanSession != null && playerId == _lanSession.LocalPlayerId)
        {
            var localPuid = (EosClientProvider.Current?.LocalProductUserId ?? string.Empty).Trim();
            if (!string.IsNullOrWhiteSpace(localPuid))
                return $"{kind}:{localPuid}";

            return $"{kind}:local:{(_profile.PlayerId ?? _profile.GetDisplayUsername()).Trim()}";
        }

        return $"{kind}:player:{playerId}:{(displayName ?? string.Empty).Trim()}";
    }

    private VeilnetProfileCacheStore? GetLocalProfileVisualCache()
    {
        var now = DateTime.UtcNow;
        if ((now - _localProfileVisualCacheLoadedUtc).TotalSeconds < 10)
            return _localProfileVisualCache;

        _localProfileVisualCacheLoadedUtc = now;
        _localProfileVisualCache = VeilnetProfileCacheStore.Load(_log);
        return _localProfileVisualCache;
    }

    private string TrimTextToWidth(string text, int maxWidth)
    {
        text = (text ?? string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(text) || _font.MeasureString(text).X <= maxWidth)
            return text;

        const string suffix = "...";
        var suffixWidth = _font.MeasureString(suffix).X;
        while (text.Length > 0 && _font.MeasureString(text).X + suffixWidth > maxWidth)
            text = text[..^1];

        return text.Length == 0 ? suffix : text + suffix;
    }

    private void DrawBoldPixelText(SpriteBatch sb, string text, Vector2 pos, Color color)
    {
        _font.DrawString(sb, text, pos + new Vector2(1, 0), color);
        _font.DrawString(sb, text, pos + new Vector2(0, 1), color);
        _font.DrawString(sb, text, pos, color);
    }

    private string FormatPlayerLabel(KeyValuePair<int, string> entry)
    {
        var label = entry.Value;
        if (_lanSession != null && entry.Key == _lanSession.LocalPlayerId)
            label = $"{label} (YOU)";
        else if (entry.Key == 0)
            label = $"{label} (HOST)";

        return label;
    }

    private void DrawInventory(SpriteBatch sb)
    {
        if (_soulLootOpen)
        {
            DrawSoulLoot(sb);
            return;
        }

        sb.Begin(samplerState: SamplerState.PointClamp, transformMatrix: UiLayout.Transform);
        if (_pausePanel != null)
            sb.Draw(_pausePanel, _inventoryPanelVisualRect, Color.White);
        else
            sb.Draw(_pixel, _inventoryPanelVisualRect, new Color(8, 12, 22, 220));

        var isLiveView = HasActiveRemoteInventoryView();

        var tabsVisible = _gameMode == GameMode.Artificer && !isLiveView;
        var isArtificerCatalog = tabsVisible && _artificerInventoryView == ArtificerInventoryView.Catalog;

        if (tabsVisible)
        {
            sb.Draw(_pixel, _inventoryCatalogTabRect, isArtificerCatalog ? new Color(42, 66, 98, 235) : new Color(20, 20, 20, 180));
            sb.Draw(_pixel, _inventoryStorageTabRect, isArtificerCatalog ? new Color(20, 20, 20, 180) : new Color(42, 66, 98, 235));
            DrawBorder(sb, _inventoryCatalogTabRect, isArtificerCatalog ? new Color(200, 225, 255) : new Color(120, 120, 120));
            DrawBorder(sb, _inventoryStorageTabRect, isArtificerCatalog ? new Color(120, 120, 120) : new Color(200, 225, 255));
            _font.DrawString(sb, "CATALOG", new Vector2(_inventoryCatalogTabRect.X + 16, _inventoryCatalogTabRect.Y + 6), Color.White);
            _font.DrawString(sb, "INVENTORY", new Vector2(_inventoryStorageTabRect.X + 8, _inventoryStorageTabRect.Y + 6), Color.White);
        }

        var titleY = _inventoryRect.Y + InventoryPadding + (tabsVisible ? InventoryTabHeight + 8 : 6);
        var title = isArtificerCatalog ? "ARTIFICER CATALOG" : "INVENTORY";
        if (isLiveView)
        {
            var targetName = ResolvePlayerName(_currentLiveInventoryTarget);
            title = $"{targetName}'S INVENTORY";
            // Hide tabs and clear button when viewing live inventory
            tabsVisible = false;
            isArtificerCatalog = false;
        }
        
        _font.DrawString(sb, title, new Vector2(_inventoryRect.X + InventoryPadding + 2, titleY), Color.White);
        if (isArtificerCatalog)
        {
            var shownText = $"Showing {_inventory.GetSandboxCatalogFilteredCount()} of {_inventory.GetSandboxCatalogTotalCount()}";
            var shownSize = _font.MeasureString(shownText);
            _font.DrawString(sb, shownText, new Vector2(_inventoryRect.Right - shownSize.X - 20, titleY), new Color(205, 220, 255));
            DrawInventoryCatalogPanel(sb);
        }
        else
        {
            // Draw live inventory data if available, otherwise draw local inventory
            if (isLiveView)
            {
                DrawLiveInventorySlots(sb, TryGetActiveRemoteInventoryView(out var liveView) ? liveView : null);
            }
            else
            {
                DrawInventorySlots(sb, _inventory.Grid, _inventoryGridSlots);
            }
        }

        // Only show clear button when not viewing live inventory
        if (!isLiveView && _inventoryClear.Visible)
            _inventoryClear.Draw(sb, _pixel, _font);
        _inventoryClose.Draw(sb, _pixel, _font);

        if (_inventoryHasHeld && _atlas != null)
        {
            var size = _inventoryGridSlots.Length > 0 ? _inventoryGridSlots[0].Width : 40;
            var scale = 1.15f;
            var scaled = (int)MathF.Round(size * scale);
            var dst = new Rectangle(_inventoryMousePos.X - scaled / 2, _inventoryMousePos.Y - scaled / 2, scaled, scaled);
            var icon = GetBlockIcon(_inventoryHeld.Id, dst.Width);
            if (icon != null)
                sb.Draw(icon, dst, Color.White);
            else
                sb.Draw(_atlas.Texture, dst, _atlas.GetFaceSourceRect((byte)_inventoryHeld.Id, FaceDirection.PosY), Color.White);

            DrawHeldItemCount(sb, dst, _inventoryHeld.Count);
        }

        sb.End();
    }

    private void DrawSoulLoot(SpriteBatch sb)
    {
        if (_soulLootRect.Width <= 0 || _soulLootRect.Height <= 0)
            UpdateSoulLootLayout();

        sb.Begin(samplerState: SamplerState.PointClamp, transformMatrix: UiLayout.Transform);
        if (_pausePanel != null)
            sb.Draw(_pausePanel, _soulLootPanelVisualRect, Color.White);
        else
            sb.Draw(_pixel, _soulLootPanelVisualRect, new Color(8, 12, 22, 220));

        var title = string.IsNullOrWhiteSpace(_soulLootTitleText) ? GetViewedSoulDisplayTitle() : _soulLootTitleText;
        var titleSize = _font.MeasureString(title);
        var titleY = _soulLootRect.Y + InventoryPadding + 8;
        _font.DrawString(
            sb,
            title,
            new Vector2(_soulLootRect.Center.X - titleSize.X * 0.5f, titleY),
            new Color(232, 246, 255));

        var soulLabelY = titleY + _font.LineHeight + 8;
        _font.DrawString(sb, "SOUL INVENTORY", new Vector2(_soulLootRect.X + InventoryPadding, soulLabelY), new Color(190, 220, 245));
        var viewedSoulInventory = GetViewedSoulInventory();
        DrawInventorySlots(sb, viewedSoulInventory, _soulLootSoulHotbarSlots, soulOffset: 0);
        DrawInventorySlots(sb, viewedSoulInventory, _soulLootSoulGridSlots, soulOffset: Inventory.HotbarSize);

        var playerLabelY = _soulLootPlayerGridSlots[0].Y - _font.LineHeight - 6;
        _font.DrawString(sb, "YOUR INVENTORY", new Vector2(_soulLootRect.X + InventoryPadding, playerLabelY), new Color(190, 220, 245));
        DrawInventorySlots(sb, _inventory.Grid, _soulLootPlayerGridSlots);

        if (!string.IsNullOrWhiteSpace(_soulLootStatusText))
        {
            var statusSize = _font.MeasureString(_soulLootStatusText);
            _font.DrawString(
                sb,
                _soulLootStatusText,
                new Vector2(_soulLootRect.Center.X - statusSize.X * 0.5f, _soulLootClear.Bounds.Y - _font.LineHeight - 8),
                new Color(255, 220, 180));
        }
        else
        {
            const string hotbarHint = "Use the bottom hotbar to place active slots.";
            var hintSize = _font.MeasureString(hotbarHint);
            _font.DrawString(
                sb,
                hotbarHint,
                new Vector2(_soulLootRect.Center.X - hintSize.X * 0.5f, _soulLootClear.Bounds.Y - _font.LineHeight - 8),
                new Color(190, 220, 245));
        }

        _soulLootClear.Draw(sb, _pixel, _font);
        _soulLootTakeAll.Draw(sb, _pixel, _font);
        _soulLootClose.Draw(sb, _pixel, _font);

        if (_inventoryHasHeld && _atlas != null)
        {
            var size = _soulLootPlayerGridSlots.Length > 0 ? _soulLootPlayerGridSlots[0].Width : 40;
            var scaled = (int)MathF.Round(size * 1.15f);
            var dst = new Rectangle(_inventoryMousePos.X - scaled / 2, _inventoryMousePos.Y - scaled / 2, scaled, scaled);
            var icon = GetBlockIcon(_inventoryHeld.Id, dst.Width);
            if (icon != null)
                sb.Draw(icon, dst, Color.White);
            else
                sb.Draw(_atlas.Texture, dst, _atlas.GetFaceSourceRect((byte)_inventoryHeld.Id, FaceDirection.PosY), Color.White);

            DrawHeldItemCount(sb, dst, _inventoryHeld.Count);
        }

        sb.End();
    }

    private void DrawInventorySlots(SpriteBatch sb, HotbarSlot[] slots, Rectangle[] rects, int soulOffset = 0)
    {
        for (int i = 0; i < rects.Length; i++)
        {
            var rect = rects[i];
            sb.Draw(_pixel, rect, new Color(20, 20, 20, 200));
            if (rect.Contains(_inventoryMousePos))
                sb.Draw(_pixel, rect, new Color(150, 150, 150, 70));
            DrawBorder(sb, rect, Color.White);

            var slotIndex = i + soulOffset;
            if (slotIndex < 0 || slotIndex >= slots.Length)
                continue;

            var slot = slots[slotIndex];
            if (slot.Count > 0 && slot.Id != BlockId.Air && _atlas != null)
            {
                var pad = 6;
                var dst = new Rectangle(rect.X + pad, rect.Y + pad, rect.Width - pad * 2, rect.Height - pad * 2);
                var icon = GetBlockIcon(slot.Id, dst.Width);
                if (icon != null)
                    sb.Draw(icon, dst, Color.White);
                else
                    sb.Draw(_atlas.Texture, dst, _atlas.GetFaceSourceRect((byte)slot.Id, FaceDirection.PosY), Color.White);
            }

            if (slot.Count > 1)
            {
                var text = slot.Count.ToString();
                var size = _font.MeasureString(text);
                var pos = new Vector2(rect.Right - size.X - 4, rect.Bottom - size.Y - 2);
                _font.DrawString(sb, text, pos, Color.White);
            }
        }
    }

    private void DrawLiveInventorySlots(SpriteBatch sb, LanInventoryView? liveView)
    {
        var gridIds = liveView?.GridIds ?? Array.Empty<byte>();
        var gridCounts = liveView?.GridCounts ?? Array.Empty<byte>();

        for (int i = 0; i < _inventoryGridSlots.Length; i++)
        {
            var rect = _inventoryGridSlots[i];
            sb.Draw(_pixel, rect, new Color(20, 20, 20, 200));
            DrawBorder(sb, rect, Color.White);

            var blockId = i < gridIds.Length ? (BlockId)gridIds[i] : BlockId.Air;
            var count = i < gridCounts.Length ? gridCounts[i] : 0;
            
            if (count > 0 && blockId != BlockId.Air && _atlas != null)
            {
                var pad = 6;
                var dst = new Rectangle(rect.X + pad, rect.Y + pad, rect.Width - pad * 2, rect.Height - pad * 2);
                var icon = GetBlockIcon(blockId, dst.Width);
                if (icon != null)
                    sb.Draw(icon, dst, Color.White);
                else
                    sb.Draw(_atlas.Texture, dst, _atlas.GetFaceSourceRect((byte)blockId, FaceDirection.PosY), Color.White);
            }

            if (count > 1)
            {
                var text = count.ToString();
                var size = _font.MeasureString(text);
                var pos = new Vector2(rect.Right - size.X - 4, rect.Bottom - size.Y - 2);
                _font.DrawString(sb, text, pos, Color.White);
            }
        }

        if (liveView == null)
        {
            const string waitingText = "WAITING FOR LIVE INVENTORY...";
            var waitingSize = _font.MeasureString(waitingText);
            var waitingPos = new Vector2(
                _inventoryRect.Center.X - waitingSize.X * 0.5f,
                _inventoryGridSlots.Length > 0
                    ? _inventoryGridSlots[0].Y - _font.LineHeight - 10
                    : _inventoryRect.Center.Y - waitingSize.Y * 0.5f);
            _font.DrawString(sb, waitingText, waitingPos, new Color(210, 220, 235));
        }
    }

    private void DrawHeldItemCount(SpriteBatch sb, Rectangle iconRect, int count)
    {
        if (count <= 0)
            return;

        var text = count.ToString();
        var textSize = _font.MeasureString(text);
        var badgePadX = 6;
        var badgePadY = 3;
        var badgeRect = new Rectangle(
            iconRect.Right - (int)MathF.Ceiling(textSize.X) - badgePadX * 2,
            iconRect.Y - (int)MathF.Ceiling(textSize.Y) - badgePadY - 4,
            (int)MathF.Ceiling(textSize.X) + badgePadX * 2,
            (int)MathF.Ceiling(textSize.Y) + badgePadY * 2);
        sb.Draw(_pixel, badgeRect, new Color(10, 14, 24, 220));
        DrawBorder(sb, badgeRect, new Color(230, 236, 248, 210));
        var pos = new Vector2(
            badgeRect.X + badgePadX,
            badgeRect.Y + badgePadY - 1);
        _font.DrawString(sb, text, pos, Color.White);
    }

    private void DrawBorder(SpriteBatch sb, Rectangle rect, Color color)
    {
        sb.Draw(_pixel, new Rectangle(rect.X, rect.Y, rect.Width, 2), color);
        sb.Draw(_pixel, new Rectangle(rect.X, rect.Bottom - 2, rect.Width, 2), color);
        sb.Draw(_pixel, new Rectangle(rect.X, rect.Y, 2, rect.Height), color);
        sb.Draw(_pixel, new Rectangle(rect.Right - 2, rect.Y, 2, rect.Height), color);
    }

    private void DrawDevOverlay(SpriteBatch sb)
    {
        var pos = _player.Position;
        var vel = _player.Velocity;
        var leftLines = new List<string>
        {
            $"FPS: {_fps:0}",
            $"WORLD: {(_meta?.Name ?? "WORLD")}",
            $"MODE: {_gameMode.ToString().ToUpperInvariant()}",
            $"POS: {pos.X:0.00}, {pos.Y:0.00}, {pos.Z:0.00}",
            $"VEL: {vel.X:0.00}, {vel.Y:0.00}, {vel.Z:0.00}",
            $"CHUNK: {_playerChunkCoord}",
            $"STATE: FLY {_player.IsFlying} | GROUND {_player.IsGrounded}",
            $"VITALS: HP {_survivalVitals.Health}/{SurvivalVitals.MaxHealth} | HUNGER {_survivalVitals.Hunger}/{SurvivalVitals.MaxHunger}",
            $"SIGIL: ATONEMENT {MathF.Round(_sigilPositiveTargetFraction * 100f):0}% | CURSE {MathF.Round(_sigilNegativeTargetFraction * 100f):0}%",
            $"HELD: {BlockRegistry.Get(_inventory.SelectedId).Name} ({_inventory.SelectedId})"
        };

        var rightLines = new List<string>
        {
            $"TIME: {_timeOfDayTicks} | WEATHER: {_weatherState.ToUpperInvariant()}",
            $"RULES: COLLISION {(_playerCollisionEnabled ? "ON" : "OFF")} | SIGIL {(_sigilPowerEnabled ? "ON" : "OFF")}",
            $"CYCLES: TIME {(_timeCycleEnabled ? "ON" : "OFF")} | WEATHER {(_weatherCycleEnabled ? "ON" : "OFF")}",
            $"DIFFICULTY: {GetDifficultyDisplayLabel(_difficultyLevel).ToUpperInvariant()}",
            $"UI: PAUSE {_pauseMenuOpen} | INV {_inventoryOpen} | CHAT {_chatInputActive} | CMD {_commandInputActive}",
            $"STREAMING: {_activeRadiusChunks}/{_targetActiveRadiusChunks} CHUNKS"
        };

        if (_world != null)
        {
            var wx = (int)MathF.Floor(pos.X);
            var wz = (int)MathF.Floor(pos.Z);
            var biomeName = _world.GetBiomeNameAt(wx, wz);
            var desertWeight = _world.GetDesertWeightAt(wx, wz);
            leftLines.Add($"BIOME: {biomeName} ({desertWeight:0.00}) @ {wx},{wz}");

            var origin = _player.Position + _player.HeadOffset;
            if (VoxelRaycast.Raycast(origin, _player.Forward, InteractRange, _world.GetBlock, out var hit))
            {
                var id = _world.GetBlock(hit.X, hit.Y, hit.Z);
                var def = BlockRegistry.Get(id);
                leftLines.Add($"LOOKING: {def.Name} ({id}) @ {hit.X},{hit.Y},{hit.Z}");
            }
        }

        if (_streamingService != null && _world != null)
        {
            var (loadQueue, meshQueue, saveQueue) = _streamingService.GetQueueSizes();
            rightLines.Add($"LOADED CHUNKS: {_world.ChunkCount}");
            rightLines.Add($"QUEUES: LOAD {loadQueue} | MESH {meshQueue} | SAVE {saveQueue}");
            rightLines.Add($"PREWARM: {(_spawnPrewarmComplete ? "DONE" : $"{_prewarmReadyCount}/{_prewarmTargetCount}")}");
        }

        var metrics = AdvancedPerformanceOptimizer.GetCurrentMetrics();
        var (ramUsed, _, vramUsed, _) = SimpleMemoryManager.GetMemoryStats();
        rightLines.Add($"PERF: CPU {metrics.CpuUsage:F1}% | RAM {ramUsed / 1024 / 1024}MB | VRAM {vramUsed / 1024 / 1024}MB");

        var padding = 20;
        var gap = 24;
        var lineHeight = _font.LineHeight + 2;
        var panelWidth = Math.Clamp((_viewport.Width - padding * 2 - gap) / 2, 220, 460);
        var textWidth = Math.Max(120, panelWidth - 20);
        var wrappedLeftLines = new List<string>();
        var wrappedRightLines = new List<string>();

        foreach (var line in leftLines)
            wrappedLeftLines.AddRange(WrapOverlayText(line, textWidth));
        foreach (var line in rightLines)
            wrappedRightLines.AddRange(WrapOverlayText(line, textWidth));

        var leftRect = new Rectangle(_viewport.X + padding, _viewport.Y + padding, panelWidth, 22 + wrappedLeftLines.Count * lineHeight);
        var rightRect = new Rectangle(_viewport.Right - padding - panelWidth, _viewport.Y + padding, panelWidth, 22 + wrappedRightLines.Count * lineHeight);

        sb.Draw(_pixel, leftRect, new Color(0, 0, 0, 124));
        sb.Draw(_pixel, rightRect, new Color(0, 0, 0, 124));
        DrawBorder(sb, leftRect, new Color(220, 220, 220, 220));
        DrawBorder(sb, rightRect, new Color(220, 220, 220, 220));

        _font.DrawString(sb, "WORLD / PLAYER", new Vector2(leftRect.X + 10, leftRect.Y + 8), Color.White);
        _font.DrawString(sb, "RENDER / SYSTEMS", new Vector2(rightRect.X + 10, rightRect.Y + 8), Color.White);

        for (int i = 0; i < wrappedLeftLines.Count; i++)
            _font.DrawString(sb, wrappedLeftLines[i], new Vector2(leftRect.X + 10, leftRect.Y + 8 + (i + 1) * lineHeight), Color.White);
        for (int i = 0; i < wrappedRightLines.Count; i++)
            _font.DrawString(sb, wrappedRightLines[i], new Vector2(rightRect.X + 10, rightRect.Y + 8 + (i + 1) * lineHeight), Color.White);
    }

