    private void DrawFaceOverlay(SpriteBatch sb)
    {
        if (!_debugFaceOverlay)
            return;

        var hitFaceText = "HIT FACE: NONE";
        if (_world != null)
        {
            var origin = _player.Position + _player.HeadOffset;
