    private void OpenHomeGui()
    {
        _homeGuiOpen = true;
        _homeGuiRenameFocused = false;
        _homeGuiCreateNameFocused = false;
        _homeGuiIconSearchFocused = false;
        _homeGuiCreatePopupOpen = false;
        _homeGuiDeleteConfirmOpen = false;
        _homeGuiHelpPopupOpen = false;
        _homeGuiIconPickerOpen = false;
        _homeGuiPendingDeleteIndex = -1;
        _homeGuiListScroll = 0f;
        _homeGuiIconScroll = 0f;
        if (_selectedHomeIndex < 0 && _homes.Count > 0)
            _selectedHomeIndex = 0;
        BuildHomeGuiIconCatalog();
        SyncHomeGuiSelectionFields();
        ResetHomeGuiCreateState();
        LayoutHomeGui();
    }

