    private void UpdateHomeGui(InputState input, float dt)
    {
        LayoutHomeGui();
        if (_homeGuiStatusTimer > 0f)
        {
            _homeGuiStatusTimer = Math.Max(0f, _homeGuiStatusTimer - dt);
            if (_homeGuiStatusTimer <= 0f)
                _homeGuiStatus = string.Empty;
        }

        if (input.IsNewKeyPress(Keys.Escape))
        {
            if (_homeGuiHelpPopupOpen)
            {
                _homeGuiHelpPopupOpen = false;
                return;
            }

            if (_homeGuiIconPickerOpen)
            {
                _homeGuiIconPickerOpen = false;
                _homeGuiIconSearchFocused = false;
                return;
            }

            if (_homeGuiDeleteConfirmOpen)
            {
                _homeGuiDeleteConfirmOpen = false;
                _homeGuiPendingDeleteIndex = -1;
                return;
            }

            if (_homeGuiCreatePopupOpen)
            {
                _homeGuiCreatePopupOpen = false;
                _homeGuiCreateNameFocused = false;
                return;
            }

            if (_homeGuiRenameFocused)
            {
                _homeGuiRenameFocused = false;
                return;
            }

            _homeGuiOpen = false;
            return;
        }

        if (IsNewActionPress(input, "HomeGui", Keys.H) && !_homeGuiRenameFocused && !_homeGuiCreateNameFocused && !_homeGuiIconSearchFocused && !_homeGuiCreatePopupOpen && !_homeGuiDeleteConfirmOpen && !_homeGuiIconPickerOpen && !_homeGuiHelpPopupOpen)
        {
            _homeGuiOpen = false;
            return;
        }

        var maxListScroll = Math.Max(0f, _homes.Count * HomeGuiRowHeight - _homeGuiListRect.Height);
        if (_homeGuiListRect.Contains(input.MousePosition) && input.ScrollDelta != 0 && !_homeGuiIconPickerOpen)
        {
            var delta = input.ScrollDelta > 0 ? -HomeGuiRowHeight : HomeGuiRowHeight;
            _homeGuiListScroll = Math.Clamp(_homeGuiListScroll + delta, 0f, maxListScroll);
        }

        if (_homeGuiIconPickerOpen && _homeGuiIconGridRect.Contains(input.MousePosition) && input.ScrollDelta != 0)
        {
            var maxIconScroll = GetMaxHomeGuiIconScroll();
            var delta = input.ScrollDelta > 0 ? -HomeGuiIconCellSize : HomeGuiIconCellSize;
            _homeGuiIconScroll = Math.Clamp(_homeGuiIconScroll + delta, 0f, maxIconScroll);
            BuildHomeGuiIconCellRects();
        }

        if (input.IsNewLeftClick())
        {
            if (_homeGuiIconPickerOpen)
            {
                HandleHomeGuiIconPickerClick(input.MousePosition);
                return;
            }

            if (_homeGuiHelpPopupOpen)
            {
                if (_homeGuiHelpCloseButtonRect.Contains(input.MousePosition))
                    _homeGuiHelpPopupOpen = false;
                return;
            }

            if (_homeGuiDeleteConfirmOpen)
            {
                if (_homeGuiDeleteConfirmButtonRect.Contains(input.MousePosition))
                    ConfirmDeleteSelectedHomeFromGui();
                else if (_homeGuiDeleteCancelButtonRect.Contains(input.MousePosition))
                {
                    _homeGuiDeleteConfirmOpen = false;
                    _homeGuiPendingDeleteIndex = -1;
                }
                return;
            }

            if (_homeGuiCreatePopupOpen)
            {
                HandleHomeGuiCreatePopupClick(input.MousePosition);
                return;
            }

            HandleHomeGuiMainClick(input.MousePosition);
        }

        if (_homeGuiIconSearchFocused)
        {
            ApplyHomeGuiTextInput(input, ref _homeGuiIconSearchText, HomeGuiMaxSearchLength, ref _homeGuiIconSearchSelectAll);
            RefreshHomeGuiFilteredIcons();
        }
        else if (_homeGuiCreateNameFocused)
        {
            ApplyHomeGuiTextInput(input, ref _homeGuiCreateNameInput, HomeGuiMaxNameLength, ref _homeGuiCreateNameSelectAll);
        }
        else if (_homeGuiRenameFocused)
        {
            ApplyHomeGuiTextInput(input, ref _homeGuiRenameInput, HomeGuiMaxNameLength, ref _homeGuiRenameSelectAll);
        }

        if (input.IsNewKeyPress(Keys.Enter))
        {
            if (_homeGuiIconPickerOpen)
            {
                _homeGuiIconPickerOpen = false;
                _homeGuiIconSearchFocused = false;
            }
            else if (_homeGuiDeleteConfirmOpen)
            {
                ConfirmDeleteSelectedHomeFromGui();
            }
            else if (_homeGuiHelpPopupOpen)
            {
                _homeGuiHelpPopupOpen = false;
            }
            else if (_homeGuiCreatePopupOpen)
            {
                ConfirmCreateHomeFromGui();
            }
            else if (_homeGuiRenameFocused)
            {
                RenameSelectedHomeFromGui();
            }
        }
    }

    private void DrawHomeGui(SpriteBatch sb)
    {
        sb.Draw(_pixel, _viewport, new Color(0, 0, 0, 110));
        sb.Draw(_pixel, _homeGuiPanelRect, new Color(18, 22, 28, 236));
        DrawBorder(sb, _homeGuiPanelRect, new Color(205, 216, 230));
        sb.Draw(_pixel, _homeGuiHeaderRect, new Color(12, 15, 20, 225));
        DrawBorder(sb, _homeGuiHeaderRect, new Color(120, 135, 150));
        _font.DrawString(sb, "HOME MANAGER", new Vector2(_homeGuiHeaderRect.X + 14, _homeGuiHeaderRect.Y + 9), Color.White);

        var limitText = $"Homes: {_homes.Count}/{GetMaxHomesForWorld()}";
        var limitColor = _homes.Count >= GetMaxHomesForWorld() ? new Color(235, 194, 130) : new Color(182, 214, 238);
        _font.DrawString(sb, limitText, new Vector2(_homeGuiHeaderRect.X + 14, _homeGuiHeaderRect.Y + 9 + _font.LineHeight), limitColor);
        DrawHomeGuiButton(sb, _homeGuiHelpButtonRect, "?", canClick: true, active: _homeGuiHelpPopupOpen);
        DrawHomeGuiButton(sb, _homeGuiCreateButtonRect, "CREATE", canClick: true, active: _homeGuiCreatePopupOpen);
        DrawHomeGuiButton(sb, _homeGuiCloseButtonRect, "X", canClick: true, destructive: true);

        sb.Draw(_pixel, _homeGuiListRect, new Color(10, 12, 18, 208));
        DrawBorder(sb, _homeGuiListRect, new Color(120, 135, 150));
        _font.DrawString(sb, "HOMES", new Vector2(_homeGuiListRect.X + 10, _homeGuiListRect.Y - _font.LineHeight - 4), new Color(188, 214, 236));
        _homeGuiRowRects.Clear();
        _homeGuiRowDeleteRects.Clear();

        var start = (int)(_homeGuiListScroll / HomeGuiRowHeight);
        var yOffset = (int)(_homeGuiListScroll % HomeGuiRowHeight);
        var visibleRows = Math.Max(1, _homeGuiListRect.Height / HomeGuiRowHeight + 2);
        for (int i = 0; i < visibleRows; i++)
        {
            var idx = start + i;
            if (idx < 0 || idx >= _homes.Count)
                continue;

            var rowY = _homeGuiListRect.Y + i * HomeGuiRowHeight - yOffset;
            var rowRect = new Rectangle(_homeGuiListRect.X + 4, rowY, _homeGuiListRect.Width - 8, HomeGuiRowHeight - 4);
            if (rowRect.Bottom < _homeGuiListRect.Y || rowRect.Y > _homeGuiListRect.Bottom)
                continue;

            var selected = idx == _selectedHomeIndex;
            var accent = selected ? LightenHomeColor(_homes[idx].AccentColor, 28) : _homes[idx].AccentColor;
            sb.Draw(_pixel, rowRect, selected ? new Color(34, 54, 74, 232) : new Color(20, 22, 28, 198));
            DrawBorder(sb, rowRect, selected ? accent : new Color(88, 98, 112));
            _homeGuiRowRects.Add(rowRect);

            var iconRect = new Rectangle(rowRect.X + 8, rowRect.Y + 8, 38, 38);
            DrawHomeIcon(sb, _homes[idx], iconRect);

            var deleteRect = new Rectangle(rowRect.Right - 28, rowRect.Y + 10, 18, 18);
            _homeGuiRowDeleteRects.Add(deleteRect);
            sb.Draw(_pixel, deleteRect, new Color(96, 34, 34, 230));
            DrawBorder(sb, deleteRect, new Color(220, 182, 182));
            _font.DrawString(sb, "X", new Vector2(deleteRect.X + 4, deleteRect.Y + 2), Color.White);

            var home = _homes[idx];
            var coords = $"{(int)home.Position.X}, {(int)home.Position.Y}, {(int)home.Position.Z}";
            var nameText = IsFavoriteHomeIndex(idx) ? "* " + home.Name : home.Name;
            var nameColor = IsFavoriteHomeIndex(idx) ? new Color(255, 234, 164) : Color.White;
            _font.DrawString(sb, nameText, new Vector2(iconRect.Right + 10, rowRect.Y + 7), nameColor);
            _font.DrawString(sb, coords, new Vector2(iconRect.Right + 10, rowRect.Y + 7 + _font.LineHeight), new Color(180, 196, 214));
        }

        sb.Draw(_pixel, _homeGuiDetailRect, new Color(12, 14, 20, 208));
        DrawBorder(sb, _homeGuiDetailRect, new Color(120, 135, 150));
        if (_selectedHomeIndex >= 0 && _selectedHomeIndex < _homes.Count)
        {
            var selectedHome = _homes[_selectedHomeIndex];
            _font.DrawString(sb, "DETAILS", new Vector2(_homeGuiDetailRect.X + 18, _homeGuiDetailRect.Y + 14), new Color(188, 214, 236));
            DrawHomeGuiInput(sb, _homeGuiRenameInputRect, _homeGuiRenameInput, _homeGuiRenameFocused, _homeGuiRenameSelectAll, "(home name)");
            DrawHomeGuiButton(sb, _homeGuiRenameButtonRect, "RENAME", canClick: true);
            DrawHomeIcon(sb, selectedHome, _homeGuiDetailIconButtonRect);
            DrawBorder(sb, _homeGuiDetailIconButtonRect, selectedHome.AccentColor);
            _font.DrawString(sb, "ICON", new Vector2(_homeGuiDetailIconButtonRect.X, _homeGuiDetailIconButtonRect.Y - _font.LineHeight - 4), new Color(188, 214, 236));
            _font.DrawString(sb, selectedHome.HasIconBlock ? selectedHome.IconBlock.ToString() : "Letter badge", new Vector2(_homeGuiDetailIconButtonRect.X, _homeGuiDetailIconButtonRect.Bottom + 8), new Color(180, 196, 214));

            sb.Draw(_pixel, _homeGuiDetailColorPreviewRect, selectedHome.AccentColor);
            DrawBorder(sb, _homeGuiDetailColorPreviewRect, LightenHomeColor(selectedHome.AccentColor, 42));
            _font.DrawString(sb, "COLOR", new Vector2(_homeGuiDetailColorPreviewRect.X, _homeGuiDetailColorPreviewRect.Y - _font.LineHeight - 4), new Color(188, 214, 236));
            DrawHomeGuiColorPalette(sb, _homeGuiColorRects, selectedHome.AccentColor);

            _font.DrawString(sb, $"Location: {(int)selectedHome.Position.X}, {(int)selectedHome.Position.Y}, {(int)selectedHome.Position.Z}", new Vector2(_homeGuiDetailRect.X + 18, _homeGuiDetailIconButtonRect.Bottom + 60), new Color(214, 220, 228));
            var favoriteText = IsFavoriteHomeIndex(_selectedHomeIndex)
                ? "Favorite home: crouch + Home key teleports here."
                : "Mark a favorite for crouch + Home key teleport.";
            _font.DrawString(sb, favoriteText, new Vector2(_homeGuiDetailRect.X + 18, _homeGuiDetailIconButtonRect.Bottom + 60 + _font.LineHeight + 8), new Color(228, 214, 164));
            var cheatText = CanUseCheatCommands() ? "Teleport available in this world." : "Teleport is hidden until cheats are enabled.";
            _font.DrawString(sb, cheatText, new Vector2(_homeGuiDetailRect.X + 18, _homeGuiTeleportButtonRect.Y - _font.LineHeight - 8), CanUseCheatCommands() ? new Color(178, 220, 188) : new Color(208, 176, 132));
            if (CanUseCheatCommands())
                DrawHomeGuiButton(sb, _homeGuiTeleportButtonRect, "TELEPORT", canClick: true);
            DrawHomeGuiButton(sb, _homeGuiSetHereButtonRect, "SET HERE", canClick: true);
            DrawHomeGuiButton(sb, _homeGuiFavoriteButtonRect, IsFavoriteHomeIndex(_selectedHomeIndex) ? "UNFAVORITE" : "FAVORITE", canClick: true, active: IsFavoriteHomeIndex(_selectedHomeIndex));
            DrawHomeGuiButton(sb, _homeGuiDeleteButtonRect, "DELETE", canClick: true, destructive: true);
        }
        else
        {
            _font.DrawString(sb, "No home selected.", new Vector2(_homeGuiDetailRect.X + 18, _homeGuiDetailRect.Y + 18), new Color(196, 204, 214));
            _font.DrawString(sb, "Create a home to store a named return point.", new Vector2(_homeGuiDetailRect.X + 18, _homeGuiDetailRect.Y + 18 + _font.LineHeight + 4), new Color(172, 184, 196));
        }

        if (!string.IsNullOrWhiteSpace(_homeGuiStatus))
            _font.DrawString(sb, _homeGuiStatus, new Vector2(_homeGuiFooterRect.X, _homeGuiFooterRect.Y + 6), new Color(235, 235, 180));

        if (_homeGuiCreatePopupOpen)
            DrawHomeGuiCreatePopup(sb);
        if (_homeGuiIconPickerOpen)
            DrawHomeGuiIconPicker(sb);
        if (_homeGuiDeleteConfirmOpen)
            DrawHomeGuiDeletePopup(sb);
        if (_homeGuiHelpPopupOpen)
            DrawHomeGuiHelpPopup(sb);
    }

    private void DrawHomeIcon(SpriteBatch sb, PlayerHomeEntry home, Rectangle iconRect)
    {
        sb.Draw(_pixel, iconRect, home.AccentColor);
        DrawBorder(sb, iconRect, LightenHomeColor(home.AccentColor, 40));

        if (home.HasIconBlock)
        {
            var iconTexture = GetBlockIcon(home.IconBlock, iconRect.Width - 4);
            if (iconTexture != null)
            {
                sb.Draw(iconTexture, new Rectangle(iconRect.X + 2, iconRect.Y + 2, iconRect.Width - 4, iconRect.Height - 4), Color.White);
                return;
            }
        }

        var fallback = home.Name.Length > 0 ? char.ToUpperInvariant(home.Name[0]).ToString() : "?";
        var fallbackSize = _font.MeasureString(fallback);
        var fallbackPos = new Vector2(iconRect.Center.X - fallbackSize.X / 2f, iconRect.Center.Y - fallbackSize.Y / 2f);
        _font.DrawString(sb, fallback, fallbackPos, Color.White);
    }

    private bool TryGetHomeRowAtPoint(Point point, out int index, out Rectangle rowRect)
    {
        index = -1;
        rowRect = Rectangle.Empty;
        if (!_homeGuiListRect.Contains(point))
            return false;

        var localY = point.Y - _homeGuiListRect.Y + (int)MathF.Round(_homeGuiListScroll);
        index = localY / HomeGuiRowHeight;
        if (index < 0 || index >= _homes.Count)
        {
            index = -1;
            return false;
        }

        var rowTop = _homeGuiListRect.Y + (index * HomeGuiRowHeight) - (int)MathF.Round(_homeGuiListScroll);
        rowRect = new Rectangle(_homeGuiListRect.X + 4, rowTop, _homeGuiListRect.Width - 8, HomeGuiRowHeight - 4);
        return true;
    }

    private void SetHomeAtCurrentPositionFromGui()
    {
        BeginCreateHomePopup();
    }

    private void RenameSelectedHomeFromGui()
    {
        if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
        {
            SetHomeGuiStatus("Select a home first.");
            return;
        }

        var newName = NormalizeHomeName(_homeGuiRenameInput);
        if (TryFindHomeIndex(newName, out var collision) && collision != _selectedHomeIndex)
        {
            SetHomeGuiStatus($"Home name already exists: {newName}");
            return;
        }

        var oldName = _homes[_selectedHomeIndex].Name;
        var renamed = _homes[_selectedHomeIndex];
        renamed.Name = newName;
        _homes[_selectedHomeIndex] = renamed;
        if (string.Equals(_favoriteHomeName, oldName, StringComparison.OrdinalIgnoreCase))
            _favoriteHomeName = newName;
        _homeGuiRenameFocused = false;
        SavePlayerState();
        SetHomeGuiStatus($"Renamed '{oldName}' to '{newName}'.");
    }

    private void DeleteSelectedHomeFromGui()
    {
        if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
        {
            SetHomeGuiStatus("Select a home first.");
            return;
        }

        _homeGuiDeleteConfirmOpen = true;
        _homeGuiPendingDeleteIndex = _selectedHomeIndex;
    }

    private void SetHomeGuiStatus(string message)
    {
        _homeGuiStatus = message;
        _homeGuiStatusTimer = 4f;
    }

    private void BeginCreateHomePopup()
    {
        var maxHomes = GetMaxHomesForWorld();
        if (_homes.Count >= maxHomes)
        {
            _homeGuiCreatePopupOpen = false;
            _homeGuiCreateNameFocused = false;
            SetHomeGuiStatus($"Home limit reached ({maxHomes}). Delete one first.");
            return;
        }

        ResetHomeGuiCreateState();
        _homeGuiCreatePopupOpen = true;
        _homeGuiCreateNameFocused = true;
    }

    private void ResetHomeGuiCreateState()
    {
        _homeGuiCreateNameInput = IsMultipleHomesEnabled() ? GetNextAutomaticHomeName() : DefaultHomeName;
        _homeGuiCreateColor = DefaultHomeAccentColor;
        _homeGuiCreateHasIconBlock = false;
        _homeGuiCreateIconBlock = BlockId.Air;
    }

    private void SyncHomeGuiSelectionFields()
    {
        if (_selectedHomeIndex >= 0 && _selectedHomeIndex < _homes.Count)
            _homeGuiRenameInput = _homes[_selectedHomeIndex].Name;
        else
            _homeGuiRenameInput = string.Empty;
    }

    private void HandleHomeGuiMainClick(Point mousePosition)
    {
        var renameClicked = _homeGuiRenameInputRect.Contains(mousePosition);
        _homeGuiRenameSelectAll = renameClicked && _homeGuiRenameFocused && !string.IsNullOrEmpty(_homeGuiRenameInput);
        _homeGuiRenameFocused = renameClicked;
        _homeGuiCreateNameFocused = false;
        _homeGuiCreateNameSelectAll = false;
        _homeGuiIconSearchFocused = false;
        _homeGuiIconSearchSelectAll = false;

        if (_homeGuiCloseButtonRect.Contains(mousePosition))
        {
            _homeGuiOpen = false;
            return;
        }

        if (_homeGuiCreateButtonRect.Contains(mousePosition))
        {
            BeginCreateHomePopup();
            return;
        }

        if (_homeGuiHelpButtonRect.Contains(mousePosition))
        {
            _homeGuiHelpPopupOpen = true;
            return;
        }

        if (TryGetHomeRowAtPoint(mousePosition, out var idx, out var rowRect))
        {
            var deleteRect = new Rectangle(rowRect.Right - 28, rowRect.Y + 10, 18, 18);
            if (deleteRect.Contains(mousePosition))
            {
                _selectedHomeIndex = idx;
                SyncHomeGuiSelectionFields();
                DeleteSelectedHomeFromGui();
                return;
            }

            _selectedHomeIndex = idx;
            SyncHomeGuiSelectionFields();
            return;
        }

        if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
            return;

        if (_homeGuiRenameButtonRect.Contains(mousePosition))
        {
            RenameSelectedHomeFromGui();
            return;
        }

        if (_homeGuiDetailIconButtonRect.Contains(mousePosition))
        {
            OpenHomeGuiIconPicker(forCreatePopup: false);
            return;
        }

        for (var i = 0; i < _homeGuiColorRects.Count; i++)
        {
            if (!_homeGuiColorRects[i].Contains(mousePosition))
                continue;
            SetSelectedHomeColor(HomeGuiPalette[i]);
            return;
        }

        if (CanUseCheatCommands() && _homeGuiTeleportButtonRect.Contains(mousePosition))
        {
            TeleportSelectedHomeFromGui();
            return;
        }

        if (_homeGuiSetHereButtonRect.Contains(mousePosition))
        {
            UpdateSelectedHomePositionFromGui();
            return;
        }

        if (_homeGuiFavoriteButtonRect.Contains(mousePosition))
        {
            ToggleFavoriteSelectedHomeFromGui();
            return;
        }

        if (_homeGuiDeleteButtonRect.Contains(mousePosition))
        {
            DeleteSelectedHomeFromGui();
            return;
        }
    }

    private void HandleHomeGuiCreatePopupClick(Point mousePosition)
    {
        var createNameClicked = _homeGuiCreateNameInputRect.Contains(mousePosition);
        _homeGuiCreateNameSelectAll = createNameClicked && _homeGuiCreateNameFocused && !string.IsNullOrEmpty(_homeGuiCreateNameInput);
        _homeGuiCreateNameFocused = createNameClicked;
        _homeGuiRenameFocused = false;
        _homeGuiRenameSelectAll = false;

        if (_homeGuiCreateConfirmButtonRect.Contains(mousePosition))
        {
            ConfirmCreateHomeFromGui();
            return;
        }

        if (_homeGuiCreateCancelButtonRect.Contains(mousePosition))
        {
            _homeGuiCreatePopupOpen = false;
            _homeGuiCreateNameFocused = false;
            return;
        }

        if (_homeGuiCreateIconButtonRect.Contains(mousePosition))
        {
            OpenHomeGuiIconPicker(forCreatePopup: true);
            return;
        }

        for (var i = 0; i < _homeGuiCreateColorRects.Count; i++)
        {
            if (!_homeGuiCreateColorRects[i].Contains(mousePosition))
                continue;
            _homeGuiCreateColor = HomeGuiPalette[i];
            return;
        }
    }

    private void HandleHomeGuiIconPickerClick(Point mousePosition)
    {
        var searchClicked = _homeGuiIconSearchRect.Contains(mousePosition);
        _homeGuiIconSearchSelectAll = searchClicked && _homeGuiIconSearchFocused && !string.IsNullOrEmpty(_homeGuiIconSearchText);
        _homeGuiIconSearchFocused = searchClicked;

        if (_homeGuiIconSearchClearRect.Contains(mousePosition))
        {
            _homeGuiIconSearchText = string.Empty;
            RefreshHomeGuiFilteredIcons();
            return;
        }

        if (_homeGuiIconDoneButtonRect.Contains(mousePosition))
        {
            _homeGuiIconPickerOpen = false;
            _homeGuiIconSearchFocused = false;
            return;
        }

        for (var i = 0; i < _homeGuiIconCellRects.Count && i < _homeGuiFilteredIcons.Count; i++)
        {
            if (!_homeGuiIconCellRects[i].Contains(mousePosition))
                continue;
            ApplyHomeGuiIconSelection(_homeGuiFilteredIcons[i].Id);
            return;
        }
    }

    private void ConfirmCreateHomeFromGui()
    {
        var requestedName = IsMultipleHomesEnabled() ? _homeGuiCreateNameInput : DefaultHomeName;
        if (!TrySetHome(requestedName, _player.Position, out var result))
        {
            SetHomeGuiStatus(result);
            return;
        }

        if (_selectedHomeIndex >= 0 && _selectedHomeIndex < _homes.Count)
        {
            var entry = _homes[_selectedHomeIndex];
            entry.AccentColor = NormalizeHomeColor(_homeGuiCreateColor);
            entry.HasIconBlock = _homeGuiCreateHasIconBlock;
            entry.IconBlock = _homeGuiCreateHasIconBlock ? _homeGuiCreateIconBlock : BlockId.Air;
            _homes[_selectedHomeIndex] = entry;
            SavePlayerState();
            SyncHomeGuiSelectionFields();
        }

        _homeGuiCreatePopupOpen = false;
        _homeGuiCreateNameFocused = false;
        _homeGuiCreateNameSelectAll = false;
        SetHomeGuiStatus(result);
    }

    private void ConfirmDeleteSelectedHomeFromGui()
    {
        if (_homeGuiPendingDeleteIndex < 0 || _homeGuiPendingDeleteIndex >= _homes.Count)
        {
            _homeGuiDeleteConfirmOpen = false;
            _homeGuiPendingDeleteIndex = -1;
            return;
        }

        var removedName = _homes[_homeGuiPendingDeleteIndex].Name;
        _homes.RemoveAt(_homeGuiPendingDeleteIndex);
        if (string.Equals(_favoriteHomeName, removedName, StringComparison.OrdinalIgnoreCase))
            _favoriteHomeName = string.Empty;
        _selectedHomeIndex = _homes.Count == 0 ? -1 : Math.Clamp(_homeGuiPendingDeleteIndex, 0, _homes.Count - 1);
        _homeGuiPendingDeleteIndex = -1;
        _homeGuiDeleteConfirmOpen = false;
        SyncLegacyHomeFields();
        SyncHomeGuiSelectionFields();
        SavePlayerState();
        SetHomeGuiStatus($"Deleted '{removedName}'.");
    }

    private void TeleportSelectedHomeFromGui()
    {
        if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
        {
            SetHomeGuiStatus("Select a home first.");
            return;
        }

        if (TryTeleportToHome(_homes[_selectedHomeIndex].Name, out var result))
            SetHomeGuiStatus(result);
        else
            SetHomeGuiStatus(result);
    }

    private void UpdateSelectedHomePositionFromGui()
    {
        if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
        {
            SetHomeGuiStatus("Select a home first.");
            return;
        }

        var entry = _homes[_selectedHomeIndex];
        entry.Position = _player.Position;
        _homes[_selectedHomeIndex] = entry;
        SavePlayerState();
        SetHomeGuiStatus($"Updated '{entry.Name}' to {(int)entry.Position.X}, {(int)entry.Position.Y}, {(int)entry.Position.Z}.");
    }

    private void ToggleFavoriteSelectedHomeFromGui()
    {
        if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
        {
            SetHomeGuiStatus("Select a home first.");
            return;
        }

        if (IsFavoriteHomeIndex(_selectedHomeIndex))
        {
            _favoriteHomeName = string.Empty;
            SavePlayerState();
            SetHomeGuiStatus("Favorite home cleared.");
            return;
        }

        SetFavoriteHomeByIndex(_selectedHomeIndex);
        SavePlayerState();
        SetHomeGuiStatus($"Favorite home set to '{_homes[_selectedHomeIndex].Name}'.");
    }

    private void SetSelectedHomeColor(Color color)
    {
        if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
            return;

        var entry = _homes[_selectedHomeIndex];
        entry.AccentColor = NormalizeHomeColor(color);
        _homes[_selectedHomeIndex] = entry;
        SavePlayerState();
    }

    private void OpenHomeGuiIconPicker(bool forCreatePopup)
    {
        _homeGuiIconPickerForCreate = forCreatePopup;
        _homeGuiIconPickerOpen = true;
        _homeGuiIconSearchFocused = true;
        _homeGuiIconSearchSelectAll = false;
        _homeGuiIconSearchText = string.Empty;
        _homeGuiIconScroll = 0f;
        RefreshHomeGuiFilteredIcons();
    }

    private void ApplyHomeGuiIconSelection(BlockId blockId)
    {
        if (_homeGuiIconPickerForCreate)
        {
            _homeGuiCreateHasIconBlock = true;
            _homeGuiCreateIconBlock = blockId;
        }
        else
        {
            if (_selectedHomeIndex < 0 || _selectedHomeIndex >= _homes.Count)
                return;

            var entry = _homes[_selectedHomeIndex];
            entry.HasIconBlock = true;
            entry.IconBlock = blockId;
            _homes[_selectedHomeIndex] = entry;
            SavePlayerState();
        }

        _homeGuiIconPickerOpen = false;
        _homeGuiIconSearchFocused = false;
        _homeGuiIconSearchSelectAll = false;
    }

    private void BuildHomeGuiIconCatalog()
    {
        if (_homeGuiIconCatalog.Count > 0)
            return;

        _homeGuiIconCatalog.AddRange(BlockRegistry.All
            .Where(def => def.Id != BlockId.Air && def.IsVisibleInInventory)
            .OrderBy(def => def.AtlasIndex)
            .ThenBy(def => def.Name, StringComparer.OrdinalIgnoreCase));
        RefreshHomeGuiFilteredIcons();
    }

    private void RefreshHomeGuiFilteredIcons()
    {
        _homeGuiFilteredIcons.Clear();
        IEnumerable<BlockDef> source = _homeGuiIconCatalog;
        var filter = _homeGuiIconSearchText.Trim();
        if (filter.Length > 0)
        {
            source = source.Where(def =>
                def.Name.Contains(filter, StringComparison.OrdinalIgnoreCase) ||
                def.Id.ToString().Contains(filter, StringComparison.OrdinalIgnoreCase));
        }

        _homeGuiFilteredIcons.AddRange(source);
        _homeGuiIconScroll = Math.Clamp(_homeGuiIconScroll, 0f, GetMaxHomeGuiIconScroll());
        BuildHomeGuiIconCellRects();
    }

    private float GetMaxHomeGuiIconScroll()
    {
        var columns = Math.Max(1, (_homeGuiIconGridRect.Width + 8) / (HomeGuiIconCellSize + 8));
        var rows = (_homeGuiFilteredIcons.Count + columns - 1) / columns;
        var contentHeight = rows * (HomeGuiIconCellSize + 8);
        return Math.Max(0f, contentHeight - _homeGuiIconGridRect.Height);
    }

    private void BuildHomeGuiIconCellRects()
    {
        _homeGuiIconCellRects.Clear();
        if (_homeGuiIconGridRect.Width <= 0 || _homeGuiIconGridRect.Height <= 0)
            return;

        var columns = Math.Max(1, (_homeGuiIconGridRect.Width + 8) / (HomeGuiIconCellSize + 8));
        for (var i = 0; i < _homeGuiFilteredIcons.Count; i++)
        {
            var col = i % columns;
            var row = i / columns;
            var x = _homeGuiIconGridRect.X + col * (HomeGuiIconCellSize + 8);
            var y = _homeGuiIconGridRect.Y + row * (HomeGuiIconCellSize + 8) - (int)MathF.Round(_homeGuiIconScroll);
            _homeGuiIconCellRects.Add(new Rectangle(x, y, HomeGuiIconCellSize, HomeGuiIconCellSize));
        }
    }

    private void LayoutHomeGuiColorRects(int startX, int startY, int maxWidth, List<Rectangle> target)
    {
        target.Clear();
        const int swatchSize = 22;
        const int gap = 8;
        var columns = Math.Max(1, maxWidth / (swatchSize + gap));
        for (var i = 0; i < HomeGuiPalette.Length; i++)
        {
            var col = i % columns;
            var row = i / columns;
            target.Add(new Rectangle(startX + col * (swatchSize + gap), startY + row * (swatchSize + gap), swatchSize, swatchSize));
        }
    }

    private void DrawHomeGuiCreatePopup(SpriteBatch sb)
    {
        sb.Draw(_pixel, _viewport, new Color(0, 0, 0, 94));
        sb.Draw(_pixel, _homeGuiCreatePopupRect, new Color(20, 24, 30, 242));
        DrawBorder(sb, _homeGuiCreatePopupRect, new Color(214, 222, 232));
        _font.DrawString(sb, "CREATE HOME", new Vector2(_homeGuiCreatePopupRect.X + 22, _homeGuiCreatePopupRect.Y + 18), Color.White);
        DrawHomeGuiInput(sb, _homeGuiCreateNameInputRect, _homeGuiCreateNameInput, _homeGuiCreateNameFocused, _homeGuiCreateNameSelectAll, IsMultipleHomesEnabled() ? "(home name)" : "Single-home world");
        DrawHomeIcon(sb, new PlayerHomeEntry
        {
            Name = NormalizeHomeName(_homeGuiCreateNameInput),
            AccentColor = _homeGuiCreateColor,
            HasIconBlock = _homeGuiCreateHasIconBlock,
            IconBlock = _homeGuiCreateHasIconBlock ? _homeGuiCreateIconBlock : BlockId.Air
        }, _homeGuiCreateIconButtonRect);
        DrawBorder(sb, _homeGuiCreateIconButtonRect, _homeGuiCreateColor);
