    private void DrawHomeGuiInput(SpriteBatch sb, Rectangle rect, string text, bool focused, bool selectAll, string placeholder)
    {
        sb.Draw(_pixel, rect, new Color(8, 10, 14, 224));
        DrawBorder(sb, rect, focused ? new Color(232, 224, 150) : new Color(126, 136, 148));
        var drawText = string.IsNullOrWhiteSpace(text) ? placeholder : text;
        var color = string.IsNullOrWhiteSpace(text) ? new Color(148, 156, 168) : Color.White;
        var textPos = new Vector2(rect.X + 8, rect.Y + 8);
        TextFieldVisuals.DrawWholeFieldSelection(sb, _pixel, _font, text, textPos, rect, selectAll, new Color(88, 148, 218, 170));
        _font.DrawString(sb, drawText, textPos, color);
        TextFieldVisuals.DrawCaret(sb, _pixel, _font, text, textPos, rect, focused, selectAll, _worldTimeSeconds, new Color(235, 228, 168));
    }

    private void DrawHomeGuiButton(SpriteBatch sb, Rectangle rect, string label, bool canClick, bool destructive = false, bool active = false)
    {
        var hovered = rect.Contains(_overlayMousePos);
        var bg = destructive ? new Color(104, 40, 40) : new Color(32, 38, 48);
        if (active)
            bg = destructive ? new Color(138, 58, 58) : new Color(52, 88, 124);
        else if (hovered && canClick)
            bg = destructive ? new Color(124, 54, 54) : new Color(52, 68, 92);
        if (!canClick)
            bg = new Color(24, 26, 30);

        sb.Draw(_pixel, rect, bg);
        DrawBorder(sb, rect, canClick ? new Color(214, 222, 232) : new Color(112, 118, 126));
        var fg = canClick ? Color.White : new Color(148, 156, 168);
        var size = _font.MeasureString(label);
        _font.DrawString(sb, label, new Vector2(rect.Center.X - size.X / 2f, rect.Center.Y - size.Y / 2f), fg);
    }

    private void DrawHomeGuiColorPalette(SpriteBatch sb, List<Rectangle> rects, Color selectedColor)
    {
        for (var i = 0; i < rects.Count && i < HomeGuiPalette.Length; i++)
        {
            var rect = rects[i];
            sb.Draw(_pixel, rect, HomeGuiPalette[i]);
            var border = ColorsApproximatelyEqual(HomeGuiPalette[i], selectedColor)
                ? new Color(248, 248, 248)
                : new Color(80, 88, 98);
            DrawBorder(sb, rect, border);
        }
    }

    private void DrawHomeGuiBlockIcon(SpriteBatch sb, BlockId blockId, Rectangle rect)
    {
        var icon = GetBlockIcon(blockId, Math.Max(16, rect.Width));
        if (icon != null)
        {
            sb.Draw(icon, rect, Color.White);
            return;
        }

        if (_atlas != null)
            sb.Draw(_atlas.Texture, rect, _atlas.GetFaceSourceRect((byte)blockId, FaceDirection.PosY), Color.White);
    }

    private void ApplyHomeGuiTextInput(InputState input, ref string target, int maxLength, ref bool selectAll)
    {
        if (!string.IsNullOrEmpty(target) && input.IsLeftDragActive())
            selectAll = true;

        if (TryHandleWholeFieldClipboard(input, ref target, maxLength, ref selectAll))
            return;

        foreach (var key in input.GetTextInputKeys())
        {
            if (key == Keys.Back)
            {
                if (selectAll)
                {
                    target = string.Empty;
                    selectAll = false;
                }
                else if (target.Length > 0)
                {
                    target = target.Substring(0, target.Length - 1);
                }
                continue;
            }

            if (!TryMapCommandInputKey(key, input.IsKeyDown(Keys.LeftShift) || input.IsKeyDown(Keys.RightShift), out var c))
                continue;

            ApplyWholeFieldTextKey(ref target, ref selectAll, c, maxLength);
        }
    }

    private static Color NormalizeHomeColor(Color color)
    {
        return color.A == 0 ? DefaultHomeAccentColor : color;
    }

    private static uint PackHomeColor(Color color) => NormalizeHomeColor(color).PackedValue;

    private static Color UnpackHomeColor(uint packed)
    {
        return packed == 0u ? DefaultHomeAccentColor : new Color(packed);
    }

    private static bool ColorsApproximatelyEqual(Color left, Color right)
    {
        return left.PackedValue == right.PackedValue;
    }

    private static Color LightenHomeColor(Color color, int amount)
    {
        return new Color(
            Math.Clamp(color.R + amount, 0, 255),
            Math.Clamp(color.G + amount, 0, 255),
            Math.Clamp(color.B + amount, 0, 255),
            255);
    }

    private void OpenStructureFinderGui(bool openStructuresTab)
    {
        if (!CanUseStructureFinderTools(out var denialReason))
        {
            _structureFinderOpen = false;
            SetCommandStatus(denialReason);
            return;
        }

        _homeGuiOpen = false;
        _structureFinderOpen = true;
        _structureFinderStructureTab = openStructuresTab;
        _structureFinderHelpPopupOpen = false;
        _structureFinderStatus = string.Empty;
        _structureFinderStatusTimer = 0f;
        ClearStructureFinderResult();
        LayoutStructureFinderGui();
    }

    private void LayoutStructureFinderGui()
    {
        if (_structureFinderBiomeRects.Length != FinderBiomeLabels.Length)
            _structureFinderBiomeRects = new Rectangle[FinderBiomeLabels.Length];

        var panelW = Math.Clamp(_viewport.Width - 220, 700, 980);
        var panelH = Math.Clamp(_viewport.Height - 220, 420, 640);
        _structureFinderPanelRect = new Rectangle(
            _viewport.Center.X - panelW / 2,
            _viewport.Center.Y - panelH / 2 - 26,
            panelW,
            panelH);

        _structureFinderHeaderRect = new Rectangle(_structureFinderPanelRect.X + 16, _structureFinderPanelRect.Y + 14, _structureFinderPanelRect.Width - 32, 52);
        _structureFinderFooterRect = new Rectangle(_structureFinderPanelRect.X + 16, _structureFinderPanelRect.Bottom - 52, _structureFinderPanelRect.Width - 32, 34);
        var contentTop = _structureFinderHeaderRect.Bottom + 12;
        var contentBottom = _structureFinderFooterRect.Y - 12;
        var contentHeight = Math.Max(180, contentBottom - contentTop);
        var listWidth = Math.Clamp(_structureFinderPanelRect.Width / 3, 240, 320);
        _structureFinderListRect = new Rectangle(_structureFinderPanelRect.X + 16, contentTop, listWidth, contentHeight);
        _structureFinderDetailRect = new Rectangle(_structureFinderListRect.Right + 14, contentTop, _structureFinderPanelRect.Right - 16 - (_structureFinderListRect.Right + 14), contentHeight);

        _structureFinderHelpButtonRect = new Rectangle(_structureFinderHeaderRect.Right - 76, _structureFinderHeaderRect.Y + 10, 32, 32);
        _structureFinderCloseBtn.Bounds = new Rectangle(_structureFinderHeaderRect.Right - 38, _structureFinderHeaderRect.Y + 10, 32, 32);
        var biomeTabWidth = Math.Max(96, (int)Math.Ceiling(_font.MeasureString(_structureFinderBiomeTabBtn.Label).X) + 26);
        var structureTabWidth = Math.Max(136, (int)Math.Ceiling(_font.MeasureString(_structureFinderStructureTabBtn.Label).X) + 26);
        var radiusTabWidth = Math.Max(158, (int)Math.Ceiling(_font.MeasureString($"RADIUS: {FinderRadiusOptions[^1]}").X) + 26);
        var headerActionWidth = biomeTabWidth + 8 + structureTabWidth + 8 + radiusTabWidth;
        var headerActionX = Math.Max(_structureFinderHeaderRect.X + 156, _structureFinderHelpButtonRect.X - 12 - headerActionWidth);
        _structureFinderBiomeTabBtn.Bounds = new Rectangle(headerActionX, _structureFinderHeaderRect.Y + 10, biomeTabWidth, 32);
        _structureFinderStructureTabBtn.Bounds = new Rectangle(_structureFinderBiomeTabBtn.Bounds.Right + 8, _structureFinderBiomeTabBtn.Bounds.Y, structureTabWidth, 32);
        _structureFinderRadiusBtn.Bounds = new Rectangle(_structureFinderStructureTabBtn.Bounds.Right + 8, _structureFinderBiomeTabBtn.Bounds.Y, radiusTabWidth, 32);
        _structureFinderHelpPopupRect = new Rectangle(
            _viewport.Center.X - Math.Min(580, _viewport.Width - 80) / 2,
            _viewport.Center.Y - Math.Min(348, _viewport.Height - 80) / 2,
            Math.Min(580, _viewport.Width - 80),
            Math.Min(348, _viewport.Height - 80));
        _structureFinderHelpCloseButtonRect = new Rectangle(_structureFinderHelpPopupRect.Right - 126, _structureFinderHelpPopupRect.Bottom - 38, 98, 28);

        var rowH = HomeGuiRowHeight;
        for (var i = 0; i < _structureFinderBiomeRects.Length; i++)
        {
            _structureFinderBiomeRects[i] = new Rectangle(
                _structureFinderListRect.X + 4,
                _structureFinderListRect.Y + 4 + i * rowH,
                _structureFinderListRect.Width - 8,
                rowH - 4);
        }

        _structureFinderFindBtn.Bounds = new Rectangle(_structureFinderDetailRect.X + 18, _structureFinderDetailRect.Bottom - 90, 92, 34);
        _structureFinderTeleportBtn.Bounds = new Rectangle(_structureFinderFindBtn.Bounds.Right + 10, _structureFinderFindBtn.Bounds.Y, 118, 34);
        _structureFinderPrintBtn.Bounds = new Rectangle(_structureFinderTeleportBtn.Bounds.Right + 10, _structureFinderTeleportBtn.Bounds.Y, 146, 34);
    }

    private void UpdateStructureFinderGui(InputState input, float dt)
    {
        LayoutStructureFinderGui();
        if (!CanUseStructureFinderTools(out var denialReason))
        {
            _structureFinderOpen = false;
            SetCommandStatus(denialReason);
            return;
        }

        if (_structureFinderStatusTimer > 0f)
        {
            _structureFinderStatusTimer = Math.Max(0f, _structureFinderStatusTimer - dt);
            if (_structureFinderStatusTimer <= 0f)
                _structureFinderStatus = string.Empty;
        }

        if (input.IsNewKeyPress(Keys.Escape))
        {
            if (_structureFinderHelpPopupOpen)
            {
                _structureFinderHelpPopupOpen = false;
                return;
            }

            _structureFinderOpen = false;
            return;
        }

        if (IsNewActionPress(input, "StructureFinder", Keys.B))
        {
            if (_structureFinderHelpPopupOpen)
            {
                _structureFinderHelpPopupOpen = false;
                return;
            }

            _structureFinderOpen = false;
            return;
        }

        if (_structureFinderHelpPopupOpen)
        {
            if (input.IsNewLeftClick() && _structureFinderHelpCloseButtonRect.Contains(input.MousePosition))
                _structureFinderHelpPopupOpen = false;

            return;
        }

        if (input.IsNewLeftClick() && _structureFinderHelpButtonRect.Contains(input.MousePosition))
        {
            _structureFinderHelpPopupOpen = true;
            return;
        }

        if (!_structureFinderStructureTab && input.IsNewLeftClick() && _structureFinderListRect.Contains(input.MousePosition))
        {
            for (var i = 0; i < _structureFinderBiomeRects.Length; i++)
            {
                if (_structureFinderBiomeRects[i].Contains(input.MousePosition))
                {
                    _structureFinderSelectedBiomeIndex = i;
                    ClearStructureFinderResult();
                    break;
                }
            }
        }

        _structureFinderBiomeTabBtn.ForceDisabledStyle = !_structureFinderStructureTab;
        _structureFinderStructureTabBtn.ForceDisabledStyle = _structureFinderStructureTab;
        _structureFinderRadiusBtn.Enabled = !_structureFinderStructureTab;
        _structureFinderFindBtn.Enabled = !_structureFinderStructureTab;
        _structureFinderTeleportBtn.Enabled = !_structureFinderStructureTab && _structureFinderHasResult && CanUseCheatCommands();
        _structureFinderPrintBtn.Enabled = !_structureFinderStructureTab && _structureFinderHasResult;
        _structureFinderRadiusBtn.ForceDisabledStyle = _structureFinderStructureTab;
        _structureFinderFindBtn.ForceDisabledStyle = _structureFinderStructureTab;
        _structureFinderTeleportBtn.ForceDisabledStyle = _structureFinderStructureTab || !_structureFinderHasResult || !CanUseCheatCommands();
        _structureFinderPrintBtn.ForceDisabledStyle = _structureFinderStructureTab || !_structureFinderHasResult;

        _structureFinderBiomeTabBtn.Update(input);
        _structureFinderStructureTabBtn.Update(input);
        _structureFinderRadiusBtn.Update(input);
        _structureFinderFindBtn.Update(input);
        _structureFinderTeleportBtn.Update(input);
        _structureFinderPrintBtn.Update(input);
        _structureFinderCloseBtn.Update(input);
    }

    private void DrawStructureFinderGui(SpriteBatch sb)
    {
        sb.Draw(_pixel, _viewport, new Color(0, 0, 0, 110));
        sb.Draw(_pixel, _structureFinderPanelRect, new Color(18, 22, 28, 236));
        DrawBorder(sb, _structureFinderPanelRect, new Color(96, 110, 128));
        sb.Draw(_pixel, _structureFinderHeaderRect, new Color(12, 15, 20, 225));
        DrawBorder(sb, _structureFinderHeaderRect, new Color(120, 135, 150));
        _font.DrawString(sb, "BIOME FINDER", new Vector2(_structureFinderHeaderRect.X + 14, _structureFinderHeaderRect.Y + 9), Color.White);
        DrawHomeGuiButton(sb, _structureFinderBiomeTabBtn.Bounds, _structureFinderBiomeTabBtn.Label, canClick: true, active: !_structureFinderStructureTab);
        DrawHomeGuiButton(sb, _structureFinderStructureTabBtn.Bounds, _structureFinderStructureTabBtn.Label, canClick: true, active: _structureFinderStructureTab);
        DrawHomeGuiButton(sb, _structureFinderRadiusBtn.Bounds, _structureFinderRadiusBtn.Label, canClick: !_structureFinderStructureTab);
        DrawHomeGuiButton(sb, _structureFinderHelpButtonRect, "?", canClick: true, active: _structureFinderHelpPopupOpen);
        DrawHomeGuiButton(sb, _structureFinderCloseBtn.Bounds, "X", canClick: true, destructive: true);

        sb.Draw(_pixel, _structureFinderListRect, new Color(10, 12, 18, 208));
        DrawBorder(sb, _structureFinderListRect, new Color(120, 135, 150));
        _font.DrawString(sb, "BIOMES", new Vector2(_structureFinderListRect.X + 10, _structureFinderListRect.Y - _font.LineHeight - 4), new Color(188, 214, 236));
        if (_structureFinderStructureTab)
        {
            _font.DrawString(sb, "Structures are not wired yet.", new Vector2(_structureFinderListRect.X + 18, _structureFinderListRect.Y + 18), new Color(230, 230, 230));
            _font.DrawString(sb, "Use the BIOMES tab for live nearby biome searches.", new Vector2(_structureFinderListRect.X + 18, _structureFinderListRect.Y + 18 + _font.LineHeight + 4), new Color(175, 195, 220));
        }
        else
        {
            for (var i = 0; i < _structureFinderBiomeRects.Length; i++)
            {
                var rect = _structureFinderBiomeRects[i];
                var selected = i == _structureFinderSelectedBiomeIndex;
                var accent = selected ? new Color(126, 170, 214) : new Color(88, 98, 112);
                sb.Draw(_pixel, rect, selected ? new Color(34, 54, 74, 232) : new Color(20, 22, 28, 198));
                DrawBorder(sb, rect, accent);
                var iconRect = new Rectangle(rect.X + 8, rect.Y + 8, 36, 36);
                DrawHomeGuiBlockIcon(sb, GetStructureFinderBiomeIcon(i), iconRect);
                DrawBorder(sb, iconRect, selected ? new Color(214, 222, 232) : new Color(102, 114, 128));
                _font.DrawString(sb, FinderBiomeLabels[i], new Vector2(iconRect.Right + 10, rect.Y + 12), Color.White);
            }
        }

        sb.Draw(_pixel, _structureFinderDetailRect, new Color(12, 14, 20, 208));
        DrawBorder(sb, _structureFinderDetailRect, new Color(120, 135, 150));
        if (_structureFinderStructureTab)
        {
            _font.DrawString(sb, "DETAILS", new Vector2(_structureFinderDetailRect.X + 18, _structureFinderDetailRect.Y + 14), new Color(188, 214, 236));
            _font.DrawString(sb, "No structure actions are available yet.", new Vector2(_structureFinderDetailRect.X + 18, _structureFinderDetailRect.Y + 52), new Color(196, 204, 214));
        }
        else
        {
            var biomeIndex = Math.Clamp(_structureFinderSelectedBiomeIndex, 0, FinderBiomeLabels.Length - 1);
            var radiusIndex = Math.Clamp(_structureFinderRadiusIndex, 0, FinderRadiusOptions.Length - 1);
            var selectedLabel = FinderBiomeLabels[biomeIndex];
            _font.DrawString(sb, "DETAILS", new Vector2(_structureFinderDetailRect.X + 18, _structureFinderDetailRect.Y + 14), new Color(188, 214, 236));
            _font.DrawString(sb, selectedLabel, new Vector2(_structureFinderDetailRect.X + 18, _structureFinderDetailRect.Y + 52), Color.White);
            _font.DrawString(sb, $"Search radius: {FinderRadiusOptions[radiusIndex]}", new Vector2(_structureFinderDetailRect.X + 18, _structureFinderDetailRect.Y + 52 + _font.LineHeight + 6), new Color(180, 196, 214));
            var detailWrapWidth = _structureFinderDetailRect.Width - 36;
            var helperLines = WrapOverlayText("Use FIND to locate the nearest matching biome around your current position.", detailWrapWidth);
            var helperY = _structureFinderDetailRect.Y + 52 + (_font.LineHeight + 6) * 2;
            for (var i = 0; i < helperLines.Count; i++)
            {
                _font.DrawString(sb, helperLines[i], new Vector2(_structureFinderDetailRect.X + 18, helperY), new Color(228, 214, 164));
                helperY += _font.LineHeight + 2;
            }

            var resultTop = Math.Max(_structureFinderDetailRect.Y + 156, helperY + 16);
            if (_structureFinderHasResult)
            {
                _font.DrawString(sb, $"Found {_structureFinderResultLabel}", new Vector2(_structureFinderDetailRect.X + 18, resultTop), Color.White);
                _font.DrawString(sb, $"Location: {_structureFinderResultX}, {_structureFinderResultY}, {_structureFinderResultZ}", new Vector2(_structureFinderDetailRect.X + 18, resultTop + _font.LineHeight + 8), new Color(214, 220, 228));
                var resultHelperLines = WrapOverlayText("TELEPORT moves you immediately. PRINT COORDS posts a clickable chat line.", detailWrapWidth);
                var resultHelperY = resultTop + (_font.LineHeight + 8) * 2;
                for (var i = 0; i < resultHelperLines.Count; i++)
                {
                    _font.DrawString(sb, resultHelperLines[i], new Vector2(_structureFinderDetailRect.X + 18, resultHelperY), CanUseCheatCommands() ? new Color(178, 220, 188) : new Color(208, 176, 132));
                    resultHelperY += _font.LineHeight + 2;
                }
            }
            else
            {
                _font.DrawString(sb, "No biome result yet.", new Vector2(_structureFinderDetailRect.X + 18, resultTop), new Color(196, 204, 214));
                var emptyLines = WrapOverlayText("Run FIND to locate a nearby biome, then teleport directly or print the coordinates to chat.", detailWrapWidth);
                var emptyY = resultTop + _font.LineHeight + 8;
                for (var i = 0; i < emptyLines.Count; i++)
                {
                    _font.DrawString(sb, emptyLines[i], new Vector2(_structureFinderDetailRect.X + 18, emptyY), new Color(172, 184, 196));
                    emptyY += _font.LineHeight + 2;
                }
            }

            DrawHomeGuiButton(sb, _structureFinderFindBtn.Bounds, _structureFinderFindBtn.Label, canClick: !_structureFinderStructureTab);
            DrawHomeGuiButton(sb, _structureFinderTeleportBtn.Bounds, _structureFinderTeleportBtn.Label, canClick: _structureFinderHasResult && CanUseCheatCommands());
            DrawHomeGuiButton(sb, _structureFinderPrintBtn.Bounds, _structureFinderPrintBtn.Label, canClick: _structureFinderHasResult);
        }

        if (!string.IsNullOrWhiteSpace(_structureFinderStatus))
            _font.DrawString(sb, _structureFinderStatus, new Vector2(_structureFinderFooterRect.X, _structureFinderFooterRect.Y + 6), new Color(235, 235, 180));

        if (_structureFinderHelpPopupOpen)
            DrawStructureFinderHelpPopup(sb);
    }

    private void CycleStructureFinderRadius()
    {
        _structureFinderRadiusIndex++;
        if (_structureFinderRadiusIndex >= FinderRadiusOptions.Length)
            _structureFinderRadiusIndex = 0;
        SyncStructureFinderRadiusLabel();
        ClearStructureFinderResult();
    }

    private void SyncStructureFinderRadiusLabel()
    {
        var index = Math.Clamp(_structureFinderRadiusIndex, 0, FinderRadiusOptions.Length - 1);
        _structureFinderRadiusIndex = index;
        _structureFinderRadiusBtn.Label = $"RADIUS: {FinderRadiusOptions[index]}";
    }

    private void ExecuteStructureFinderSearchFromGui()
    {
        if (_structureFinderStructureTab)
        {
            SetStructureFinderStatus("No structures configured yet.");
            return;
        }

        var biomeIndex = Math.Clamp(_structureFinderSelectedBiomeIndex, 0, FinderBiomeTokens.Length - 1);
        var radiusIndex = Math.Clamp(_structureFinderRadiusIndex, 0, FinderRadiusOptions.Length - 1);
        var token = FinderBiomeTokens[biomeIndex];
        var label = FinderBiomeLabels[biomeIndex];
        var radius = FinderRadiusOptions[radiusIndex];
        if (TryLocateBiomeResult(token, label, radius, out var foundX, out var foundY, out var foundZ))
        {
            _structureFinderHasResult = true;
            _structureFinderResultLabel = label;
            _structureFinderResultX = foundX;
            _structureFinderResultY = foundY;
            _structureFinderResultZ = foundZ;
            SetStructureFinderStatus($"Located {label} at {foundX} {foundY} {foundZ}.");
        }
        else
        {
            ClearStructureFinderResult();
            SetStructureFinderStatus($"Unable to locate {label}.");
        }
    }

    private void SetStructureFinderStatus(string message)
    {
        _structureFinderStatus = message;
        _structureFinderStatusTimer = 4f;
    }

    private void ClearStructureFinderResult()
    {
        _structureFinderHasResult = false;
        _structureFinderResultLabel = string.Empty;
        _structureFinderResultX = 0;
        _structureFinderResultY = 0;
        _structureFinderResultZ = 0;
    }

    private void TeleportStructureFinderResultFromGui()
    {
        if (!_structureFinderHasResult)
        {
            SetStructureFinderStatus("Locate a biome first.");
            return;
        }

        if (!CanUseCheatCommands())
        {
            SetStructureFinderStatus("Commands are disabled in this world.");
            return;
        }

        if (TryTeleportPlayer(_structureFinderResultX, _structureFinderResultZ, _structureFinderResultY, out var result))
            SetStructureFinderStatus(result);
        else
            SetStructureFinderStatus(result);
    }

    private void PrintStructureFinderResultToChat()
    {
        if (!_structureFinderHasResult)
        {
            SetStructureFinderStatus("Locate a biome first.");
            return;
        }

        AddChatLine(
            $"X: {_structureFinderResultX} Y: {_structureFinderResultY} Z: {_structureFinderResultZ}",
            isSystem: true,
            teleportX: _structureFinderResultX,
            teleportY: _structureFinderResultY,
            teleportZ: _structureFinderResultZ,
            hoverText: $"Click to teleport to {_structureFinderResultLabel} at {_structureFinderResultX} {_structureFinderResultY} {_structureFinderResultZ}");
        SetStructureFinderStatus($"Printed {_structureFinderResultLabel} coordinates to chat.");
    }

    private static BlockId GetStructureFinderBiomeIcon(int biomeIndex)
    {
        return biomeIndex switch
        {
            0 => BlockId.Grass,
            1 => BlockId.Leaves,
            2 => BlockId.Stone,
            3 => BlockId.Sand,
            4 => BlockId.Water,
            _ => BlockId.Grass
        };
    }

    private void ExecuteMeCommand(string[] commandParts)
    {
        if (commandParts.Length < 2)
        {
            SetCommandSyntax("me");
            return;
        }

        var raw = string.Join(" ", commandParts.Skip(1));
        var username = _profile.GetDisplayUsername();
        if (_lanSession != null && _lanSession.IsConnected)
        {
            _lanSession.SendChat(new LanChatMessage
            {
                FromPlayerId = _lanSession.LocalPlayerId,
                ToPlayerId = -1,
                Kind = LanChatKind.Emote,
                Text = raw,
                TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            });
            return;
        }

        AddChatLine($"* {username} {raw}", isSystem: false);
    }

    private void ExecuteMsgCommand(string[] commandParts)
    {
        if (commandParts.Length < 3)
        {
            SetCommandSyntax("msg");
            return;
        }

        if (_lanSession == null || !_lanSession.IsConnected)
        {
            SetCommandStatus("Private messaging is only available in multiplayer.");
            return;
        }

        if (!TryResolvePlayerTarget(commandParts[1], out var targetId, out var targetName))
        {
            SetCommandStatus($"Player not found: {commandParts[1]}");
            return;
        }

        var text = string.Join(" ", commandParts.Skip(2));
        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = targetId,
            Kind = LanChatKind.Whisper,
            Text = text,
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
    }

    private void ExecuteChatClearCommand(string[] commandParts)
    {
        if (commandParts.Length >= 2 && string.Equals(commandParts[1], "confirm", StringComparison.OrdinalIgnoreCase))
        {
            ClearChatHistory();
            return;
        }

        AddChatLine(
            "Clear chat history?",
            isSystem: true,
            actionLabel: "CONFIRM",
            customActionToken: ChatClearConfirmActionToken,
            customActionStatus: "Chat history cleared.",
            actionLabel2: "CANCEL",
            customActionToken2: ChatClearCancelActionToken,
            customActionStatus2: "Chat clear canceled.");
        SetCommandStatus("Click CONFIRM to clear chat history.", 4f, echoToChat: false);
    }

    private void ClearChatHistory()
    {
        _chatLines.Clear();
        _chatActionHitboxes.Clear();
        _hoveredChatActionIndex = -1;
        _chatOverlayScrollLines = 0;
        TruncateHistoryFile(ChatHistoryLogPath);
        ClearPendingQuickConfirmation();
        ResetInviteQuickHoldState();
        SetCommandStatus("Chat history cleared.");
    }

    private void ExecuteGiveCommand(string[] commandParts)
    {
        if (!_giveItemsEnabled)
        {
            SetCommandStatus("Item giving is disabled in this world. Use /rule giveitem on to enable it.");
            return;
        }

        if (commandParts.Length < 2)
        {
            SetCommandSyntax("give");
            return;
        }

        if (string.Equals(commandParts[1], "list", StringComparison.OrdinalIgnoreCase))
        {
            var all = BlockRegistry.All
                .Where(def => def.Id != BlockId.Air)
                .OrderBy(def => def.AtlasIndex)
                .Select(def => $"{(byte)def.Id}:{def.Id} ({def.Name})")
                .ToArray();
            AddChatLine($"Give IDs: {string.Join(", ", all)}", isSystem: true);
            SetCommandStatus($"Listed {all.Length} items/blocks. Use snake_case names (example: coal_ore).", 6f, echoToChat: false);
            return;
        }

        var args = commandParts.Skip(1).ToList();
        var amount = 1;

        var localId = _lanSession?.LocalPlayerId ?? 0;
        var targetId = localId;
        var targetName = ResolvePlayerName(localId);
        var itemParts = new List<string>(args);

        string itemToken;
        if (args.Count >= 2 && TryResolvePlayerTarget(args[0], out var candidateId, out var candidateName))
        {
            targetId = candidateId;
            targetName = candidateName;
            itemParts = args.Skip(1).ToList();
        }

        if (itemParts.Count > 1
            && int.TryParse(itemParts[^1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedAmount))
        {
            amount = Math.Max(1, parsedAmount);
            itemParts.RemoveAt(itemParts.Count - 1);
        }

        itemToken = string.Join(" ", itemParts);
        if (!TryResolveInventoryItemToken(itemToken, out var itemId))
        {
            SetCommandSyntax("give", $"Unknown item or block: {itemToken}.");
            return;
        }

        if (_lanSession != null && targetId != localId && !_lanSession.IsHost)
        {
            SetCommandStatus("Only the host can give items to another player.");
            return;
        }

        if (_lanSession == null || targetId == localId)
        {
            var added = GiveLocalInventoryItem(itemId, amount);
            if (added <= 0)
            {
                SetCommandStatus($"No inventory space for {itemId}.");
                return;
            }

            SetCommandStatus($"Gave {added}x {itemId} to {targetName}.", 4f, echoToChat: false);
            return;
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = targetId,
            Kind = LanChatKind.System,
            Text = $"{InventoryGiveSyncPrefix}{targetId}|{(byte)itemId}|{amount}|{_profile.GetDisplayUsername()}",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
        SetCommandStatus($"Requested give: {amount}x {itemId} -> {targetName}.", 4f, echoToChat: false);
    }

    private void ExecuteClearInventoryCommand(string[] commandParts)
    {
        var args = commandParts.Skip(1).ToArray();
        var localId = _lanSession?.LocalPlayerId ?? 0;
        var targetId = localId;
        var targetName = ResolvePlayerName(localId);

        // /clear <item> OR /clear <player> <item>
        if (args.Length >= 1)
        {
            if (args.Length >= 2 && TryResolvePlayerTarget(args[0], out var itemTargetId, out var itemTargetName))
            {
                var itemToken = string.Join(" ", args.Skip(1));
                if (TryResolveInventoryItemToken(itemToken, out var targetItemId))
                {
                    ExecuteClearSpecificItem(itemTargetId, itemTargetName, targetItemId);
                    return;
                }
            }

            var selfItemToken = string.Join(" ", args);
            if (TryResolveInventoryItemToken(selfItemToken, out var selfItemId))
            {
                ExecuteClearSpecificItem(localId, targetName, selfItemId);
                return;
            }

            if (!TryResolvePlayerTarget(args[0], out targetId, out targetName))
            {
                SetCommandSyntax("clear", $"Unknown player or item: {args[0]}.");
                return;
            }
        }

        if (_lanSession != null && targetId != localId && !_lanSession.IsHost)
        {
            SetCommandStatus("Only the host can clear another player's inventory.");
            return;
        }

        AddChatLine(
            $"Clear inventory for {targetName}?",
            isSystem: true,
            actionLabel: "CONFIRM",
            customActionToken: $"{InventoryClearConfirmActionPrefix}{targetId}",
            customActionStatus: $"Cleared inventory for {targetName}.",
            actionLabel2: "CANCEL",
            customActionToken2: $"{InventoryClearCancelActionPrefix}{targetId}",
            customActionStatus2: "Inventory clear canceled.");
        SetCommandStatus($"Click CONFIRM to clear {targetName}'s inventory.", 4f, echoToChat: false);
    }

    private void ExecuteClearSpecificItem(int targetId, string targetName, BlockId itemId)
    {
        var localId = _lanSession?.LocalPlayerId ?? 0;
        if (_lanSession != null && targetId != localId && !_lanSession.IsHost)
        {
            SetCommandStatus("Only the host can clear another player's inventory items.");
            return;
        }

        if (_lanSession == null || targetId == localId)
        {
            var removed = RemoveLocalInventoryItem(itemId);
            if (removed <= 0)
            {
                SetCommandStatus($"{targetName} has no {itemId} in inventory.", 4f, echoToChat: false);
                return;
            }

            SetCommandStatus($"Removed {removed}x {itemId} from {targetName}.", 4f, echoToChat: false);
            return;
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = targetId,
            Kind = LanChatKind.System,
            Text = $"{InventoryClearItemSyncPrefix}{targetId}|{(byte)itemId}|{_profile.GetDisplayUsername()}",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
        SetCommandStatus($"Requested clear of {itemId} for {targetName}.", 4f, echoToChat: false);
    }

    private void ExecuteConfirmedInventoryClear(int targetId)
    {
        var localId = _lanSession?.LocalPlayerId ?? 0;
        if (_lanSession != null && targetId != localId && !_lanSession.IsHost)
        {
            SetCommandStatus("Only the host can clear another player's inventory.");
            return;
        }

        var targetName = ResolvePlayerName(targetId);
        if (_lanSession == null || targetId == localId)
        {
            var removed = ClearLocalInventoryItems();
            var status = removed > 0
                ? $"Cleared your inventory ({removed} item{(removed == 1 ? string.Empty : "s")})."
                : "Your inventory is already empty.";
            SetCommandStatus(status);
            return;
        }

        if (!_lanSession.IsHost)
        {
            SetCommandStatus("Only the host can clear another player's inventory.");
            return;
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = targetId,
            Kind = LanChatKind.System,
            Text = $"{InventoryClearSyncPrefix}{targetId}|{_profile.GetDisplayUsername()}",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });

        SetCommandStatus($"Requested inventory clear for {targetName}.");
    }

    private int ClearLocalInventoryItems()
    {
        var removed = _inventory.ClearAll(clearGrid: true);
        _inventoryHeld = default;
        _inventoryHasHeld = false;
        _heldFrom = InventorySlotGroup.None;
        _heldIndex = -1;
        SavePlayerState();
        return removed;
    }

    private void ClearArtificerInventoryFromUi()
    {
        if (_gameMode != GameMode.Artificer)
            return;

        if (!_inventoryClearConfirmPending)
        {
            _inventoryClearConfirmPending = true;
            _inventoryClearConfirmTimer = InventoryClearConfirmSeconds;
            SetCommandStatus("Click CLEAR INVENTORY again to confirm.", 3f, echoToChat: false);
            return;
        }

        _inventoryClearConfirmPending = false;
        _inventoryClearConfirmTimer = 0f;
        var removed = ClearLocalInventoryItems();
        var status = removed > 0
            ? $"Inventory cleared ({removed} item{(removed == 1 ? string.Empty : "s")})."
            : "Inventory is already empty.";
        SetCommandStatus(status, 3f, echoToChat: false);
    }

    private void ClearSoulLootFromUi()
    {
        if (!_soulMarker.Active)
            return;

        if (!_soulLootClearConfirmPending)
        {
            _soulLootClearConfirmPending = true;
            _soulLootStatusText = "Press CLEAR SOUL again to confirm.";
            SetCommandStatus("Click CLEAR SOUL again to confirm.", 3f, echoToChat: false);
            return;
        }

        _soulLootClearConfirmPending = false;
        _soulLootStatusText = string.Empty;
        if (_soulMarker.Inventory != null)
            Array.Clear(_soulMarker.Inventory, 0, _soulMarker.Inventory.Length);
        _soulLootPendingClearRemoval = true;
        MarkPlayerStateDirty();
        SavePlayerState();
        PushLocalPersistenceSnapshotNow();
        _soulLootStatusText = "Soul cleared. Close the window to dismiss it.";
        SetCommandStatus("Soul cleared. Close the window to dismiss it.", 2.5f, echoToChat: false);
    }

    private void TakeAllSoulLootFromUi()
    {
        if (!IsViewingLocalSoul())
        {
            RequestSharedSoulTakeAll();
            return;
        }

        var moved = RecoverSoulInventoryToPlayerInventory();
        if (moved <= 0)
        {
            _soulLootStatusText = "No room to take items.";
            SetCommandStatus("No room to take items.", 2.2f, echoToChat: false);
            return;
        }

        _soulLootStatusText = $"Recovered {moved} item{(moved == 1 ? string.Empty : "s")}.";
    }

    private void HandleSoulLootSlotClick(InventorySlotGroup group, int index)
    {
        switch (group)
        {
            case InventorySlotGroup.SoulHotbar:
                if (index < 0 || index >= Inventory.HotbarSize)
                    return;
                ref var soulHotbarSlot = ref _soulMarker.Inventory[index];
                HandleSoulLootSlotSwap(ref soulHotbarSlot, group, index);
                return;
            case InventorySlotGroup.SoulGrid:
                if (index < 0 || index >= Inventory.GridSize)
                    return;
                ref var soulGridSlot = ref _soulMarker.Inventory[Inventory.HotbarSize + index];
                HandleSoulLootSlotSwap(ref soulGridSlot, group, index);
                return;
            case InventorySlotGroup.Grid:
                ref var playerGridSlot = ref _inventory.Grid[index];
                HandleSoulLootSlotSwap(ref playerGridSlot, group, index);
                return;
            case InventorySlotGroup.Hotbar:
                ref var playerHotbarSlot = ref _inventory.Hotbar[index];
                HandleSoulLootSlotSwap(ref playerHotbarSlot, group, index);
                return;
        }
    }

    private void HandleSoulLootSlotSwap(ref HotbarSlot slot, InventorySlotGroup group, int index)
    {
        if (!_inventoryHasHeld)
        {
            if (slot.Count <= 0 || slot.Id == BlockId.Air)
                return;

            _inventoryHeld = slot;
            _inventoryHasHeld = true;
            _heldFrom = group;
            _heldIndex = index;
            slot = default;
            MarkPlayerStateDirty();
            return;
        }

        var temp = slot;
        slot = _inventoryHeld;
        _inventoryHeld = temp;
        _inventoryHasHeld = _inventoryHeld.Count > 0 && _inventoryHeld.Id != BlockId.Air;
        _heldFrom = _inventoryHasHeld ? group : InventorySlotGroup.None;
        _heldIndex = _inventoryHasHeld ? index : -1;
        MarkPlayerStateDirty();
    }

    private void ReturnHeldSoulLootItemToSourceOrFallback()
    {
        if (!_inventoryHasHeld || _inventoryHeld.Id == BlockId.Air || _inventoryHeld.Count <= 0)
            return;

        switch (_heldFrom)
        {
            case InventorySlotGroup.SoulHotbar:
                _soulMarker.Inventory[_heldIndex] = _inventoryHeld;
                break;
            case InventorySlotGroup.SoulGrid:
                _soulMarker.Inventory[Inventory.HotbarSize + _heldIndex] = _inventoryHeld;
                break;
            case InventorySlotGroup.Grid:
                _inventory.Grid[_heldIndex] = _inventoryHeld;
                break;
            case InventorySlotGroup.Hotbar:
                _inventory.Hotbar[_heldIndex] = _inventoryHeld;
                break;
            default:
                var leftover = _inventory.Add(_inventoryHeld.Id, _inventoryHeld.Count);
                if (leftover > 0)
                    AddStackToSoulInventory(_inventoryHeld.Id, leftover, preferredSoulIndex: -1);
                break;
        }

        _inventoryHeld = default;
        _inventoryHasHeld = false;
        _heldFrom = InventorySlotGroup.None;
        _heldIndex = -1;
        MarkPlayerStateDirty();
    }

    private int TransferSoulSlotToInventory(int index)
    {
        if (!_soulMarker.Active || _soulMarker.Inventory == null || index < 0 || index >= _soulMarker.Inventory.Length)
            return 0;

        var slot = _soulMarker.Inventory[index];
        if (slot.Id == BlockId.Air || slot.Count <= 0)
            return 0;

        var leftover = RestoreSoulStackToPlayer(index, slot.Id, slot.Count);
        var moved = slot.Count - leftover;
        if (moved <= 0)
            return 0;

        _soulMarker.Inventory[index].Count = leftover;
        _soulMarker.Inventory[index].Id = leftover > 0 ? slot.Id : BlockId.Air;
        MarkPlayerStateDirty();
        if (!HasSoulInventoryItems())
        {
            _soulLootPendingClearRemoval = true;
            _soulLootStatusText = "Soul emptied. Close the window to dismiss it.";
        }

        SavePlayerState();
        PushLocalPersistenceSnapshotNow();
        return moved;
    }

    private int RecoverSoulInventoryToPlayerInventory()
    {
        if (!_soulMarker.Active || _soulMarker.Inventory == null)
            return 0;

        var moved = 0;
        for (var i = 0; i < _soulMarker.Inventory.Length; i++)
        {
            var slot = _soulMarker.Inventory[i];
            if (slot.Id == BlockId.Air || slot.Count <= 0)
                continue;

            var leftover = RestoreSoulStackToPlayer(i, slot.Id, slot.Count);
            moved += slot.Count - leftover;
            _soulMarker.Inventory[i].Count = leftover;
            _soulMarker.Inventory[i].Id = leftover > 0 ? slot.Id : BlockId.Air;
        }

        if (moved > 0)
        {
            MarkPlayerStateDirty();
            if (!HasSoulInventoryItems())
            {
                _soulLootPendingClearRemoval = true;
                _soulLootStatusText = "Soul emptied. Close the window to dismiss it.";
            }

            SavePlayerState();
            PushLocalPersistenceSnapshotNow();
        }
        return moved;
    }

    private void ShiftTransferSoulSlotToPlayer(int soulIndex)
    {
        if (!IsViewingLocalSoul())
        {
            RequestSharedSoulSlotTake(soulIndex);
            return;
        }

        var moved = TransferSoulSlotToInventory(soulIndex);
        _soulLootStatusText = moved > 0
            ? $"Moved {moved} item{(moved == 1 ? string.Empty : "s")}."
            : "No room to move that stack.";
    }

    private void ShiftTransferPlayerSlotToSoul(InventorySlotGroup group, int index)
    {
        var preferredSoulIndex = group == InventorySlotGroup.Hotbar ? index : Inventory.HotbarSize + index;

        if (group == InventorySlotGroup.Hotbar)
        {
            ref var hotbarSlot = ref _inventory.Hotbar[index];
            MovePlayerStackToSoul(ref hotbarSlot, preferredSoulIndex);
            return;
        }

        ref var gridSlot = ref _inventory.Grid[index];
        MovePlayerStackToSoul(ref gridSlot, preferredSoulIndex);
    }

    private void MovePlayerStackToSoul(ref HotbarSlot slot, int preferredSoulIndex)
    {
        if (slot.Id == BlockId.Air || slot.Count <= 0)
            return;

        var originalId = slot.Id;
        var originalCount = slot.Count;
        var leftover = AddStackToSoulInventory(originalId, originalCount, preferredSoulIndex);
        var moved = originalCount - leftover;
        if (moved <= 0)
        {
            _soulLootStatusText = "No room in the soul inventory.";
            return;
        }

        slot.Count = leftover;
        slot.Id = leftover > 0 ? originalId : BlockId.Air;
        _soulLootStatusText = $"Moved {moved} item{(moved == 1 ? string.Empty : "s")} to the soul.";
        MarkPlayerStateDirty();
        SavePlayerState();
        PushLocalPersistenceSnapshotNow();
    }

    private void RequestSharedSoulSlotTake(int soulIndex)
    {
        if (!CanTakeFromViewedSoul())
            return;

        if (_soulLootSourcePlayerId <= 0 || _lanSession == null || !_lanSession.IsConnected)
            return;

        if (_lanSession.IsHost)
        {
            if (TryProcessSharedSoulTakeRequest(_soulLootSourcePlayerId, _lanSession.LocalPlayerId, soulIndex, takeAll: false, out var moved, out var status))
            {
                _soulLootStatusText = moved > 0 ? status : "No room to move that stack.";
                SetCommandStatus(status, moved > 0 ? 3f : 2.5f, echoToChat: false);
            }
            else
            {
                _soulLootStatusText = status;
                SetCommandStatus(status, 2.5f, echoToChat: false);
            }

            return;
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = -1,
            Kind = LanChatKind.System,
            Text = $"{SoulLootTakeRequestPrefix}{_soulLootSourcePlayerId}|{_lanSession.LocalPlayerId}|{soulIndex}|0",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
        _soulLootStatusText = "Requesting soul transfer...";
    }

    private void RequestSharedSoulTakeAll()
    {
        if (!CanTakeFromViewedSoul())
            return;

        if (_soulLootSourcePlayerId <= 0 || _lanSession == null || !_lanSession.IsConnected)
            return;

        if (_lanSession.IsHost)
        {
            if (TryProcessSharedSoulTakeRequest(_soulLootSourcePlayerId, _lanSession.LocalPlayerId, soulIndex: -1, takeAll: true, out var moved, out var status))
            {
                _soulLootStatusText = status;
                SetCommandStatus(status, moved > 0 ? 3f : 2.5f, echoToChat: false);
            }
            else
            {
                _soulLootStatusText = status;
                SetCommandStatus(status, 2.5f, echoToChat: false);
            }

            return;
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = -1,
            Kind = LanChatKind.System,
            Text = $"{SoulLootTakeRequestPrefix}{_soulLootSourcePlayerId}|{_lanSession.LocalPlayerId}|-1|1",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
        _soulLootStatusText = "Requesting soul transfer...";
    }

    private bool TryProcessSharedSoulTakeRequest(int ownerPlayerId, int takerPlayerId, int soulIndex, bool takeAll, out int moved, out string status)
    {
        moved = 0;
        status = "Shared soul transfer failed.";
        if (_lanSession == null || !_lanSession.IsHost)
            return false;
        if (!_sharedSoulAccessEnabled)
        {
            status = "Shared soul access is disabled.";
            return false;
        }

        if (!TryGetSoulOwnerState(ownerPlayerId, out var ownerState, out var ownerSnapshot))
        {
            status = "That soul is no longer available.";
            return false;
        }

        var soulInventory = ownerState.SoulInventory ?? Array.Empty<HotbarSlot>();
        if (!HasAnySoulInventoryItems(soulInventory))
        {
            status = "The soul carries nothing.";
            return false;
        }

        if (takeAll)
        {
            for (var i = 0; i < soulInventory.Length; i++)
            {
                var slot = soulInventory[i];
                if (slot.Id == BlockId.Air || slot.Count <= 0)
                    continue;

                var leftover = TryTransferSoulStackToPlayer(ownerPlayerId, takerPlayerId, i, slot.Id, slot.Count);
                var transferred = slot.Count - leftover;
                if (transferred <= 0)
                    continue;

                moved += transferred;
                soulInventory[i].Count = leftover;
                soulInventory[i].Id = leftover > 0 ? slot.Id : BlockId.Air;
            }
        }
        else
        {
            if (soulIndex < 0 || soulIndex >= soulInventory.Length)
            {
                status = "That soul slot is not valid.";
                return false;
            }

            var slot = soulInventory[soulIndex];
            if (slot.Id == BlockId.Air || slot.Count <= 0)
            {
                status = "That soul slot is empty.";
                return false;
            }

            var leftover = TryTransferSoulStackToPlayer(ownerPlayerId, takerPlayerId, soulIndex, slot.Id, slot.Count);
            moved = slot.Count - leftover;
            soulInventory[soulIndex].Count = leftover;
            soulInventory[soulIndex].Id = leftover > 0 ? slot.Id : BlockId.Air;
        }

        ownerState.SoulInventory = soulInventory;
        if (!HasAnySoulInventoryItems(ownerState.SoulInventory))
            ownerState.HasSoulMarker = false;

        PersistSoulOwnerState(ownerPlayerId, ownerState, ownerSnapshot);

        if (moved <= 0)
        {
            status = takeAll ? "No room to take items." : "No room to move that stack.";
            return false;
        }

        var ownerName = ResolvePlayerName(ownerPlayerId);
        status = takeAll
            ? $"Recovered {moved} item{(moved == 1 ? string.Empty : "s")} from {ownerName}'s soul."
            : $"Moved {moved} item{(moved == 1 ? string.Empty : "s")} from {ownerName}'s soul.";
        return true;
    }

    private int TryTransferSoulStackToPlayer(int ownerPlayerId, int takerPlayerId, int soulIndex, BlockId id, int amount)
    {
        if (_lanSession == null)
            return amount;

        if (takerPlayerId == _lanSession.LocalPlayerId)
        {
            var leftover = RestoreSoulStackToPlayer(soulIndex, id, amount);
            if (leftover < amount)
            {
                MarkPlayerStateDirty();
                SavePlayerState();
                PushLocalPersistenceSnapshotNow();
            }

            return leftover;
        }

        if (!TryGetRemotePlayerStateSnapshot(takerPlayerId, out var takerState, out var takerSnapshot))
            return amount;

        var remoteLeftover = RestoreSoulStackToPlayerState(takerState, soulIndex, id, amount);
        PersistRemotePlayerState(takerPlayerId, takerState, takerSnapshot, broadcastToObservers: false, sendRestoreToPlayer: true);
        return remoteLeftover;
    }

    private bool TryGetSoulOwnerState(int ownerPlayerId, out PlayerWorldState state, out LanPlayerPersistenceSnapshot snapshot)
    {
        snapshot = default;
        if (_lanSession != null && ownerPlayerId == _lanSession.LocalPlayerId)
        {
            state = CapturePlayerState();
            state.Username = _profile.GetDisplayUsername();
            return true;
        }

        return TryGetRemotePlayerStateSnapshot(ownerPlayerId, out state, out snapshot);
    }

    private bool TryGetRemotePlayerStateSnapshot(int playerId, out PlayerWorldState state, out LanPlayerPersistenceSnapshot snapshot)
    {
        state = default!;
        snapshot = default;
        if (!_latestRemotePersistenceByPlayerId.TryGetValue(playerId, out snapshot))
            return false;

        return PlayerWorldState.TryFromCompressedBytes(snapshot.Payload ?? Array.Empty<byte>(), _log, out state);
    }

    private void PersistSoulOwnerState(int ownerPlayerId, PlayerWorldState state, LanPlayerPersistenceSnapshot sourceSnapshot)
    {
        if (_lanSession == null)
            return;

        if (ownerPlayerId == _lanSession.LocalPlayerId)
        {
            _soulMarker.Active = state.HasSoulMarker && HasAnySoulInventoryItems(state.SoulInventory);
            _soulMarker.Inventory = state.SoulInventory;
            if (!_soulMarker.Active)
                _soulLootPendingClearRemoval = true;
            MarkPlayerStateDirty();
            SavePlayerState();
            PushLocalPersistenceSnapshotNow();
            return;
        }

        PersistRemotePlayerState(ownerPlayerId, state, sourceSnapshot, broadcastToObservers: true, sendRestoreToPlayer: true);
    }

    private void PersistRemotePlayerState(int playerId, PlayerWorldState state, LanPlayerPersistenceSnapshot sourceSnapshot, bool broadcastToObservers, bool sendRestoreToPlayer)
    {
        if (_lanSession == null)
            return;

        var payload = state.ToCompressedBytes(_log);
        if (payload.Length == 0)
            return;

        var normalized = new LanPlayerPersistenceSnapshot
        {
            PlayerId = playerId,
            Username = string.IsNullOrWhiteSpace(state.Username) ? sourceSnapshot.Username : state.Username,
            Payload = payload,
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        };

        _latestRemotePersistenceByPlayerId[playerId] = normalized;
        RefreshRemoteSoulState(playerId, state);
        if (sendRestoreToPlayer)
            _lanSession.SendPersistenceRestore(playerId, normalized);
        if (broadcastToObservers)
            _lanSession.SendPersistenceSnapshot(normalized);
        TryFlushRemotePersistenceSnapshot(playerId, normalized, force: true);
    }

    private int RestoreSoulStackToPlayerState(PlayerWorldState state, int soulIndex, BlockId id, int amount)
    {
        state.Hotbar = EnsureSlotArrayLength(state.Hotbar, Inventory.HotbarSize);
        state.InventoryGrid = EnsureSlotArrayLength(state.InventoryGrid, Inventory.GridSize);

        var leftover = amount;
        if (soulIndex < Inventory.HotbarSize)
            leftover = FillSpecificSlot(ref state.Hotbar[soulIndex], id, leftover);
        else
            leftover = FillSpecificSlot(ref state.InventoryGrid[soulIndex - Inventory.HotbarSize], id, leftover);

        if (leftover > 0)
        {
            for (var i = 0; i < state.Hotbar.Length && leftover > 0; i++)
                leftover = FillSpecificSlot(ref state.Hotbar[i], id, leftover);
            for (var i = 0; i < state.InventoryGrid.Length && leftover > 0; i++)
                leftover = FillSpecificSlot(ref state.InventoryGrid[i], id, leftover);
        }

        return leftover;
    }

    private static HotbarSlot[] EnsureSlotArrayLength(HotbarSlot[]? slots, int length)
    {
        var output = new HotbarSlot[length];
        if (slots != null)
            Array.Copy(slots, output, Math.Min(slots.Length, output.Length));
        return output;
    }

    private int RestoreSoulStackToPlayer(int soulIndex, BlockId id, int amount)
    {
        var leftover = amount;
        if (soulIndex < Inventory.HotbarSize)
            leftover = FillSpecificSlot(ref _inventory.Hotbar[soulIndex], id, leftover);
        else
            leftover = FillSpecificSlot(ref _inventory.Grid[soulIndex - Inventory.HotbarSize], id, leftover);

        if (leftover > 0)
            leftover = _inventory.Add(id, leftover);
        return leftover;
    }

    private int AddStackToSoulInventory(BlockId id, int amount, int preferredSoulIndex)
    {
        if (_soulMarker.Inventory == null)
            _soulMarker.Inventory = CloneSoulInventorySlots(null);

        var leftover = amount;
        if (preferredSoulIndex >= 0 && preferredSoulIndex < _soulMarker.Inventory.Length)
            leftover = FillSpecificSlot(ref _soulMarker.Inventory[preferredSoulIndex], id, leftover);

        for (var i = 0; i < _soulMarker.Inventory.Length && leftover > 0; i++)
        {
            if (i == preferredSoulIndex)
                continue;
            leftover = FillSpecificSlot(ref _soulMarker.Inventory[i], id, leftover);
        }

        return leftover;
    }

    private int FillSpecificSlot(ref HotbarSlot slot, BlockId id, int amount)
    {
        if (amount <= 0)
            return 0;

        var max = GetSoulLootMaxStack(id);
        if (slot.Count > 0 && slot.Id != id)
            return amount;

        if (slot.Count <= 0 || slot.Id == BlockId.Air)
        {
            var add = Math.Min(max, amount);
            slot.Id = id;
            slot.Count = add;
            return amount - add;
        }

        var room = Math.Max(0, max - slot.Count);
        if (room <= 0)
            return amount;

        var stacked = Math.Min(room, amount);
        slot.Count += stacked;
        return amount - stacked;
    }

    private static int GetSoulLootMaxStack(BlockId id)
    {
        return id is BlockId.CinderbranchStaff or BlockId.StormreedStaff ? 1 : 60;
    }

    private void OpenSoulLootGui()
    {
        var canOpen = IsViewingLocalSoul()
            ? CanInteractWithSoul()
            : _sharedSoulAccessEnabled && HasViewedSoulInventoryItems();
        if (!canOpen)
        {
            if ((IsViewingLocalSoul() && _soulMarker.Active && HasSoulInventoryItems())
                || (!IsViewingLocalSoul() && HasViewedSoulInventoryItems()))
                SetCommandStatus("You cannot interact with this soul.", 2.2f, echoToChat: false);
            else
                SetCommandStatus("The soul carries nothing.", 2.2f, echoToChat: false);
            return;
        }

        _soulLootOpen = true;
        _inventoryOpen = true;
        _soulLootClearConfirmPending = false;
        _soulLootPendingClearRemoval = false;
        _soulLootTitleText = GetViewedSoulDisplayTitle();
        _soulLootStatusText = IsViewingLocalSoul()
            ? string.Empty
            : "Shared soul access enabled. Click a soul slot or TAKE ALL to pull items.";
        UpdateSoulLootLayout();
    }

    private int GiveLocalInventoryItem(BlockId itemId, int amount)
    {
        var leftover = _inventory.Add(itemId, Math.Max(1, amount));
        var added = Math.Max(0, amount - leftover);
        if (added > 0)
            SavePlayerState();
        return added;
    }

    private bool TryHandoffSelectedItemDirect(int targetPlayerId, int requestedAmount, out string status)
    {
        status = "Unable to hand off that item.";
        if (!_giveItemsEnabled)
        {
            status = "Item giving is disabled in this world.";
            return false;
        }

        if (_lanSession == null || !_lanSession.IsConnected)
        {
            status = "Direct handoff requires multiplayer.";
            return false;
        }

        var itemId = _inventory.SelectedId;
        if (itemId == BlockId.Air || _inventory.SelectedCount <= 0 || requestedAmount <= 0)
        {
            status = "No item selected to hand off.";
            return false;
        }

        requestedAmount = Math.Min(requestedAmount, _inventory.SelectedCount);
        if (targetPlayerId == _lanSession.LocalPlayerId)
        {
            status = "You already have that item selected.";
            return false;
        }

        if (_lanSession.IsHost)
        {
            return TryProcessDirectPlayerHandoff(_lanSession.LocalPlayerId, targetPlayerId, itemId, requestedAmount, out _, out status);
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = 0,
            Kind = LanChatKind.System,
            Text = $"{InventoryHandoffRequestPrefix}{targetPlayerId}|{(byte)itemId}|{requestedAmount}",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
        status = $"Handing {requestedAmount}x {itemId} to {ResolvePlayerName(targetPlayerId)}...";
        return true;
    }

    private bool TryProcessDirectPlayerHandoff(int senderPlayerId, int targetPlayerId, BlockId itemId, int requestedAmount, out int moved, out string status)
    {
        moved = 0;
        status = "Item handoff failed.";
        if (_lanSession == null || !_lanSession.IsHost)
            return false;
        if (!_giveItemsEnabled)
        {
            status = "Item giving is disabled in this world.";
            return false;
        }

        requestedAmount = Math.Max(1, requestedAmount);
        if (itemId == BlockId.Air || requestedAmount <= 0)
        {
            status = "No valid item was selected.";
            return false;
        }

        var senderName = ResolvePlayerName(senderPlayerId);
        var targetName = ResolvePlayerName(targetPlayerId);
        var senderAvailable = senderPlayerId == _lanSession.LocalPlayerId
            ? (_inventory.SelectedId == itemId ? _inventory.SelectedCount : 0)
            : GetRemotePlayerItemCount(senderPlayerId, itemId);
        if (senderAvailable <= 0)
        {
            status = $"{senderName} has no {itemId} to hand off.";
            return false;
        }

        var transferAmount = Math.Min(requestedAmount, senderAvailable);
        if (transferAmount <= 0)
        {
            status = $"{senderName} has no {itemId} to hand off.";
            return false;
        }

        if (targetPlayerId == _lanSession.LocalPlayerId)
        {
            moved = GiveLocalInventoryItem(itemId, transferAmount);
        }
        else
        {
            moved = GiveRemoteInventoryItem(targetPlayerId, itemId, transferAmount);
        }

        if (moved <= 0)
        {
            status = $"{targetName}'s inventory is full.";
            return false;
        }

        if (senderPlayerId == _lanSession.LocalPlayerId)
        {
            if (!TryConsumeSelectedForWorldDrop(moved, out _))
            {
                status = "Your held item changed before the handoff completed.";
                return false;
            }

            SavePlayerState();
            PushLocalPersistenceSnapshotNow();
        }
        else if (!TryRemoveRemotePlayerItems(senderPlayerId, itemId, moved))
        {
            status = $"{senderName}'s inventory changed before the handoff completed.";
            return false;
        }

        if (targetPlayerId != _lanSession.LocalPlayerId)
        {
            _lanSession.SendChat(new LanChatMessage
            {
                FromPlayerId = _lanSession.LocalPlayerId,
                ToPlayerId = targetPlayerId,
                Kind = LanChatKind.System,
                Text = $"{senderName} gave you {moved}x {itemId}.",
                TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            });
        }

        status = $"GAVE {targetName.ToUpperInvariant()} {moved}x {itemId}";
        return true;
    }

    private int GetRemotePlayerItemCount(int playerId, BlockId itemId)
    {
        if (!TryGetRemotePlayerStateSnapshot(playerId, out var state, out _))
            return 0;

        return CountItemInSlots(state.Hotbar, itemId) + CountItemInSlots(state.InventoryGrid, itemId);
    }

    private int GiveRemoteInventoryItem(int playerId, BlockId itemId, int amount)
    {
        if (!TryGetRemotePlayerStateSnapshot(playerId, out var state, out var snapshot))
            return 0;

        var added = GiveItemToPlayerState(state, itemId, amount);
        if (added <= 0)
            return 0;

        PersistRemotePlayerState(playerId, state, snapshot, broadcastToObservers: false, sendRestoreToPlayer: true);
        return added;
    }

    private bool TryRemoveRemotePlayerItems(int playerId, BlockId itemId, int amount)
    {
        if (!TryGetRemotePlayerStateSnapshot(playerId, out var state, out var snapshot))
            return false;

        var removed = RemoveItemAmountFromPlayerState(state, itemId, amount);
        if (removed <= 0)
            return false;

        PersistRemotePlayerState(playerId, state, snapshot, broadcastToObservers: true, sendRestoreToPlayer: true);
        return removed == amount;
    }

    private static int CountItemInSlots(HotbarSlot[]? slots, BlockId itemId)
    {
        if (slots == null || itemId == BlockId.Air)
            return 0;

        var count = 0;
        for (var i = 0; i < slots.Length; i++)
        {
            if (slots[i].Id == itemId && slots[i].Count > 0)
                count += slots[i].Count;
        }

        return count;
    }

    private int GiveItemToPlayerState(PlayerWorldState state, BlockId itemId, int amount)
    {
        state.Hotbar = EnsureSlotArrayLength(state.Hotbar, Inventory.HotbarSize);
        state.InventoryGrid = EnsureSlotArrayLength(state.InventoryGrid, Inventory.GridSize);

        var leftover = amount;
        for (var i = 0; i < state.Hotbar.Length && leftover > 0; i++)
            leftover = FillSpecificSlot(ref state.Hotbar[i], itemId, leftover);
        for (var i = 0; i < state.InventoryGrid.Length && leftover > 0; i++)
            leftover = FillSpecificSlot(ref state.InventoryGrid[i], itemId, leftover);

        return Math.Max(0, amount - leftover);
    }

    private static int RemoveItemAmountFromSlots(HotbarSlot[]? slots, BlockId itemId, int amount)
    {
        if (slots == null || itemId == BlockId.Air || amount <= 0)
            return 0;

        var removed = 0;
        for (var i = 0; i < slots.Length && removed < amount; i++)
        {
            if (slots[i].Id != itemId || slots[i].Count <= 0)
                continue;

            var take = Math.Min(slots[i].Count, amount - removed);
            slots[i].Count -= take;
            removed += take;
            if (slots[i].Count <= 0)
            {
                slots[i].Id = BlockId.Air;
                slots[i].Count = 0;
            }
        }

        return removed;
    }

    private static int RemoveItemAmountFromPlayerState(PlayerWorldState state, BlockId itemId, int amount)
    {
        state.Hotbar = EnsureSlotArrayLength(state.Hotbar, Inventory.HotbarSize);
        state.InventoryGrid = EnsureSlotArrayLength(state.InventoryGrid, Inventory.GridSize);
        var removed = RemoveItemAmountFromSlots(state.Hotbar, itemId, amount);
        if (removed < amount)
            removed += RemoveItemAmountFromSlots(state.InventoryGrid, itemId, amount - removed);
        return removed;
    }

    private int RemoveLocalInventoryItem(BlockId itemId)
    {
        if (itemId == BlockId.Air)
            return 0;

        var removed = 0;
        removed += RemoveItemFromSlots(_inventory.Hotbar, itemId);
        if (_inventory.Mode != GameMode.Artificer)
            removed += RemoveItemFromSlots(_inventory.Grid, itemId);

        if (_inventoryHasHeld && _inventoryHeld.Id == itemId && _inventoryHeld.Count > 0)
        {
            removed += _inventoryHeld.Count;
            _inventoryHeld = default;
            _inventoryHasHeld = false;
            _heldFrom = InventorySlotGroup.None;
            _heldIndex = -1;
        }

        if (removed > 0)
            SavePlayerState();

        return removed;
    }

    private static int RemoveItemFromSlots(HotbarSlot[] slots, BlockId itemId)
    {
        var removed = 0;
        for (var i = 0; i < slots.Length; i++)
        {
            if (slots[i].Id != itemId || slots[i].Count <= 0)
                continue;

            removed += slots[i].Count;
            slots[i].Id = BlockId.Air;
            slots[i].Count = 0;
        }

        return removed;
    }

    private void ExecutePosCommand(string[] commandParts)
    {
        var targetId = _lanSession?.LocalPlayerId ?? 0;
        if (commandParts.Length >= 2 && !TryResolvePlayerTarget(commandParts[1], out targetId, out _))
        {
            SetCommandStatus($"Player not found: {commandParts[1]}");
            return;
        }

        if (!TryGetKnownPlayerPose(targetId, out var position, out _, out _))
        {
            SetCommandStatus($"Unable to resolve position for {ResolvePlayerName(targetId)}.");
            return;
        }

        var x = (int)MathF.Floor(position.X);
        var y = (int)MathF.Floor(position.Y);
        var z = (int)MathF.Floor(position.Z);
        var targetName = ResolvePlayerName(targetId);
        var coords = $"{x} {y} {z}";
        AddChatLine(
            $"{targetName} position: {coords}",
            isSystem: true,
            hoverText: "Click COPY to copy coordinates.",
            copyText: coords,
            actionLabel: "COPY");
        SetCommandStatus($"{targetName} is at {coords}.", 4f, echoToChat: false);
    }

    private void ExecuteBroadcastCommand(string[] commandParts)
    {
        if (commandParts.Length < 2)
        {
            SetCommandSyntax("broadcast");
            return;
        }

        var text = string.Join(" ", commandParts.Skip(1)).Trim();
        if (string.IsNullOrWhiteSpace(text))
        {
            SetCommandSyntax("broadcast");
            return;
        }

        var line = $"[BROADCAST] {text}";

        if (_lanSession != null && _lanSession.IsConnected)
        {
            _lanSession.SendChat(new LanChatMessage
            {
                FromPlayerId = _lanSession.LocalPlayerId,
                ToPlayerId = -1,
                Kind = LanChatKind.System,
                Text = line,
                TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            });
            SetCommandStatus("Broadcast sent.", 3f, echoToChat: false);
            return;
        }

        AddChatLine(line, isSystem: true);
        SetCommandStatus("Broadcast sent.", 3f, echoToChat: false);
    }

    private enum PlayerSetStatKind
    {
        Health,
        Hunger,
        Attunement
    }

    private void ExecuteSetStatCommand(string[] commandParts)
    {
        if (commandParts.Length < 4)
        {
            SetCommandSyntax("set");
            return;
        }

        if (!TryParseSetStatKind(commandParts[1], out var statKind))
        {
            SetCommandSyntax("set", "Stat must be health, hunger, or attunement.");
            return;
        }

        if (!TryResolvePlayerTarget(commandParts[2], out var targetId, out var targetName))
        {
            SetCommandStatus($"Player not found: {commandParts[2]}");
            return;
        }

        if (!TryNormalizeSetStatValue(statKind, commandParts[3], out var normalizedValue, out var displayValue, out var error))
        {
            SetCommandSyntax("set", error, echoToChat: false);
            return;
        }

        ApplyTargetedPlayerStatChange(statKind, targetId, targetName, normalizedValue, displayValue);
    }

    private void ExecuteKillCommand(string[] commandParts)
    {
        if (commandParts.Length < 2)
        {
            var localId = _lanSession?.LocalPlayerId ?? 0;
            ApplyKillToTarget(localId, ResolvePlayerName(localId));
            return;
        }

        var killed = new List<string>();
        var unresolved = new List<string>();
        var index = 1;
        while (index < commandParts.Length)
        {
            var matched = false;
            for (var take = commandParts.Length - index; take >= 1; take--)
            {
                var token = string.Join(" ", commandParts.Skip(index).Take(take));
                if (!TryResolvePlayerTarget(token, out var targetId, out var targetName))
                    continue;

                if (ApplyKillToTarget(targetId, targetName))
                    killed.Add(targetName);
                index += take;
                matched = true;
                break;
            }

            if (matched)
                continue;

            unresolved.Add(commandParts[index]);
            index++;
        }

        if (unresolved.Count > 0)
            SetCommandStatus($"Player not found: {string.Join(", ", unresolved)}", 4f, echoToChat: false);
        else if (killed.Count > 0)
            SetCommandStatus(killed.Count == 1 ? $"Killed {killed[0]}." : $"Killed {killed.Count} players.", 4f, echoToChat: false);
    }

    private bool ApplyKillToTarget(int targetId, string targetName)
    {
        var localId = _lanSession?.LocalPlayerId ?? 0;
        targetName = string.IsNullOrWhiteSpace(targetName) ? ResolvePlayerName(targetId) : targetName.Trim();

        if (_lanSession != null && targetId != localId && !_lanSession.IsHost)
        {
            SetCommandStatus("Only the host can kill another player.", 4f, echoToChat: false);
            return false;
        }

        if (_lanSession == null || targetId == localId)
        {
            ApplyLocalPlayerStatChange(PlayerSetStatKind.Health, 0f, saveImmediately: true);
            SetCommandStatus($"Killed {targetName}.", 4f, echoToChat: false);
            return true;
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = targetId,
            Kind = LanChatKind.System,
            Text = $"{PlayerStatSyncPrefix}{targetId}|{GetSetStatToken(PlayerSetStatKind.Health)}|0|{_profile.GetDisplayUsername()}",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
        _remoteHealthByPlayerId[targetId] = 0;
        return true;
    }

    private void ExecuteReloadHudCommand(string[] _)
    {
        try
        {
            _healthHudTexture = TryReloadOptionalTexture("textures/menu/GUIS/health.png");
            _hungerHudTexture = TryReloadOptionalTexture("textures/menu/GUIS/hunger.png");
            _sigilHudTexture = TryReloadOptionalTexture("textures/menu/GUIS/sigil_balance_mockup.png");
            SetCommandStatus("HUD textures reloaded from disk.");
        }
        catch (Exception ex)
        {
            SetCommandStatus($"HUD reload failed: {ex.Message}");
        }
    }

    private static bool TryParseSetStatKind(string raw, out PlayerSetStatKind statKind)
    {
        statKind = PlayerSetStatKind.Health;
        var token = (raw ?? string.Empty).Trim().ToLowerInvariant();
        return token switch
        {
            "health" or "hp" => (statKind = PlayerSetStatKind.Health) == PlayerSetStatKind.Health,
            "hunger" or "food" => (statKind = PlayerSetStatKind.Hunger) == PlayerSetStatKind.Hunger,
            "attunement" or "attune" or "atonement" => (statKind = PlayerSetStatKind.Attunement) == PlayerSetStatKind.Attunement,
            _ => false
        };
    }

    private static bool TryNormalizeSetStatValue(PlayerSetStatKind statKind, string rawValue, out float normalizedValue, out string displayValue, out string error)
    {
        normalizedValue = 0f;
        displayValue = "0";
        error = string.Empty;

        switch (statKind)
        {
            case PlayerSetStatKind.Health:
                if (!int.TryParse(rawValue, NumberStyles.Integer, CultureInfo.InvariantCulture, out var health))
                {
                    error = "Health value must be a whole number.";
                    return false;
                }

                health = Math.Clamp(health, 0, SurvivalVitals.MaxHealth);
                normalizedValue = health;
                displayValue = health.ToString(CultureInfo.InvariantCulture);
                return true;

            case PlayerSetStatKind.Hunger:
                if (!int.TryParse(rawValue, NumberStyles.Integer, CultureInfo.InvariantCulture, out var hunger))
                {
                    error = "Hunger value must be a whole number.";
                    return false;
                }

                hunger = Math.Clamp(hunger, 0, SurvivalVitals.MaxHunger);
                normalizedValue = hunger;
                displayValue = hunger.ToString(CultureInfo.InvariantCulture);
                return true;

            case PlayerSetStatKind.Attunement:
                if (!float.TryParse(rawValue, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var attunement))
                {
                    error = "Attunement value must be a number.";
                    return false;
                }

                var fraction = attunement > 1f ? attunement / 100f : attunement;
                fraction = Math.Clamp(fraction, 0f, 1f);
                normalizedValue = fraction;
                displayValue = MathF.Round(fraction * 100f).ToString("0", CultureInfo.InvariantCulture) + "%";
                return true;

            default:
                error = "Unsupported stat.";
                return false;
        }
    }

    private void ApplyTargetedPlayerStatChange(PlayerSetStatKind statKind, int targetId, string targetName, float normalizedValue, string displayValue)
    {
        var localId = _lanSession?.LocalPlayerId ?? 0;
        if (_lanSession == null || targetId == localId)
        {
            ApplyLocalPlayerStatChange(statKind, normalizedValue, saveImmediately: true);
            SetCommandStatus($"Set {targetName}'s {GetSetStatDisplayName(statKind)} to {displayValue}.", 4f, echoToChat: false);
            return;
        }

        if (!_lanSession.IsHost)
        {
            SetCommandStatus($"Only the host can change another player's {GetSetStatDisplayName(statKind)}.");
            return;
        }

        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = targetId,
            Kind = LanChatKind.System,
            Text = $"{PlayerStatSyncPrefix}{targetId}|{GetSetStatToken(statKind)}|{normalizedValue.ToString(CultureInfo.InvariantCulture)}|{_profile.GetDisplayUsername()}",
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });

        switch (statKind)
        {
            case PlayerSetStatKind.Health:
                _remoteHealthByPlayerId[targetId] = Math.Clamp((int)MathF.Round(normalizedValue), 0, SurvivalVitals.MaxHealth);
                break;
            case PlayerSetStatKind.Hunger:
                _remoteHungerByPlayerId[targetId] = Math.Clamp((int)MathF.Round(normalizedValue), 0, SurvivalVitals.MaxHunger);
                break;
            case PlayerSetStatKind.Attunement:
                _remoteSigilAtonementByPlayerId[targetId] = Math.Clamp(normalizedValue, 0f, 1f);
                break;
        }

        SetCommandStatus($"Set {targetName}'s {GetSetStatDisplayName(statKind)} to {displayValue}.", 4f, echoToChat: false);
    }

    private void ApplyLocalPlayerStatChange(PlayerSetStatKind statKind, float normalizedValue, bool saveImmediately)
    {
        switch (statKind)
        {
            case PlayerSetStatKind.Health:
            {
                var newHealth = Math.Clamp((int)MathF.Round(normalizedValue), 0, SurvivalVitals.MaxHealth);
                _survivalVitals.Load(newHealth, _survivalVitals.Hunger);
                if (newHealth > 0)
                    _survivalRespawnPending = false;
                else if (_gameMode == GameMode.Veilwalker)
                    BeginVeilwalkerRespawn();
                break;
            }
            case PlayerSetStatKind.Hunger:
            {
                var newHunger = Math.Clamp((int)MathF.Round(normalizedValue), 0, SurvivalVitals.MaxHunger);
                _survivalVitals.Load(_survivalVitals.Health, newHunger);
                break;
            }
            case PlayerSetStatKind.Attunement:
                _sigilPositiveTargetFraction = Math.Clamp(normalizedValue, 0f, 1f);
                break;
        }

        MarkPlayerStateDirty();
        if (saveImmediately)
            SavePlayerState();
    }

    private static string GetSetStatToken(PlayerSetStatKind statKind)
    {
        return statKind switch
        {
            PlayerSetStatKind.Health => "health",
            PlayerSetStatKind.Hunger => "hunger",
            PlayerSetStatKind.Attunement => "attunement",
            _ => "health"
        };
    }

    private static string GetSetStatDisplayName(PlayerSetStatKind statKind)
    {
        return statKind switch
        {
            PlayerSetStatKind.Health => "health",
            PlayerSetStatKind.Hunger => "hunger",
            PlayerSetStatKind.Attunement => "attunement",
            _ => "stat"
        };
    }

    private void ExecuteSigilCommand(string[] commandParts)
    {
        if (!_sigilPowerEnabled)
        {
            SetCommandStatus("Sigil power is disabled in this world. Use /rule sigil enabled to turn it back on.", 4f, echoToChat: false);
            return;
        }

        if (commandParts.Length < 2)
        {
            SetCommandSyntax("sigil", echoToChat: false);
            return;
        }

        switch (commandParts[1].ToLowerInvariant())
        {
            case "empty":
            case "clear":
                _sigilPositiveTargetFraction = 0f;
                _sigilNegativeTargetFraction = 0f;
                MarkPlayerStateDirty();
                SavePlayerState();
                SetCommandStatus("Sigil meter reset to EMPTY.", 3f, echoToChat: false);
                return;

            case "positive":
                if (commandParts.Length < 3 || !TryParseSigilPercent(commandParts[2], out var positiveValue))
                {
                    SetCommandSyntax("sigil", "Sigil positive syntax is invalid.", echoToChat: false);
                    return;
                }

                _sigilPositiveTargetFraction = positiveValue;
                MarkPlayerStateDirty();
                SavePlayerState();
                SetCommandStatus($"Sigil {SigilPositiveLabel} target set to {MathF.Round(_sigilPositiveTargetFraction * 100f):0}%.", 3f, echoToChat: false);
                return;

            case "negative":
                if (commandParts.Length < 3 || !TryParseSigilPercent(commandParts[2], out var negativeValue))
                {
                    SetCommandSyntax("sigil", "Sigil negative syntax is invalid.", echoToChat: false);
                    return;
                }

                _sigilNegativeTargetFraction = negativeValue;
                MarkPlayerStateDirty();
                SavePlayerState();
                SetCommandStatus($"Sigil {SigilNegativeLabel} target set to {MathF.Round(_sigilNegativeTargetFraction * 100f):0}%.", 3f, echoToChat: false);
                return;

            case "set":
                if (commandParts.Length < 4
                    || !TryParseSigilPercent(commandParts[2], out var positiveSetValue)
                    || !TryParseSigilPercent(commandParts[3], out var negativeSetValue))
                {
                    SetCommandSyntax("sigil", "Sigil set syntax is invalid.", echoToChat: false);
                    return;
                }

                _sigilPositiveTargetFraction = positiveSetValue;
                _sigilNegativeTargetFraction = negativeSetValue;
                MarkPlayerStateDirty();
                SavePlayerState();
                SetCommandStatus(
                    $"Sigil set: {SigilPositiveLabel} {MathF.Round(_sigilPositiveTargetFraction * 100f):0}% | {SigilNegativeLabel} {MathF.Round(_sigilNegativeTargetFraction * 100f):0}%.",
                    4f,
                    echoToChat: false);
                return;
        }

        SetCommandSyntax("sigil", echoToChat: false);
    }

    private static bool TryParseSigilPercent(string token, out float fraction)
    {
        fraction = 0f;
        if (string.IsNullOrWhiteSpace(token))
            return false;

        token = token.Trim();
        if (token.EndsWith('%'))
            token = token[..^1];

        if (!float.TryParse(token, NumberStyles.Float, CultureInfo.InvariantCulture, out var percent))
            return false;

        fraction = Math.Clamp(percent / 100f, 0f, 1f);
        return true;
    }

    private void ExecuteInvCommand(string[] commandParts)
    {
        if (!HasOperatorPermissions())
        {
            SetCommandStatus("Inventory viewing requires operator permissions.");
            return;
        }

        var args = commandParts.Skip(1).ToArray();
        var localId = _lanSession?.LocalPlayerId ?? 0;

        // /inv clear - clear inventory view
        if (args.Length == 1 && args[0].Equals("clear", StringComparison.OrdinalIgnoreCase))
        {
            ClearInventoryView();
            SetCommandStatus("Inventory view cleared.", 3f, echoToChat: false);
            return;
        }

        // /inv [player] - view player's inventory
        int targetId = localId;
        string targetName = ResolvePlayerName(localId);

        if (args.Length >= 1)
        {
            if (!TryResolvePlayerTarget(args[0], out targetId, out targetName))
            {
                SetCommandStatus($"Player not found: {args[0]}");
                return;
            }
        }
        else if (_veilseerSpectateTargetPlayerId >= 0)
        {
            targetId = _veilseerSpectateTargetPlayerId;
            targetName = ResolvePlayerName(targetId);
        }

        // Start spectating the target player to view their inventory
        if (targetId == localId)
        {
            if (HasActiveRemoteInventoryView())
                ClearInventoryView();

            // View own inventory (open regular inventory UI)
            if (!_inventoryOpen)
            {
                _inventoryOpen = true;
                SetCommandStatus("Opened your inventory.", 3f, echoToChat: false);
            }
            else
            {
                SetCommandStatus("Your inventory is already open.", 3f, echoToChat: false);
            }
        }
        else
        {
            // Start spectating remote player to view their inventory
            if (_lanSession == null)
            {
                SetCommandStatus("Inventory viewing requires multiplayer session.");
                return;
            }

            // Check if target is Veilseer (can't view Veilseer inventory)
            if (_remoteIsVeilseer.TryGetValue(targetId, out var isVeilseer) && isVeilseer)
            {
                SetCommandStatus($"Cannot view {targetName}'s inventory - Veilseer is hidden.");
                return;
            }

            // Start spectating and request inventory view
            StartSpectatingPlayer(targetId);
            RequestInventoryView(targetId, openUi: true);
            SetCommandStatus($"Now viewing {targetName}'s inventory.", 3f, echoToChat: false);
        }
    }

    private void ClearInventoryView(bool preserveSpectate = false)
    {
        var targetId = _currentLiveInventoryTarget;

        // Clear current inventory view target
        if (_lanSession != null && _lanSession.IsConnected)
        {
            var localId = _lanSession.LocalPlayerId;
            if (_inventoryViewTargetByViewer.TryGetValue(localId, out var requestedTargetId))
            {
                _inventoryViewTargetByViewer.Remove(localId);
                if (HasOperatorPermissions())
                {
                    _lanSession.SendChat(new LanChatMessage
                    {
                        FromPlayerId = localId,
                        ToPlayerId = -1,
                        Kind = LanChatKind.System,
                        Text = InventoryViewClosePrefix + requestedTargetId,
                        TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                    });
                }
            }
        }

        ResetLiveInventoryMirrorState(targetId);

        // Stop spectating if currently spectating for inventory viewing
        if (!preserveSpectate && _veilseerSpectateTargetPlayerId >= 0)
        {
            StopSpectatingPlayer();
        }

        _currentLiveInventoryTarget = -1;

        // Close inventory UI if open
        if (_inventoryOpen)
        {
            _inventoryOpen = false;
        }
    }

    private void StartSpectatingPlayer(int targetId)
    {
        // Set spectate target
        _veilseerSpectateTargetPlayerId = targetId;
        _veilseerSpectateSlot = -1; // Not using slot-based spectating
        
        // Show spectate popup
        var targetName = ResolvePlayerName(targetId);
        _veilseerSpectatePopupText = $"Spectating {targetName}";
        _veilseerSpectatePopupTimer = 3f;
    }

    private void StopSpectatingPlayer()
    {
        if (HasActiveRemoteInventoryView())
        {
            var targetId = _currentLiveInventoryTarget;
            ResetLiveInventoryMirrorState(targetId);
            _currentLiveInventoryTarget = -1;
            _inventoryOpen = false;
        }

        ResetSpectateCameraSmoothing();
        _veilseerSpectateTargetPlayerId = -1;
        _veilseerSpectateSlot = -1;
        _veilseerSpectatePopupText = string.Empty;
        _veilseerSpectatePopupTimer = 0f;
    }

    private void DetachVeilseerFromSpectateTarget(PlayerModel? lastObservedModel = null, string? popupText = null, string? statusMessage = null, bool preserveCurrentView = false)
    {
        if (_veilseerSpectateTargetPlayerId < 0)
            return;

        if (preserveCurrentView && lastObservedModel != null)
        {
            _player.Position = lastObservedModel.Position;
            _player.Yaw = lastObservedModel.Yaw;
            _player.Pitch = lastObservedModel.Pitch;
        }

        StopSpectatingPlayer();

        if (popupText != null)
            SetVeilseerSpectatePopup(popupText);
        if (!string.IsNullOrWhiteSpace(statusMessage))
            SetCommandStatus(statusMessage, 3f);
    }

    private void RequestInventoryView(int targetId, bool openUi)
    {
        if (_lanSession == null)
            return;

        if (!HasOperatorPermissions())
            return;

        if (_gameMode != GameMode.Veilseer)
            return;

        var localId = _lanSession.LocalPlayerId;
        var previousTargetId = _currentLiveInventoryTarget;
        if (previousTargetId >= 0 && previousTargetId != targetId)
        {
            if (_lanSession.IsConnected)
            {
                _lanSession.SendChat(new LanChatMessage
                {
                    FromPlayerId = localId,
                    ToPlayerId = -1,
                    Kind = LanChatKind.System,
                    Text = InventoryViewClosePrefix + previousTargetId,
                    TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
                });
            }

            ResetLiveInventoryMirrorState(previousTargetId);
        }

        _inventoryViewTargetByViewer[localId] = targetId;
        _inventoryViewPushAccumulator[localId] = 0f; // Reset accumulator to send immediately
        
        // Set current live inventory target
        _currentLiveInventoryTarget = targetId;
        _liveInventoryTargetPlayerId = targetId;
        _liveInventoryTargetName = ResolvePlayerName(targetId);
        _liveInventoryViewActive = true;
        _liveInventoryAutoSpectate = true;
        
        // Open inventory UI to show live view
        if (openUi && !_inventoryOpen)
        {
            _inventoryOpen = true;
        }

        if (_lanSession.IsConnected)
        {
            _lanSession.SendChat(new LanChatMessage
            {
                FromPlayerId = _lanSession.LocalPlayerId,
                ToPlayerId = -1,
                Kind = LanChatKind.System,
                Text = InventoryViewRequestPrefix + targetId,
                TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
            });
        }
    }

    private void UpdateLiveInventoryDisplay(LanInventoryView inventoryView)
    {
        _liveInventoryViews[inventoryView.TargetPlayerId] = inventoryView;
    }

    private void ForwardClientInventoryViewToViewers(LanInventoryView inventoryView)
    {
        if (_lanSession == null || !_lanSession.IsConnected || !_lanSession.IsHost)
            return;

        // Client-to-host updates come in as ViewerPlayerId == TargetPlayerId (the client itself).
        // Forward to any viewer currently requesting this target.
        foreach (var pair in _inventoryViewTargetByViewer)
        {
            var viewerId = pair.Key;
            var targetId = pair.Value;
            if (targetId != inventoryView.TargetPlayerId)
                continue;

            var forwarded = new LanInventoryView
            {
                ViewerPlayerId = viewerId,
                TargetPlayerId = inventoryView.TargetPlayerId,
                SelectedIndex = inventoryView.SelectedIndex,
                HotbarIds = inventoryView.HotbarIds,
                HotbarCounts = inventoryView.HotbarCounts,
                GridIds = inventoryView.GridIds,
                GridCounts = inventoryView.GridCounts
            };

            _lanSession.SendInventoryView(forwarded);
        }
    }

    private void ExecuteCommandClearCommand(string[] _)
    {
        var removed = _textInputHistory.RemoveAll(x => x.StartsWith("/", StringComparison.Ordinal));
        _textInputHistoryBrowsing = false;
        _textInputHistoryCursor = _textInputHistory.Count;
        _textInputHistoryDraft = _chatInputActive ? _chatInputText : _commandInputText;
        TruncateHistoryFile(CommandHistoryLogPath);
        SetCommandStatus(removed > 0
            ? $"Cleared {removed} command history entr{(removed == 1 ? "y" : "ies")}."
            : "No command history entries to clear.");
    }

    private bool TryResolvePlayerTarget(string token, out int playerId, out string name)
    {
        playerId = -1;
        name = string.Empty;
        token = (token ?? string.Empty).Trim();
        if (token.Length == 0)
            return false;

        var localId = _lanSession?.LocalPlayerId ?? 0;
        var localName = (_profile.GetDisplayUsername() ?? string.Empty).Trim();

        if (int.TryParse(token, NumberStyles.Integer, CultureInfo.InvariantCulture, out var byId))
        {
            if (_playerNames.TryGetValue(byId, out var byIdName))
            {
                playerId = byId;
                name = byIdName;
                return true;
            }

            if (byId == localId)
            {
                playerId = localId;
                name = !string.IsNullOrWhiteSpace(localName) ? localName : ResolvePlayerName(localId);
                return true;
            }
        }

        if (string.Equals(token, "@s", StringComparison.OrdinalIgnoreCase)
            || string.Equals(token, "self", StringComparison.OrdinalIgnoreCase)
            || string.Equals(token, "me", StringComparison.OrdinalIgnoreCase))
        {
            playerId = localId;
            name = !string.IsNullOrWhiteSpace(localName) ? localName : ResolvePlayerName(localId);
            return true;
        }

        if (!string.IsNullOrWhiteSpace(localName) && string.Equals(localName, token, StringComparison.OrdinalIgnoreCase))
        {
            playerId = localId;
            name = localName;
            return true;
        }

        if (!string.IsNullOrWhiteSpace(localName)
            && localName.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0)
        {
            playerId = localId;
            name = localName;
            return true;
        }

        foreach (var entry in _playerNames)
        {
            if (string.Equals(entry.Value, token, StringComparison.OrdinalIgnoreCase))
            {
                playerId = entry.Key;
                name = entry.Value;
                return true;
            }
        }

        foreach (var entry in _playerNames)
        {
            if (string.IsNullOrWhiteSpace(entry.Value))
                continue;
            if (entry.Value.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0)
            {
                playerId = entry.Key;
                name = entry.Value;
                return true;
            }
        }

        return false;
    }

    private bool TryResolveOperatorToken(string token, out string operatorName, out string operatorAuthorityId)
    {
        operatorName = string.Empty;
        operatorAuthorityId = string.Empty;
        if (TryResolvePlayerTarget(token, out var playerId, out var resolved))
        {
            token = resolved;
            operatorAuthorityId = ResolvePlayerAuthorityId(playerId);
        }

        var normalized = NormalizeIdentityToken(token);
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        if (HasAuthenticatedAuthorityMode() && string.IsNullOrWhiteSpace(operatorAuthorityId))
            return false;

        operatorName = normalized;
        return true;
    }

    private static string NormalizeIdentityToken(string? raw)
    {
        return (raw ?? string.Empty).Trim();
    }

    private string ResolvePersistenceUsername(int playerId, string? primary, string? secondary)
    {
        var candidates = new[]
        {
            NormalizeIdentityToken(primary),
            NormalizeIdentityToken(secondary),
            _playerNames.TryGetValue(playerId, out var mapped) ? NormalizeIdentityToken(mapped) : string.Empty,
            NormalizeIdentityToken(ResolvePlayerName(playerId))
        };

        for (var i = 0; i < candidates.Length; i++)
        {
            var candidate = candidates[i];
            if (string.IsNullOrWhiteSpace(candidate))
                continue;
            if (IsGeneratedPlayerPlaceholder(candidate))
                continue;

            return candidate;
        }

        for (var i = 0; i < candidates.Length; i++)
        {
            var candidate = candidates[i];
            if (!string.IsNullOrWhiteSpace(candidate))
                return candidate;
        }

        return string.Empty;
    }

    private static string NormalizeDeathType(string? rawValue)
    {
        var token = (rawValue ?? string.Empty).Trim().ToLowerInvariant();
        return token switch
        {
            "body" or "corpse" => "body",
            "itemdrop" or "itemdrops" or "drop" or "drops" => "itemdrop",
            _ => "soul"
        };
    }

    private static string NormalizeInventoryRuleValue(string? rawValue)
    {
        var token = (rawValue ?? string.Empty).Trim().ToLowerInvariant();
        return token switch
        {
            "keep" or "save" or "saved" => "keep",
            "drop" or "itemdrop" or "itemdrops" or "drops" => "drop",
            "body" or "corpse" => "body",
            "soul" or "soulmarker" => "soul",
            _ => string.Empty
        };
    }

    private string GetInventoryRuleValue()
    {
        if (_saveInventoryEnabled)
            return "keep";

        return NormalizeDeathType(_deathType) switch
        {
            "itemdrop" => "drop",
            "body" => "body",
            _ => "soul"
        };
    }

    private static bool IsGeneratedPlayerPlaceholder(string candidate)
    {
        if (!candidate.StartsWith("Player", StringComparison.OrdinalIgnoreCase))
            return false;

        var suffix = candidate.Substring("Player".Length);
        return int.TryParse(suffix, out _);
    }

    private void LoadOperatorsFromMeta()
    {
        _operators.Clear();
        _operatorAuthorityIds.Clear();

        var operatorNames = (_meta?.OperatorUsernames ?? new List<string>()).ToArray();
        for (var i = 0; i < operatorNames.Length; i++)
        {
            var normalized = NormalizeIdentityToken(operatorNames[i]);
            if (!string.IsNullOrWhiteSpace(normalized))
                _operators.Add(normalized);
        }

        var operatorIds = (_meta?.OperatorIdentityIds ?? _meta?.Gameplay?.OperatorIdentityIds ?? new List<string>()).ToArray();
        for (var i = 0; i < operatorIds.Length; i++)
        {
            var normalized = NormalizeIdentityToken(operatorIds[i]);
            if (!string.IsNullOrWhiteSpace(normalized))
                _operatorAuthorityIds.Add(normalized);
        }
    }

    private void PersistOperatorsToMeta()
    {
        if (_meta == null)
            return;

        _meta.OperatorUsernames = _operators
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
            .ToList();
        _meta.OperatorIdentityIds = _operatorAuthorityIds
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(id => id, StringComparer.OrdinalIgnoreCase)
            .ToList();
        _meta.Save(_metaPath, _log);
    }

    private void BroadcastOperatorSyncState()
    {
        if (_lanSession == null || !_lanSession.IsConnected || !_lanSession.IsHost)
            return;

        var payload = BuildOperatorSyncPayload();
        _lanSession.SendChat(new LanChatMessage
        {
            FromPlayerId = _lanSession.LocalPlayerId,
            ToPlayerId = -1,
            Kind = LanChatKind.System,
            Text = payload,
            TimestampUtc = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()
        });
    }

    private string BuildOperatorSyncPayload()
    {
        var payloadNames = _operators
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
            .Select(name => "n:" + Uri.EscapeDataString(name));
        var payloadIds = _operatorAuthorityIds
            .Where(id => !string.IsNullOrWhiteSpace(id))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(id => id, StringComparer.OrdinalIgnoreCase)
            .Select(id => "id:" + Uri.EscapeDataString(id));
        var payloadEntries = payloadNames
            .Concat(payloadIds)
            .ToArray();
        return OperatorSyncPrefix + string.Join("|", payloadEntries);
    }

    private bool TryHandleOperatorSyncMessage(LanChatMessage message)
    {
        if (message.Kind != LanChatKind.System)
            return false;
        if (message.FromPlayerId != 0)
            return false;

        var text = message.Text ?? string.Empty;
        if (!text.StartsWith(OperatorSyncPrefix, StringComparison.Ordinal))
            return false;

        var payload = text.Substring(OperatorSyncPrefix.Length);
        _operators.Clear();
        _operatorAuthorityIds.Clear();
        if (!string.IsNullOrWhiteSpace(payload))
        {
            var entries = payload.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            for (var i = 0; i < entries.Length; i++)
            {
                var entry = entries[i];
                if (entry.StartsWith("id:", StringComparison.Ordinal))
                {
                    var normalizedAuthorityId = NormalizeIdentityToken(Uri.UnescapeDataString(entry["id:".Length..]));
                    if (!string.IsNullOrWhiteSpace(normalizedAuthorityId))
                        _operatorAuthorityIds.Add(normalizedAuthorityId);
                    continue;
                }

                var encodedName = entry.StartsWith("n:", StringComparison.Ordinal)
                    ? entry["n:".Length..]
                    : entry;
                var normalizedName = NormalizeIdentityToken(Uri.UnescapeDataString(encodedName));
                if (!string.IsNullOrWhiteSpace(normalizedName))
                    _operators.Add(normalizedName);
            }
        }

        return true;
    }

    private bool TryHandleGameModeSyncMessage(LanChatMessage message)
    {
        if (_lanSession == null || message.Kind != LanChatKind.System)
            return false;
        if (message.FromPlayerId != 0)
            return false;

        var text = message.Text ?? string.Empty;
        if (!text.StartsWith(GameModeSyncPrefix, StringComparison.Ordinal))
            return false;

        var payload = text.Substring(GameModeSyncPrefix.Length);
        var parts = payload.Split('|', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries);
        if (parts.Length < 2)
            return true;

        if (!int.TryParse(parts[0], out var targetId))
            return true;
        if (!TryParseGameModeToken(parts[1], out var mode))
            return true;

        if (targetId != _lanSession.LocalPlayerId)
            return true;

        ApplyGameModeChange(mode, GameModeChangeSource.Command, persistImmediately: _lanSession.IsHost, emitFeedback: true);
        return true;
    }

    private bool TryCanPlayerEditRules(int playerId)
    {
        if (_lanSession == null)
            return true;
        if (playerId == _lanSession.LocalPlayerId)
            return HasOperatorPermissions();

        return HasStoredOperatorAuthority(playerId, ResolvePlayerName(playerId));
    }

